// NEW HSK 3.0 Cap 3 - Goi du lieu tai theo yeu cau (Day du: Bai 1-18)
const HSK30_3_FULL_DATA = {"1":{"pages":"1–9","titleZh":"我们去机场接你们","titlePy":"Wǒmen qù jīchǎng jiē nǐmen","titleVi":"Anh chị sẽ đến sân bay đón các em","goals":["能听懂并使用多项定语描述人或事物的特征。Có khả năng nghe hiểu và sử dụng được định ngữ đa tầng để miêu tả đặc điểm của người hoặc sự vật.","能听懂并解决物品丢失的问题。Có khả năng nghe hiểu và giải quyết các vấn đề liên quan đến việc thất lạc đồ vật.","掌握疑问代词的用法，能表达不确定的人、事物或地方等信息。Nắm vững cách sử dụng đại từ nghi vấn để diễn đạt thông tin về người, sự vật hoặc địa điểm không xác định."],"words":[{"zh":"以为","py":"yǐwéi","vi":"cho rằng, nghĩ rằng","pos":"đgt."},{"zh":"像","py":"xiàng","vi":"giống, giống như","pos":"đgt."},{"zh":"长","py":"zhǎng","vi":"phát triển, lớn lên","pos":"đgt."},{"zh":"身高","py":"shēngāo","vi":"chiều cao","pos":"dt."},{"zh":"米","py":"mǐ","vi":"mét (đơn vị đo lường)","pos":"lượng."},{"zh":"瘦","py":"shòu","vi":"gầy, ốm","pos":"tt."},{"zh":"接","py":"jiē","vi":"đón","pos":"đgt."},{"zh":"行李","py":"xíngli","vi":"hành lý","pos":"dt."},{"zh":"丢","py":"diū","vi":"làm mất, bị mất","pos":"đgt."},{"zh":"箱子","py":"xiāngzi","vi":"va li","pos":"dt."},{"zh":"号码","py":"hàomǎ","vi":"số, mã số","pos":"dt."},{"zh":"好像","py":"hǎoxiàng","vi":"dường như, có vẻ như","pos":"phó."},{"zh":"重要","py":"zhòngyào","vi":"quan trọng","pos":"tt."},{"zh":"着急","py":"zháojí","vi":"lo lắng, sốt ruột","pos":"tt."},{"zh":"护照","py":"hùzhào","vi":"hộ chiếu","pos":"dt."},{"zh":"服务台","py":"fúwùtái","vi":"quầy phục vụ","pos":"dt."},{"zh":"应该","py":"yīnggāi","vi":"nên","pos":"đtnn."},{"zh":"站","py":"zhàn","vi":"đứng","pos":"đgt."},{"zh":"中间","py":"zhōngjiān","vi":"ở giữa, trung gian","pos":"dt."},{"zh":"短","py":"duǎn","vi":"ngắn","pos":"tt."},{"zh":"头发","py":"tóufa","vi":"tóc","pos":"dt."},{"zh":"年轻","py":"niánqīng","vi":"trẻ, trẻ tuổi","pos":"tt."},{"zh":"发现","py":"fāxiàn","vi":"phát hiện, tìm thấy","pos":"đgt."},{"zh":"不见","py":"bújiàn","vi":"bị mất, không thấy","pos":"đgt."},{"zh":"带","py":"dài","vi":"mang, dẫn, đưa","pos":"đgt."},{"zh":"帮助","py":"bāngzhù","vi":"giúp, giúp đỡ","pos":"đgt."},{"zh":"照片","py":"zhàopiàn","vi":"ảnh (chụp)","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，刘明和王一雪在沙发上聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trên ghế sofa ở trong nhà.","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这是杨同乐吗？他怎么跟白家月在一起？","py":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?","vi":"Đây có phải là Dương Đồng Lạc không nhỉ? Sao em ấy lại đi cùng Bạch Gia Nguyệt thế?"},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"他不是杨同乐，他叫李文，是白家月的好朋友。","py":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou.","vi":"Em ấy không phải là Dương Đồng Lạc đâu. Em ấy tên là Lý Văn, là bạn thân của Bạch Gia Nguyệt."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我还以为是同乐呢，他们看上去有点儿像。","py":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Anh cứ tưởng là Đồng Lạc, trông họ hơi giống nhau."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是长得有点儿像，但是他比同乐高，身高有一米八。","py":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","vi":"Đúng là hơi giống thật, nhưng em ấy cao hơn Đồng Lạc, cao khoảng 1m8."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"看起来也比同乐瘦一点儿。","py":"Kàn qǐlái yě bǐ Tónglè shòu yìdiǎnr.","vi":"Xem ra cũng có vẻ gầy hơn Đồng Lạc một chút."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"下个星期家月和李文要来北京，我去机场接他们。","py":"Xià gè xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen.","vi":"Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh vào tuần tới. Em định đi đón các em ấy ở sân bay."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"他们哪天到北京？我跟你一起去机场接他们吧。","py":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba.","vi":"Các em ấy đến vào ngày nào? Anh sẽ đi đón cùng em."},{"section":"Bài khóa 2","context":"在机场，李文和白家月在行李领取处。Lý Văn và Bạch Gia Nguyệt đang ở khu vực nhận hành lý tại sân bay.","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我的行李怎么还没出来？是不是丢了？","py":"Wǒ de xíngli zěnme hái méi chūlai? Shì bu shì diū le?","vi":"Sao hành lý của em vẫn chưa thấy đâu nhỉ? Liệu có bị thất lạc không nhỉ?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"你的行李箱是什么样的？","py":"Nǐ de xínglixiāng shì shénme yàng de?","vi":"Va li của em trông như thế nào?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"是一个黑色的箱子，上面写着我的名字和电话号码。","py":"Shì yí gè hēisè de xiāngzi, shàngmian xiězhe wǒ de míngzi hé diànhuà hàomǎ.","vi":"Là một chiếc va li màu đen, trên đó có ghi tên em và số điện thoại."},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","py":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bu shì yǒu rén ná cuò le?","vi":"Hình như anh đã nhìn thấy một cái giống như vậy ở đâu đó rồi, hay ai đó đã lấy nhầm mất rồi?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我们快找谁问一下吧，箱子里有不少重要的东西。","py":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi li yǒu bù shǎo zhòngyào de dōngxi.","vi":"Chúng ta mau tìm người để hỏi đi, trong va li có nhiều đồ quan trọng lắm."},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"别着急，我们拿着护照和机票，去服务台问问吧。","py":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","vi":"Đừng lo lắng. Chúng ta cầm theo hộ chiếu và vé máy bay đến quầy phục vụ để hỏi xem sao."},{"section":"Bài khóa 3","context":"在机场大厅，刘明和王一雪接机。Lưu Minh và Vương Nhất Tuyết đang đón người tại sảnh sân bay.","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"飞机早就到了，你看见白家月他们了吗？","py":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?","vi":"Máy bay đã hạ cánh từ lâu rồi. Em đã nhìn thấy Bạch Gia Nguyệt và Lý Văn chưa?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"没有，他们应该快出来了。","py":"Méiyǒu, tāmen yīnggāi kuài chūlai le.","vi":"Chưa ạ, chắc các em ấy sẽ ra ngay bây giờ thôi."},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我们站到中间去吧，这样他们好找一些。","py":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē.","vi":"Chúng ta đứng ra giữa đi, như vậy các em ấy sẽ dễ nhìn thấy hơn."},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你看那个高个子的人是李文吗？","py":"Nǐ kàn nàge gāo gèzi de rén shì Lǐ Wén ma?","vi":"Anh nhìn xem, có phải chàng trai cao cao kia là Lý Văn không?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","py":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén?","vi":"Em nói người nào vậy? Chàng trai tóc ngắn, mặc đồ đen kia phải không?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对，那个人就是李文！你看，家月在他后面呢。","py":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumian ne.","vi":"Đúng rồi, người đó chính là Lý Văn! Anh nhìn kìa, Gia Nguyệt ở ngay phía sau em ấy."},{"section":"Bài khóa 4","context":"在宾馆房间，李文在写日记。Lý Văn đang viết nhật ký ở trong phòng khách sạn.","audio":"01-7.mp3","speaker":"李文","name":"Lý Văn","zh":"昨天我到北京了。虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。晚上，一雪姐带我们去吃了一家很好吃的中国菜。","py":"Zuótiān wǒ dào Běijīng le. Suīrán lùshang huāle shí jǐ gè xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài. Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodàole xínglixiāng. Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlai jiù kànjiànle Wáng lǎoshī de jiějie, tā kàn qǐlái bǐ zhàopiàn shang niánqīng. Wǎnshang, Yīxuě jiě dài wǒmen qù chīle yì jiā hěn hǎochī de Zhōngguó cài.","vi":"Hôm qua tôi đã đến Bắc Kinh. Mặc dù trải qua hành trình hơn mười tiếng đồng hồ, nhưng vì ngồi cạnh Gia Nguyệt nên tôi cảm thấy thời gian trôi qua rất nhanh. Khi đến sân bay, Gia Nguyệt phát hiện va li của mình không thấy đâu, tôi đã đưa cô ấy đến quầy phục vụ, giúp cô ấy tìm lại va li. Đến lúc chúng tôi rời sân bay thì đã hơn 8 giờ tối. Khi vừa bước ra ngoài, chúng tôi liền nhìn thấy chị gái của cô Vương, chị ấy trông trẻ hơn so với trong ảnh. Buổi tối, chị Nhất Tuyết đã đưa chúng tôi đi ăn món Trung Quốc rất ngon."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定短语“看上去/看起来”","py":"Gùdìng duǎnyǔ “kàn shàngqu/kàn qǐlái”","title":"Cụm từ cố định “看上去/看起来”","explain":"固定短语“看上去”与“看起来”，可用来描述某人或某物的外观或状态。\nCụm từ cố định “看上去” và “看起来” có thể được sử dụng để miêu tả ngoại hình hoặc trạng thái của người hoặc sự vật.","examples":[{"zh":"他们看上去有点儿像。","py":"Tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Trông họ hơi giống nhau.","hl":"看上去"},{"zh":"这些菜看起来都很好吃。","py":"Zhèxiē cài kàn qǐlái dōu hěn hǎochī.","vi":"Những món ăn này trông đều rất ngon.","hl":"看起来"},{"zh":"那个新来的老师看上去很年轻。","py":"Nàge xīn lái de lǎoshī kàn shàngqu hěn niánqīng.","vi":"Thầy/cô giáo mới đến kia trông rất trẻ.","hl":"看上去"}],"struct":"Chủ ngữ + 看上去 / 看起来 + Tính từ / Cụm động từ","note":"Dùng để nêu nhận xét, đánh giá qua quan sát bề ngoài."},"g2":{"han":"疑问代词的非疑问用法（1）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (1)","title":"Cách dùng linh hoạt của đại từ nghi vấn (1)","explain":"疑问代词“哪儿”、“什么”、“谁”、“哪”等用在陈述句中，表示不知道或不需要指明的地点、事物或人等。\nCác đại từ nghi vấn như “哪儿”, “什么”, “谁”, “哪” dùng trong câu trần thuật biểu thị những địa điểm, sự vật hoặc con người không biết hoặc không cần chỉ rõ.","examples":[{"zh":"我好像在哪儿看到过这个箱子。","py":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi.","vi":"Hình như anh đã từng nhìn thấy chiếc va li này ở đâu đó rồi.","hl":"哪儿"},{"zh":"你吃点儿什么再走吧。","py":"Nǐ chī diǎnr shénme zài zǒu ba.","vi":"Bạn ăn chút gì đó rồi hãy đi.","hl":"什么"},{"zh":"我们哪天一起去踢足球吧。","py":"Wǒmen nǎ tiān yìqǐ qù tī zúqiú ba.","vi":"Hôm nào chúng ta cùng đi đá bóng nhé.","hl":"哪天"}],"struct":"Câu trần thuật chứa 哪儿 / 什么 / 谁 / 哪 (+ lượng từ) (phiếm chỉ)","note":"Mang nghĩa phiếm chỉ: ở đâu đó, cái gì đó, ai đó, ngày nào đó."},"g3":{"han":"多项定语","py":"Duōxiàng dìngyǔ","title":"Định ngữ đa tầng","explain":"名词性中心语的前面可以同时有多个定语，这些定语一般按照时间/处所、动作/状态、特点的顺序进行排列，数量短语或指量短语位置比较灵活，可以放在表示动作或状态的定语的前面或者后面。\nTrước trung tâm ngữ danh từ có thể cùng xuất hiện nhiều định ngữ. Các định ngữ này thường được sắp xếp theo trật tự như sau: thời gian/địa điểm → hành động/trạng thái → đặc điểm; trong đó, cụm từ chỉ số lượng hoặc cụm từ chỉ lượng có vị trí tương đối linh hoạt, có thể đặt trước hoặc sau định ngữ biểu thị hành động hoặc trạng thái.","examples":[{"zh":"李文是那个穿着黑衣服的短头发的年轻人吗？","py":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén ma?","vi":"Lý Văn có phải là chàng trai trẻ tóc ngắn mặc áo đen kia không?","hl":"那个穿着黑衣服的短头发的"},{"zh":"昨天和家月一起看电影的两个人是我的朋友。","py":"Zuótiān hé Jiāyuè yìqǐ kàn diànyǐng de liǎng gè rén shì wǒ de péngyou.","vi":"Hai người hôm qua cùng xem phim với Gia Nguyệt là bạn của tôi.","hl":"昨天和家月一起看电影的两个人"},{"zh":"我那件新买的白色的衣服在哪儿？","py":"Wǒ nà jiàn xīn mǎi de báisè de yīfu zài nǎr?","vi":"Chiếc áo màu trắng mới mua của tôi ở đâu rồi?","hl":"我那件新买的白色的"}],"struct":"(Thời gian/Nơi chốn) + (Sở hữu/Chỉ thị/Số lượng) + Động tác/Trạng thái + Đặc điểm + (的) + Trung tâm ngữ","note":"Sắp xếp từ phạm vi lớn/xa đến gần/gắn với tính chất cốt lõi của danh từ trung tâm."}},"grammarQuiz":[{"id":"hsk3_b1_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"服务台 (____) 在前面，我们过去问问吧。","opts":[{"t":"应该","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false}],"exp":"Đáp án E (应该): ‘Quầy phục vụ chắc là ở phía trước, chúng ta qua hỏi thử xem.’"},{"id":"hsk3_b1_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他已经到了，我们快出去 (____) 他吧。","opts":[{"t":"接","ok":true},{"t":"带","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án B (接): ‘Anh ấy đến rồi, chúng ta mau ra đón anh ấy đi.’"},{"id":"hsk3_b1_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我的护照不见了，是不是在机场 (____) 了？","opts":[{"t":"丢","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án C (丢): ‘Hộ chiếu của tôi không thấy đâu, có phải làm mất ở sân bay rồi không?’"},{"id":"hsk3_b1_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"行李票很 (____)，你们出机场的时候有人看。","opts":[{"t":"重要","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án D (重要): ‘Cuống vé hành lý rất quan trọng, lúc các bạn ra khỏi sân bay sẽ có người kiểm tra.’"},{"id":"hsk3_b1_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 了两个行李箱和一个大包，所以走得非常慢。","opts":[{"t":"带","ok":true},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án A (带): ‘Tôi mang theo hai chiếc va li và một túi lớn nên đi rất chậm.’"},{"id":"hsk3_b1_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个头发很短的男孩儿是我弟弟。\nB: 我 (____) 这个是你，你们长得太像了。","opts":[{"t":"以为","ok":true},{"t":"发现","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án B (以为): ‘Tôi cứ tưởng người này là bạn, hai người trông giống nhau quá.’"},{"id":"hsk3_b1_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我 (____) 坐飞机来北京的人非常多。\nB: 对，很多人这个时候来北京旅游。","opts":[{"t":"发现","ok":true},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án A (发现): ‘Tôi nhận thấy người đi máy bay đến Bắc Kinh rất đông.’"},{"id":"hsk3_b1_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这是我和哥哥的照片，你看我们像吗？\nB: 你们很像，你哥哥看起来也很 (____)。","opts":[{"t":"年轻","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án D (年轻): ‘Hai người rất giống nhau, anh trai bạn trông cũng rất trẻ.’"},{"id":"hsk3_b1_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你的行李箱找到了，你看看是不是这个？\nB: 对，太好了！谢谢您的 (____)。","opts":[{"t":"帮助","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false}],"exp":"Đáp án E (帮助): ‘Đúng rồi, tuyệt quá! Cảm ơn sự giúp đỡ của ngài.’"},{"id":"hsk3_b1_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 那个穿着黑衣服的高个子的人是王老师吗？\nB: (____) 是吧，我也不知道。","opts":[{"t":"好像","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án C (好像): ‘Hình như là vậy, tôi cũng không rõ.’"},{"id":"hsk3_b1_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"刘明和王一雪在做什么？","opts":[{"t":"B 看手机","ok":true},{"t":"A 看电视","ok":false},{"t":"C 去机场","ok":false}],"exp":"Trong tranh Bài khóa 1: Hai người đang ngồi trên ghế sofa xem điện thoại."},{"id":"hsk3_b1_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"刘明跟王一雪一起去机场做什么？","opts":[{"t":"C 接白家月","ok":true},{"t":"A 坐飞机","ok":false},{"t":"B 找朋友","ok":false}],"exp":"Lưu Minh nói: “我跟你一起去机场接他们吧” (đón Bạch Gia Nguyệt và Lý Văn)."},{"id":"hsk3_b1_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月在机场做什么？","opts":[{"t":"A 等箱子","ok":true},{"t":"B 等同学","ok":false},{"t":"C 等王一雪","ok":false}],"exp":"Hai người đang đứng ở khu nhận hành lý đợi va li ra."},{"id":"hsk3_b1_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"白家月为什么很着急？","opts":[{"t":"B 行李箱丢了","ok":true},{"t":"A 护照丢了","ok":false},{"t":"C 拿错行李箱了","ok":false}],"exp":"Bạch Gia Nguyệt lo hành lý bị thất lạc vì trong va li có nhiều đồ quan trọng."},{"id":"hsk3_b1_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘明和王一雪在机场做什么？","opts":[{"t":"A 接人","ok":true},{"t":"B 坐飞机","ok":false},{"t":"C 找行李箱","ok":false}],"exp":"Hai người đang đợi ở sảnh sân bay để đón Bạch Gia Nguyệt và Lý Văn."},{"id":"hsk3_b1_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘明为什么要站到中间？","opts":[{"t":"C 白家月好找他们","ok":true},{"t":"A 旁边人太多了","ok":false},{"t":"B 他看见白家月了","ok":false}],"exp":"Lưu Minh nói: “我们站到中间去吧，这样他们好找一些。”"},{"id":"hsk3_b1_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文回北京的路上花了多长时间？","opts":[{"t":"B 十几个小时","ok":true},{"t":"A 几个小时","ok":false},{"t":"C 几十个小时","ok":false}],"exp":"Bài khóa 4: “虽然路上花了十几个小时...”"},{"id":"hsk3_b1_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文觉得王老师的姐姐看起来怎么样？","opts":[{"t":"B 很年轻","ok":true},{"t":"A 很累","ok":false},{"t":"C 很像王老师","ok":false}],"exp":"Bài khóa 4: “她看起来比照片上年轻。”"}],"chars":["以","为","像","长","身","高","米","瘦","接","行","李","丢","箱","子","号","码","好","重","要","着","急","护","照","服","务","台","应","该","站","中","间","短","头","发","年","轻","现","不","见","带","帮","助","片","我","们","去","机","场","你"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 刘明为什么以为李文是杨同乐？ (2) 李文长什么样？ (3) 白家月什么时候来中国？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月的箱子是什么样的？ (2) 李文看到过白家月的箱子吗？ (3) 他们现在要做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪为什么说白家月他们应该快出来了？ (2) 刘明看见的年轻人长什么样？ (3) 王一雪怎么知道那个年轻人就是李文？","Câu hỏi thảo luận Bài khóa 4: (1) 李文为什么觉得时间过得很快？ (2) 到机场的时候，白家月发现了什么问题？ (3) 王一雪带他们去做什么了？"],"workbook":null},"2":{"pages":"10–18","titleZh":"你们想吃什么就点什么","titlePy":"Nǐmen xiǎng chī shénme jiù diǎn shénme","titleVi":"Các em muốn ăn món gì thì gọi món đó","goals":["能听懂并谈论餐厅的菜品、服务和个人的饮食习惯。Có khả năng nghe hiểu và trao đổi về món ăn trong nhà hàng, dịch vụ và thói quen ẩm thực của cá nhân.","能听懂并使用疑问代词指代任何一个对象。Có khả năng nghe hiểu và sử dụng đại từ nghi vấn để chỉ bất kỳ đối tượng nào.","了解中国人就餐时使用的餐具。Hiểu về dụng cụ ăn uống mà người Trung Quốc sử dụng khi dùng bữa."],"words":[{"zh":"菜单","py":"càidān","vi":"thực đơn","pos":"dt."},{"zh":"又","py":"yòu","vi":"lại, vừa","pos":"phó."},{"zh":"饿","py":"è","vi":"đói","pos":"tt."},{"zh":"渴","py":"kě","vi":"khát","pos":"tt."},{"zh":"客气","py":"kèqi","vi":"khách sáo, khách khí","pos":"đgt./tt."},{"zh":"饮料","py":"yǐnliào","vi":"đồ uống","pos":"dt."},{"zh":"好久","py":"hǎojiǔ","vi":"lâu, rất lâu","pos":"tt."},{"zh":"服务","py":"fúwù","vi":"phục vụ","pos":"đgt."},{"zh":"员","py":"yuán","vi":"đặt sau danh từ hoặc động từ để chỉ người","pos":"htố."},{"zh":"双","py":"shuāng","vi":"đôi","pos":"lượng."},{"zh":"筷子","py":"kuàizi","vi":"đũa","pos":"dt."},{"zh":"勺子","py":"sháozi","vi":"thìa","pos":"dt."},{"zh":"碗","py":"wǎn","vi":"bát","pos":"dt."},{"zh":"马上","py":"mǎshàng","vi":"lập tức, ngay lập tức","pos":"phó."},{"zh":"热情","py":"rèqíng","vi":"nhiệt tình","pos":"tt."},{"zh":"尝","py":"cháng","vi":"nếm, thử","pos":"đgt."},{"zh":"记","py":"jì","vi":"nhớ, ghi nhớ","pos":"đgt."},{"zh":"用","py":"yòng","vi":"dùng, sử dụng","pos":"đgt."},{"zh":"鸡","py":"jī","vi":"gà","pos":"dt."},{"zh":"张","py":"zhāng","vi":"tờ, bức (dùng cho giấy, tranh...)","pos":"lượng."},{"zh":"不用","py":"búyòng","vi":"không cần","pos":"phó."},{"zh":"选","py":"xuǎn","vi":"chọn, lựa chọn","pos":"đgt."},{"zh":"外卖","py":"wàimài","vi":"đồ ăn giao tận nơi, đặt đồ ăn giao tận nơi","pos":"dt./đgt."},{"zh":"方便","py":"fāngbiàn","vi":"thuận tiện, tiện lợi","pos":"tt."},{"zh":"蛋糕","py":"dàngāo","vi":"bánh ngọt, bánh kem, bánh ga tô","pos":"dt."},{"zh":"只","py":"zhǐ","vi":"chỉ","pos":"phó."},{"zh":"方便面","py":"fāngbiànmiàn","vi":"mì ăn liền","pos":"dt."},{"zh":"简单","py":"jiǎndān","vi":"đơn giản","pos":"tt."}],"dialog":[{"section":"Bài khóa 1","context":"在饭馆，王一雪、刘明、白家月和李文在点菜。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang gọi món tại nhà hàng.","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月、李文，你们看看菜单，想吃点儿什么？","py":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?","vi":"Gia Nguyệt, Lý Văn, hai em xem thực đơn đi, muốn ăn món gì vậy?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"李文","name":"Lý Văn","zh":"谢谢一雪姐，我都可以，你们点吧。","py":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba.","vi":"Cảm ơn chị Nhất Tuyết, em ăn gì cũng được, chị gọi món đi ạ."},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"飞了这么远，现在还真是又饿又渴。","py":"Fēile zhème yuǎn, xiànzài hái zhēn shì yòu è yòu kě.","vi":"Sau chuyến bay dài như vậy, em thực sự vừa đói vừa khát."},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那多点点儿，别客气。你们喝什么饮料？","py":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?","vi":"Vậy thì hãy gọi nhiều một chút, đừng ngại nhé. Các em muốn uống gì nào?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","py":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?","vi":"Lâu rồi em không được uống trà Trung Quốc, cũng lâu lắm rồi không được ăn sủi cảo. Em muốn uống trà xanh và ăn sủi cảo, có được không chị?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"没问题。你们看看还想吃什么。","py":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme.","vi":"Không vấn đề gì. Các em xem có còn muốn dùng thêm gì nữa không nhé."},{"section":"Bài khóa 2","context":"在饭馆，王一雪、刘明、白家月和李文一起吃饭。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang ăn cùng nhau tại nhà hàng.","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","py":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí gè sháozi hé yí gè wǎn.","vi":"Em ơi, cho chị xin thêm một đôi đũa, một cái thìa và một cái bát nhé."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"好的，请等一下，我马上去拿。","py":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná.","vi":"Vâng ạ. Xin vui lòng đợi một lát, em sẽ mang ra ngay."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","py":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài.","vi":"Nhà hàng này phục vụ rất nhiệt tình, các món ăn đều rất ngon. Các em ăn thử đi, xem có thích những món ăn này không."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"哪个菜都好吃。您点的这些菜真不错。","py":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò.","vi":"Món nào cũng ngon cả. Những món chị gọi thực sự rất tuyệt."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","py":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le.","vi":"Đồ ăn ở đây vừa rẻ lại vừa ngon, bọn chị thường xuyên đến đây nên nhân viên phục vụ đều nhớ rõ các món yêu thích của bọn chị."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","py":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng mànyòng.","vi":"Chị Vương ơi, chị thường tới đây dùng bữa, hôm nay nhà hàng xin tặng chị một ít trái cây, chúc chị ngon miệng!"},{"section":"Bài khóa 3","context":"在饭馆，王一雪、刘明、白家月和李文继续边吃边聊。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn tiếp tục vừa ăn vừa trò chuyện trong nhà hàng.","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这个鸡肉饭太好吃了，我要再来吃一次。","py":"Zhège jīròufàn tài hǎochī le, wǒ yào zài lái chī yí cì.","vi":"Món cơm gà này ngon quá, nhất định em sẽ quay lại ăn một lần nữa."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"李文","name":"Lý Văn","zh":"你可以拿走这张菜单，看看下次还吃点儿什么。","py":"Nǐ kěyǐ názǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme.","vi":"Em có thể cầm lấy thực đơn này, xem lần tới còn muốn gọi món gì nữa."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","py":"Búyòng ná càidān, zài shǒujī shang jiù néng kàndào, yě kěyǐ xuǎnhǎo le ràng tāmen gěi nǐ sòng.","vi":"Không cần lấy thực đơn đâu, có thể xem trên điện thoại, cũng có thể chọn xong rồi bảo họ giao hàng tận nơi."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"他们家还能送外卖？","py":"Tāmen jiā hái néng sòng wàimài?","vi":"Quán này có giao đồ ăn tận nơi sao?"},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","py":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme.","vi":"Đúng vậy! Ngày nay có rất nhiều nhà hàng cung cấp dịch vụ giao đồ ăn tận nơi, muốn ăn gì thì đặt món đó."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那真是太方便了！","py":"Nà zhēn shì tài fāngbiàn le!","vi":"Vậy thì thật sự quá tiện lợi ạ!"},{"section":"Bài khóa 4","context":"在李文家，李文在写日记。Lý Văn đang viết nhật ký ở trong nhà mình.","audio":"02-7.mp3","speaker":"李文","name":"Lý Văn","zh":"这些年在国外，我很少自己做饭。早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。午饭和晚饭也都在外面吃。快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","py":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuòfàn. Zǎofàn wǒ chī yí gè miànbāo, yǒu shíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi. Wǔfàn hé wǎnfàn yě dōu zài wàimiàn chī. Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiālǐ yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎo jǐ tiān zhǐ chī fāngbiànmiàn. Xiànzài huídào Zhōngguó le, měitiān néng chīdào māma zuò de fàn, wǒ zhēn shì tài gāoxìng le! Yǒu shíhou māma zhǐ zuò jǐ gè jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī.","vi":"Ở nước ngoài mấy năm nay, tôi hiếm khi tự nấu ăn. Bữa sáng, tôi thường ăn một ổ bánh mì, đôi khi ăn một miếng bánh ngọt rồi uống một tách cà phê. Bữa trưa và bữa tối cũng đều ăn ngoài. Lúc sắp thi cử, tôi vừa bận vừa mệt, không có thời gian đi ra ngoài ăn cơm, trong nhà cũng chẳng có gì để ăn, mấy ngày liền tôi chỉ có thể ăn mì ăn liền. Bây giờ về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự rất hạnh phúc! Đôi khi mẹ chỉ làm vài món ăn đơn giản, nhưng tôi cũng rất thích ăn, bởi vì không có gì ngon bằng cơm mẹ nấu."}],"dialogQuestions":[],"grammar":{"g1":{"han":"并列复句“又……又……”","py":"Bìngliè fùjù “yòu... yòu...”","title":"Câu ghép đẳng lập “又……又……”","explain":"并列复句“又……又……”与形容词搭配使用，表示人或者事物同时具有两个特点。基本结构：又+形容词1+又+形容词2。\nCâu ghép đẳng lập “又……又……” được sử dụng kết hợp với tính từ, biểu thị người hoặc sự vật đồng thời mang hai đặc điểm. Cấu trúc cơ bản: 又 + tính từ 1 + 又 + tính từ 2.","examples":[{"zh":"我现在还真是又饿又渴。","py":"Wǒ xiànzài hái zhēn shì yòu è yòu kě.","vi":"Bây giờ em thực sự vừa đói vừa khát.","hl":"又饿又渴"},{"zh":"那个女孩儿又高又漂亮。","py":"Nàge nǚháir yòu gāo yòu piàoliang.","vi":"Cô gái kia vừa cao vừa xinh đẹp.","hl":"又高又漂亮"},{"zh":"这个饭馆的菜又便宜又好吃。","py":"Zhège fànguǎn de cài yòu piányi yòu hǎochī.","vi":"Món ăn ở nhà hàng này vừa rẻ vừa ngon.","hl":"又便宜又好吃"}],"struct":"又 + Tính từ 1 + 又 + Tính từ 2","note":"Hai tính từ phải cùng tính chất tích cực hoặc cùng tiêu cực (tránh trộn tốt với xấu)."},"g2":{"han":"疑问代词的非疑问用法（2）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (2)","title":"Cách dùng linh hoạt của đại từ nghi vấn (2)","explain":"疑问代词“哪、哪儿、什么、谁、怎么”等还可以用来表示任指，比如“谁”指任何一个人，“什么”指任何一件东西，句中常用副词“都”与之呼应。\nĐại từ nghi vấn “哪”, “哪儿”, “什么”, “谁”, “怎么”... còn có thể dùng để biểu thị ý nghĩa chỉ chung, ví dụ “谁” chỉ bất kỳ người nào, “什么” chỉ bất kỳ sự vật nào; thường dùng kết hợp với phó từ “都” trong câu.","examples":[{"zh":"哪个菜都好吃。","py":"Nǎge cài dōu hǎochī.","vi":"Món nào cũng ngon.","hl":"哪个……都"},{"zh":"这次旅游，我去哪儿都可以。","py":"Zhè cì lǚyóu, wǒ qù nǎr dōu kěyǐ.","vi":"Chuyến du lịch lần này tôi đi đâu cũng được.","hl":"哪儿都"},{"zh":"我下午有时间，你想什么时候来都没问题。","py":"Wǒ xiàwǔ yǒu shíjiān, nǐ xiǎng shénme shíhou lái dōu méi wèntí.","vi":"Buổi chiều tôi rảnh, bạn muốn đến lúc nào cũng không vấn đề gì.","hl":"什么时候都"}],"struct":"Đại từ nghi vấn + (... ) + 都 / 也 + Vị ngữ","note":"Diễn tả phạm vi toàn bộ (bất kỳ ai, bất kỳ cái gì, bất kỳ đâu... đều...)."},"g3":{"han":"疑问代词的非疑问用法（3）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (3)","title":"Cách dùng linh hoạt của đại từ nghi vấn (3)","explain":"两个相同的疑问代词可以表示任指，前后呼应，指同一个人、同一件事、同一种方式、同一个时间、同一个地点等。当前后两个分句的主语相同时，后一分句的主语可以省略。当前后两个分句的主语不同时，第二个主语要放在“就”的前面。\nHai đại từ nghi vấn giống nhau có thể dùng để biểu thị ý nghĩa chỉ chung, chúng có sự tương ứng trước sau, chỉ cùng một người, một sự việc, một phương thức, một thời điểm... Khi chủ ngữ của hai phân câu giống nhau, chủ ngữ của phân câu sau có thể được lược bỏ. Khi chủ ngữ của hai phân câu khác nhau, chủ ngữ thứ hai cần đặt trước “就”.","examples":[{"zh":"你们想吃什么就点什么。","py":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vi":"Các em muốn ăn món gì thì gọi món đó.","hl":"什么……就……什么"},{"zh":"你觉得哪个好看就买哪个。","py":"Nǐ juéde nǎge hǎokàn jiù mǎi nǎge.","vi":"Bạn thấy cái nào đẹp thì mua cái đó.","hl":"哪个……就……哪个"},{"zh":"你想去哪儿，我们就去哪儿。","py":"Nǐ xiǎng qù nǎr, wǒmen jiù qù nǎr.","vi":"Em muốn đi đâu thì chúng ta đi đó.","hl":"哪儿……就……哪儿"}],"struct":"... (Đại từ nghi vấn) + (Chủ ngữ 2 +) 就 + ... (Cùng đại từ nghi vấn)","note":"Hai vế tương ứng theo nguyên tắc đồng nhất đối tượng được chọn."}},"grammarQuiz":[{"id":"hsk3_b2_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我觉得 (____) 筷子吃饭更方便。","opts":[{"t":"用","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false}],"exp":"Đáp án E (用): ‘Tôi thấy dùng đũa ăn cơm tiện hơn.’"},{"id":"hsk3_b2_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你 (____) 住那个饭馆的名字了吗？","opts":[{"t":"记","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"用","ok":false}],"exp":"Đáp án D (记): ‘Bạn đã nhớ tên nhà hàng kia chưa?’"},{"id":"hsk3_b2_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她现在很饿，早上 (____) 吃了一块蛋糕。","opts":[{"t":"只","ok":true},{"t":"尝","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án B (只): ‘Cô ấy giờ rất đói, buổi sáng chỉ ăn có một miếng bánh ngọt.’"},{"id":"hsk3_b2_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"(____) 上有好几个新菜，你看看我们吃哪个？","opts":[{"t":"菜单","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án C (菜单): ‘Trên thực đơn có khá nhiều món mới, bạn xem chúng ta ăn món nào?’"},{"id":"hsk3_b2_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我妈妈会做中国菜，下次你们来我家 (____) 一下她做的菜。","opts":[{"t":"尝","ok":true},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án A (尝): ‘Mẹ tôi biết nấu món Trung Quốc, lần tới các bạn qua nhà tôi nếm thử món mẹ tôi nấu nhé.’"},{"id":"hsk3_b2_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我还不太会用筷子，你们有勺子吗？\nB: 有，你等一下，我 (____) 给你拿。","opts":[{"t":"马上","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false}],"exp":"Đáp án E (马上): ‘Có ạ, bạn đợi một chút, tôi mang ra cho bạn ngay.’"},{"id":"hsk3_b2_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我找服务员要一下菜单，咱们点菜。\nB: 在手机上就可以点菜，(____) 要菜单。","opts":[{"t":"不用","ok":true},{"t":"饿","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án B (不用): ‘Trên điện thoại có thể gọi món được rồi, không cần xin thực đơn đâu.’"},{"id":"hsk3_b2_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我太 (____) 了，不想做饭了，我们叫个外卖，怎么样？\nB: 没问题，你想吃什么，我们就点什么。","opts":[{"t":"饿","ok":true},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án A (饿): ‘Tôi đói quá rồi, không muốn nấu cơm nữa, mình đặt đồ ăn giao tận nơi nhé?’"},{"id":"hsk3_b2_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你想去哪个饭馆吃饭？\nB: 我 (____) 没吃饺子了，去楼下的饺子馆吧。","opts":[{"t":"好久","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án D (好久): ‘Tôi lâu lắm rồi chưa ăn sủi cảo, xuống quán sủi cảo dưới tầng đi.’"},{"id":"hsk3_b2_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你下班回家自己做饭吗？\nB: 不做饭，我就吃碗方便面。方便面是最 (____) 的晚饭。","opts":[{"t":"简单","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án C (简单): ‘Mì ăn liền là bữa tối đơn giản nhất.’"},{"id":"hsk3_b2_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"他们在做什么？","opts":[{"t":"C 在饭馆吃饭","ok":true},{"t":"A 买东西","ok":false},{"t":"B 在家吃饭","ok":false}],"exp":"Bốn người đang ngồi gọi món ăn tại nhà hàng."},{"id":"hsk3_b2_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月想吃什么中国菜？","opts":[{"t":"A 饺子","ok":true},{"t":"B 包子","ok":false},{"t":"C 面条儿","ok":false}],"exp":"Bạch Gia Nguyệt nói: “我想喝绿茶、吃饺子，可以吗？”"},{"id":"hsk3_b2_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪让服务员拿什么？","opts":[{"t":"C 勺子、筷子和碗","ok":true},{"t":"A 筷子和碗","ok":false},{"t":"B 勺子和筷子","ok":false}],"exp":"Vương Nhất Tuyết nói: “再给我们拿一双筷子、一个勺子和一个碗。”"},{"id":"hsk3_b2_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"这家饭馆的服务怎么样？","opts":[{"t":"B 很热情","ok":true},{"t":"A 很慢","ok":false},{"t":"C 不太好","ok":false}],"exp":"Vương Nhất Tuyết nhận xét: “这家饭馆的服务很热情”."},{"id":"hsk3_b2_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"在这家饭馆，白家月喜欢吃什么？","opts":[{"t":"B 鸡肉饭","ok":true},{"t":"A 包子","ok":false},{"t":"C 面条儿","ok":false}],"exp":"Bạch Gia Nguyệt nói: “这个鸡肉饭太好吃了”."},{"id":"hsk3_b2_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪为什么说“不用拿菜单”？","opts":[{"t":"C 手机上可以看菜单","ok":true},{"t":"A 她有菜单","ok":false},{"t":"B 她不想再来","ok":false}],"exp":"Vương Nhất Tuyết nói: “不用拿菜单，在手机上就能看到”."},{"id":"hsk3_b2_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"快要考试的时候，李文怎么吃饭？","opts":[{"t":"A 吃方便面","ok":true},{"t":"B 出去吃饭","ok":false},{"t":"C 回妈妈家吃","ok":false}],"exp":"Bài khóa 4: “快要考试的时候...我可能好几天只吃方便面。”"},{"id":"hsk3_b2_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"回到中国了，李文为什么很高兴？","opts":[{"t":"C 每天能吃到妈妈做的饭","ok":true},{"t":"A 妈妈每天做很多菜","ok":false},{"t":"B 可以经常去外面吃饭","ok":false}],"exp":"Bài khóa 4: “每天能吃到妈妈做的饭，我真是太高兴了！”"}],"chars":["菜","单","又","饿","渴","客","气","饮","料","好","久","服","务","员","双","筷","子","勺","碗","马","上","热","情","尝","记","用","鸡","张","不","选","外","卖","方","便","蛋","糕","只","面","简","你","们","想","吃","什","么","就","点"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 14): “上/下+量词”主要用来表示时间顺序，“上”表示过去，“下”表示将来。例如：上次/下次、上周/下周、上个月/下个月。Cấu trúc “上/下 + lượng từ” chủ yếu được dùng để biểu thị trình tự thời gian; “上” biểu thị quá khứ, “下” biểu thị tương lai. Ví dụ: 上次 (lần trước)/下次 (lần sau), 上周 (tuần trước)/下周 (tuần sau), 上个月 (tháng trước)/下个月 (tháng sau).","Món quà của Tiểu Ngữ (trang 18, video 2-1): 筷子 — Đũa.","Câu hỏi thảo luận Bài khóa 1: (1) 白家月现在觉得怎么样？ (2) 白家月想喝什么？ (3) 王一雪要点什么？","Câu hỏi thảo luận Bài khóa 2: (1) 王一雪觉得这家饭馆怎么样？ (2) 白家月觉得饭馆的菜怎么样？ (3) 服务员为什么送了一些水果？","Câu hỏi thảo luận Bài khóa 3: (1) 白家月为什么要再来吃一次？ (2) 这家饭馆可以怎么点菜？ (3) 听说很多饭馆都能送外卖，白家月觉得怎么样？","Câu hỏi thảo luận Bài khóa 4: (1) 李文在国外经常做饭吗？ (2) 李文为什么好几天只吃方便面？ (3) 回到中国后什么事让他非常高兴？"],"workbook":null},"3":{"pages":"19–28","titleZh":"这个小区挺好的","titlePy":"Zhège xiǎoqū tǐng hǎo de","titleVi":"Khu dân cư này khá tốt","goals":["能听懂并谈论居住环境和居家情况。Có thể nghe hiểu và thảo luận được về môi trường sống và tình hình sinh hoạt trong gia đình.","能听懂并使用“挺”“坏了”表达程度。Có thể nghe hiểu và sử dụng được “挺” và “坏了” để biểu đạt mức độ.","掌握“就”和“才”的用法，能表达动作发生的早晚、快慢等信息。Nắm vững cách dùng của “就” và “才” để biểu đạt thời điểm sớm hay muộn, nhanh hay chậm của hành động."],"words":[{"zh":"初中","py":"chūzhōng","vi":"trung học cơ sở, cấp hai","pos":"dt."},{"zh":"咱们","py":"zánmen","vi":"chúng ta","pos":"đt."},{"zh":"换","py":"huàn","vi":"thay, thay đổi, đổi","pos":"đgt."},{"zh":"房子","py":"fángzi","vi":"nhà, căn nhà","pos":"dt."},{"zh":"小区","py":"xiǎoqū","vi":"khu dân cư, khu nhà ở","pos":"dt."},{"zh":"环境","py":"huánjìng","vi":"môi trường","pos":"dt."},{"zh":"挺","py":"tǐng","vi":"khá, rất","pos":"phó."},{"zh":"空调","py":"kōngtiáo","vi":"máy điều hoà","pos":"dt."},{"zh":"洗衣机","py":"xǐyījī","vi":"máy giặt","pos":"dt."},{"zh":"层","py":"céng","vi":"tầng","pos":"lượng."},{"zh":"花园","py":"huāyuán","vi":"vườn hoa","pos":"dt."},{"zh":"灯","py":"dēng","vi":"đèn","pos":"dt."},{"zh":"关","py":"guān","vi":"tắt, đóng","pos":"đgt."},{"zh":"冰箱","py":"bīngxiāng","vi":"tủ lạnh","pos":"dt."},{"zh":"卫生间","py":"wèishēngjiān","vi":"nhà vệ sinh","pos":"dt."},{"zh":"打扫","py":"dǎsǎo","vi":"dọn dẹp, quét dọn","pos":"đgt."},{"zh":"搬家","py":"bānjiā","vi":"chuyển nhà","pos":"đgt."},{"zh":"办","py":"bàn","vi":"làm, xử lý","pos":"đgt."},{"zh":"信用卡","py":"xìnyòngkǎ","vi":"thẻ tín dụng","pos":"dt."},{"zh":"还","py":"huán","vi":"trả, hoàn trả","pos":"đgt."},{"zh":"听说","py":"tīngshuō","vi":"nghe nói","pos":"đgt."},{"zh":"银行","py":"yínháng","vi":"ngân hàng","pos":"dt."},{"zh":"才","py":"cái","vi":"(mãi)... mới","pos":"phó."},{"zh":"纸","py":"zhǐ","vi":"giấy","pos":"dt."},{"zh":"搬","py":"bān","vi":"chuyển, mang, bê","pos":"đgt."},{"zh":"需要","py":"xūyào","vi":"cần, cần thiết, nhu cầu","pos":"đgt./dt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，刘明和王一雪在聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trong nhà.","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","py":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìn diǎnr de fángzi ba.","vi":"Trường cấp 2 của Tiểu Tuyết khá xa nhà, chúng ta hãy chuyển nhà đến gần đó hơn đi."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好啊，我上网看看。你觉得这个小区怎么样？","py":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","vi":"Được em nhé, anh sẽ lên mạng xem. Em thấy khu dân cư này thế nào?"},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"环境挺好的，离地铁站还不远。","py":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn.","vi":"Môi trường khá ổn, cũng không xa ga tàu điện ngầm lắm."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"房子里面也不错，空调和洗衣机都是新的。","py":"Fángzi lǐmian yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","vi":"Bên trong căn hộ trông cũng không tồi, điều hoà và máy giặt đều là đồ mới."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是不错，但是我不喜欢住一层。","py":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng.","vi":"Cũng khá ổn đấy, nhưng em không thích sống ở tầng một."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这个一层带一个小花园，我觉得咱们可以去看看。","py":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","vi":"Căn hộ tầng một này có một khu vườn nhỏ, anh nghĩ chúng ta nên đến xem thử."},{"section":"Bài khóa 2","context":"在新家，王一雪在收拾房间，刘明进来了。Vương Nhất Tuyết đang dọn dẹp trong nhà mới thì Lưu Minh bước vào.","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我今天早上来的时候，灯还开着。","py":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe.","vi":"Sáng nay khi em tới, đèn vẫn còn đang bật."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我这几天忙坏了，可能走的时候忘关了。","py":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le.","vi":"Mấy ngày nay anh bận tối mắt tối mũi, chắc lúc đi quên tắt đèn rồi."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"冰箱不能用，这些吃的东西放在哪儿？","py":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?","vi":"Tủ lạnh không dùng được, đống đồ ăn này giờ phải để đâu đây?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"不可能吧？冰箱是新买的，我来看看。","py":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan.","vi":"Không thể nào? Tủ lạnh vừa mới mua mà, để anh xem thử."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"洗衣机也坏了吗？","py":"Xǐyījī yě huài le ma?","vi":"Có phải máy giặt cũng hỏng rồi không?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"没坏，但是卫生间没打扫好，还不能洗衣服。","py":"Méi huài, dànshì wèishēngjiān méi dǎsǎohǎo, hái bù néng xǐ yīfu.","vi":"Không, nhưng phòng vệ sinh vẫn chưa dọn sạch nên chưa thể giặt đồ được."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"星期天我们真的能搬家吗？","py":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","vi":"Liệu Chủ nhật này chúng ta có thể dọn đến đây không?"},{"section":"Bài khóa 3","context":"在家里，刘明和王一雪在客厅聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trong phòng khách ở nhà.","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这个月花了不少钱。","py":"Zhège yuè huāle bù shǎo qián.","vi":"Tháng này đã tiêu khá nhiều tiền rồi đấy."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是的，我们买了很多搬家时要用的东西。","py":"Shì de, wǒmen mǎile hěn duō bānjiā shí yào yòng de dōngxi.","vi":"Đúng vậy, mình đã mua rất nhiều thứ để dùng khi chuyển nhà mà."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","py":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànman huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bànle xìnyòngkǎ mǎi dōngxi hái néng piányi.","vi":"Chúng ta hãy làm thẻ tín dụng đi, như vậy tiền tiêu có thể trả dần được. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, lại còn được giảm giá khi mua sắm bằng thẻ tín dụng nữa."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","py":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?","vi":"Tuyệt! Ngân hàng Trung Quốc rất gần đây, chỉ mất vài phút đi bộ thôi. Khi nào chúng ta đi vậy?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"今天下午？","py":"Jīntiān xiàwǔ?","vi":"Chiều nay thì sao?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vi":"Chiều nay anh phải đến bệnh viện, phải khá muộn anh mới về được."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那我下午自己去吧。","py":"Nà wǒ xiàwǔ zìjǐ qù ba.","vi":"Vậy chiều nay em sẽ tự đi vậy."},{"section":"Bài khóa 4","context":"在家里，刘明和王一雪讨论搬家计划。Lưu Minh và Vương Nhất Tuyết đang ở trong nhà thảo luận về kế hoạch chuyển nhà.","audio":"03-7.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","py":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bānwán.","vi":"Anh nghĩ chúng ta có thể chuyển nhà trong tuần này. Ngày mai anh sẽ mua một ít thùng giấy, chuẩn bị một lát là xong ngay. Vào ngày chuyển nhà, anh định nhờ vài người bạn đến giúp, nhiều nhất chỉ mất một ngày là chuyển xong."},{"section":"Bài khóa 4","context":"","audio":"03-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","py":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xià zhōu qù dǎsǎo xīn jiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuòwán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī.","vi":"Em nghĩ phải tháng sau chúng ta mới có thể chuyển nhà được. Tuần này mình bắt đầu chuẩn bị, tuần sau dọn dẹp nhà mới. Bao nhiêu việc phải làm nên chúng ta cần ít nhất hai tuần để hoàn tất mọi thứ. Vào ngày chuyển nhà, chúng ta nên thuê một công ty chuyển nhà."}],"dialogQuestions":[],"grammar":{"g1":{"han":"程度副词“挺”","py":"Chéngdù fùcí “tǐng”","title":"Phó từ chỉ mức độ “挺”","explain":"程度副词“挺”用在形容词或心理动词前，表示程度较高，常用于口语中。基本结构：挺+形容词/心理动词+的。\nPhó từ chỉ mức độ “挺” thường dùng trong văn nói, đặt trước tính từ hoặc động từ chỉ tâm lý để biểu thị mức độ tương đối cao. Cấu trúc cơ bản: 挺 + tính từ/động từ chỉ tâm lý + 的.","examples":[{"zh":"这个小区环境挺好的。","py":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vi":"Môi trường khu dân cư này khá tốt.","hl":"挺好的"},{"zh":"这家饭馆的菜挺好吃的。","py":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","vi":"Món ăn ở nhà hàng này khá ngon.","hl":"挺好吃的"},{"zh":"买这个吧，我挺喜欢这个颜色的。","py":"Mǎi zhège ba, wǒ tǐng xǐhuan zhège yánsè de.","vi":"Mua cái này đi, tôi khá thích màu này đấy.","hl":"挺喜欢……的"}],"struct":"挺 + Tính từ / Động từ tâm lý + 的","note":"Thường đi kèm trợ từ ngữ khí “的” ở cuối câu để câu nói tự nhiên hơn."},"g2":{"han":"程度补语（1）","py":"Chéngdù bǔyǔ (1)","title":"Bổ ngữ trình độ (1)","explain":"程度补语“坏了”用在形容词的后面，表示程度非常高，带有夸张的语气，常用在负面的情况中。\nBổ ngữ trình độ “坏了” đặt sau tính từ, biểu thị mức độ rất cao, mang ngữ khí cường điệu, thường dùng trong các tình huống tiêu cực.","examples":[{"zh":"我这几天忙坏了。","py":"Wǒ zhè jǐ tiān máng huài le.","vi":"Mấy ngày nay anh bận chết đi được (bận tối mắt tối mũi).","hl":"忙坏了"},{"zh":"我渴坏了，哪里能买水？","py":"Wǒ kě huài le, nǎlǐ néng mǎi shuǐ?","vi":"Tôi khát khô cổ rồi, ở đâu mua được nước thế?","hl":"渴坏了"},{"zh":"这几天非常忙，大家都累坏了。","py":"Zhè jǐ tiān fēicháng máng, dàjiā dōu lèi huài le.","vi":"Mấy hôm nay rất bận, mọi người đều mệt rã rời rồi.","hl":"累坏了"}],"struct":"Tính từ + 坏了","note":"Mang sắc thái nhấn mạnh cực độ (mệt rã rời, bận tối mặt, đói cồn cào...)."},"g3":{"han":"“就”和“才”","py":"“Jiù” hé “Cái”","title":"Phó từ “就” và “才”","explain":"副词“就”和“才”用在动词前面作状语，“就”表示说话人认为动作发生得早，进行得快、顺利；“才”表示说话人认为动作发生得晚，进行得慢、不顺利。\nPhó từ “就” và “才” đặt trước động từ làm trạng ngữ. “就” biểu thị hành động xảy ra sớm hoặc được thực hiện nhanh, thuận lợi theo nhận định của người nói; “才” biểu thị hành động xảy ra muộn hoặc được thực hiện chậm, không thuận lợi theo nhận định của người nói.","examples":[{"zh":"中国银行很近，走路几分钟就能到。","py":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào.","vi":"Ngân hàng Trung Quốc rất gần, đi bộ vài phút là có thể đến ngay.","hl":"就"},{"zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vi":"Chiều nay anh phải đến bệnh viện, rất muộn mới về được.","hl":"才"},{"zh":"我早上五点就起床了。","py":"Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le.","vi":"Sáng 5 giờ tôi đã dậy rồi.","hl":"就"},{"zh":"坐火车去北京，五个小时才能到。","py":"Zuò huǒchē qù Běijīng, wǔ gè xiǎoshí cái néng dào.","vi":"Đi tàu hỏa đến Bắc Kinh, mất 5 tiếng mới tới được.","hl":"才"}],"struct":"Thời gian / Số lượng + 就 + Động từ (sớm/nhanh/dễ) | Thời gian / Số lượng + 才 + Động từ (muộn/lâu/khó)","note":"Lưu ý: Cuối câu dùng “才” thường không thêm trợ từ ngữ khí “了” khi diễn đạt thời gian muộn."}},"grammarQuiz":[{"id":"hsk3_b3_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你走的时候要 (____) 灯。","opts":[{"t":"关","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"还","ok":false}],"exp":"Đáp án D (关): ‘Lúc bạn đi nhớ tắt đèn.’"},{"id":"hsk3_b3_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我要去银行 (____) 一张信用卡。","opts":[{"t":"办","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án C (办): ‘Tôi muốn ra ngân hàng làm một tấm thẻ tín dụng.’"},{"id":"hsk3_b3_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"搬家要准备的东西 (____) 多的。","opts":[{"t":"挺","ok":true},{"t":"才","ok":false},{"t":"办","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án B (挺): ‘Đồ đạc cần chuẩn bị khi chuyển nhà khá nhiều đấy.’"},{"id":"hsk3_b3_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这本书不是我的，明天我要 (____) 给朋友。","opts":[{"t":"还","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"关","ok":false}],"exp":"Đáp án E (还): ‘Quyển sách này không phải của tôi, ngày mai tôi phải trả lại cho bạn.’"},{"id":"hsk3_b3_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我太忙了，没时间打扫新家，可能下个月 (____) 搬家。","opts":[{"t":"才","ok":true},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án A (才): ‘Tôi bận quá, chưa có thời gian dọn nhà mới, có lẽ tháng sau mới chuyển nhà.’"},{"id":"hsk3_b3_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你去哪儿了？怎么这么晚才回来？\nB: 我一直在 (____) 新家，今天真是累坏了。","opts":[{"t":"打扫","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false}],"exp":"Đáp án E (打扫): ‘Tôi luôn dọn dẹp nhà mới, hôm nay đúng là mệt rã rời.’"},{"id":"hsk3_b3_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个小区离学校有点儿远。\nB: 虽然有点儿远，但是我们很喜欢这个小区的 (____)。","opts":[{"t":"环境","ok":true},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án A (环境): ‘Tuy hơi xa một chút nhưng chúng tôi rất thích môi trường của khu dân cư này.’"},{"id":"hsk3_b3_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你知道她为什么不喜欢这个房子吗？\nB: 我 (____) 她不喜欢住一层。","opts":[{"t":"听说","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án D (听说): ‘Tôi nghe nói cô ấy không thích ở tầng một.’"},{"id":"hsk3_b3_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个小区明天不能 (____)，你知道吗？\nB: 我知道，我已经告诉搬家公司的人了，他们下周一再来。","opts":[{"t":"搬家","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án C (搬家): ‘Ngày mai khu dân cư này không cho chuyển nhà, bạn biết không?’"},{"id":"hsk3_b3_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 她家真大，还有个大花园。\nB: 因为她家人多，(____) 一个大房子。","opts":[{"t":"需要","ok":true},{"t":"环境","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án B (需要): ‘Vì nhà cô ấy đông người nên cần một ngôi nhà lớn.’"},{"id":"hsk3_b3_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一雪和刘明想做什么？","opts":[{"t":"A 换房子","ok":true},{"t":"B 买空调","ok":false},{"t":"C 去女儿的初中","ok":false}],"exp":"Vương Nhất Tuyết nói: “咱们换一个近点儿的房子吧。”"},{"id":"hsk3_b3_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一雪为什么不喜欢这个房子？","opts":[{"t":"B 她不喜欢住一层","ok":true},{"t":"A 房子太远","ok":false},{"t":"C 她不喜欢这个小区","ok":false}],"exp":"Vương Nhất Tuyết nói: “是不错，但是我不喜欢住一层。”"},{"id":"hsk3_b3_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"灯为什么开着？","opts":[{"t":"C 刘明走的时候忘关了","ok":true},{"t":"A 灯坏了","ok":false},{"t":"B 是王一雪打开的","ok":false}],"exp":"Lưu Minh nói: “可能走的时候忘关了。”"},{"id":"hsk3_b3_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"现在新家是什么样的？","opts":[{"t":"C 卫生间没打扫好","ok":true},{"t":"A 冰箱是旧的","ok":false},{"t":"B 洗衣机是坏的","ok":false}],"exp":"Lưu Minh nói: “冰箱是新买的...没坏，但是卫生间没打扫好，还不能洗衣服。”"},{"id":"hsk3_b3_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪和刘明为什么这个月花了不少钱？","opts":[{"t":"C 买了很多搬家要用的东西","ok":true},{"t":"A 买衣服了","ok":false},{"t":"B 去饭店吃饭了","ok":false}],"exp":"Lưu Minh nói: “是的，我们买了很多搬家时要用的东西。”"},{"id":"hsk3_b3_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪想去中国银行做什么？","opts":[{"t":"C 办信用卡","ok":true},{"t":"A 买东西","ok":false},{"t":"B 还信用卡","ok":false}],"exp":"Vương Nhất Tuyết nói: “咱们办张信用卡吧...”"},{"id":"hsk3_b3_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明想什么时候搬家？","opts":[{"t":"B 这个星期","ok":true},{"t":"A 明天","ok":false},{"t":"C 下个星期","ok":false}],"exp":"Lưu Minh nói: “我觉得这个星期就能搬家。”"},{"id":"hsk3_b3_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪想什么时候搬家？","opts":[{"t":"C 下个月","ok":true},{"t":"A 这周","ok":false},{"t":"B 下周","ok":false}],"exp":"Vương Nhất Tuyết nói: “我觉得下个月才能搬家。”"}],"chars":["初","中","咱","们","换","房","子","小","区","环","境","挺","空","调","洗","衣","机","层","花","园","灯","关","冰","箱","卫","生","间","打","扫","搬","家","办","信","用","卡","还","听","说","银","行","才","纸","需","要","这","个","好","的"],"rhyme":null,"notes":["Món quà của Tiểu Ngữ (trang 27, video 3-1): 在中国租房 — Thuê nhà tại Trung Quốc.","Tổng kết học tập Bài 1–3 (trang 27–28): 9 điểm ngữ pháp gồm 看上去/看起来, 疑问代词的非疑问用法(1)(2)(3), 多项定语, 又……又……, 挺, 程度补语(1) 坏了, 就 và 才.","Câu hỏi thảo luận Bài khóa 1: (1) 他们为什么要换房子？ (2) 王一雪觉得新小区怎么样？ (3) 刘明为什么喜欢这个房子？","Câu hỏi thảo luận Bài khóa 2: (1) 他们家的冰箱怎么了？ (2) 为什么不能洗衣服？ (3) 你觉得星期天他们能不能搬家？为什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪为什么想办信用卡？ (2) 王一雪想什么时候去银行？ (3) 刘明为什么今天不能去银行？","Câu hỏi thảo luận Bài khóa 4: (1) 刘明明天去买什么？ (2) 王一雪打算下周做什么？ (3) 刘明打算找谁搬家？王一雪呢？"],"workbook":null},"4":{"pages":"29–37","titleZh":"这家宾馆跟别的都不一样","titlePy":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","titleVi":"Khách sạn này không giống như những khách sạn khác","goals":["能听懂并谈论假期计划，能表达旅游过程中的感受。Có thể nghe hiểu và thảo luận kế hoạch kỳ nghỉ, có thể diễn đạt được cảm nhận trong quá trình du lịch.","能听懂并表达完全否定的意义。Có thể nghe hiểu và diễn đạt được ý nghĩa của phủ định hoàn toàn.","掌握“除了”的用法，能表达排除或补充的意义。Nắm vững cách sử dụng của “除了” để biểu đạt ý nghĩa loại trừ hoặc bổ sung."],"words":[{"zh":"假期","py":"jiàqī","vi":"kỳ nghỉ","pos":"dt."},{"zh":"海","py":"hǎi","vi":"biển","pos":"dt."},{"zh":"草原","py":"cǎoyuán","vi":"thảo nguyên","pos":"dt."},{"zh":"主意","py":"zhǔyi","vi":"ý tưởng","pos":"dt."},{"zh":"骑","py":"qí","vi":"cưỡi","pos":"đgt."},{"zh":"马","py":"mǎ","vi":"ngựa","pos":"dt."},{"zh":"羊","py":"yáng","vi":"cừu, dê","pos":"dt."},{"zh":"月亮","py":"yuèliang","vi":"mặt trăng","pos":"dt."},{"zh":"一定","py":"yídìng","vi":"nhất định, chắc chắn","pos":"phó."},{"zh":"刻","py":"kè","vi":"khắc (15 phút)","pos":"lượng."},{"zh":"起飞","py":"qǐfēi","vi":"cất cánh","pos":"đgt."},{"zh":"宾馆","py":"bīnguǎn","vi":"khách sạn","pos":"dt."},{"zh":"特别","py":"tèbié","vi":"đặc biệt, rất, vô cùng","pos":"tt./phó."},{"zh":"别的","py":"biéde","vi":"khác","pos":"đt."},{"zh":"一样","py":"yíyàng","vi":"giống nhau","pos":"tt."},{"zh":"牛","py":"niú","vi":"bò","pos":"dt."},{"zh":"相机","py":"xiàngjī","vi":"máy ảnh","pos":"dt."},{"zh":"欢迎","py":"huānyíng","vi":"chào đón, hoan nghênh","pos":"đgt."},{"zh":"司机","py":"sījī","vi":"tài xế","pos":"dt."},{"zh":"晚点","py":"wǎndiǎn","vi":"muộn, muộn giờ, trễ giờ","pos":"đgt."},{"zh":"久","py":"jiǔ","vi":"lâu","pos":"tt."},{"zh":"除了","py":"chúle","vi":"ngoài... (ra), trừ... (ra)","pos":"giới."},{"zh":"以外","py":"yǐwài","vi":"(ngoài)... ra","pos":"dt."},{"zh":"先","py":"xiān","vi":"trước, trước tiên","pos":"phó."},{"zh":"一直","py":"yìzhí","vi":"luôn luôn, suốt","pos":"phó."},{"zh":"干净","py":"gānjìng","vi":"sạch, sạch sẽ","pos":"tt."},{"zh":"满意","py":"mǎnyì","vi":"hài lòng","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在王一飞家客厅，杨同乐和王一飞在聊天儿。Dương Đồng Lạc và Vương Nhất Phi đang trò chuyện trong phòng khách nhà Vương Nhất Phi.","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"这个假期咱们去哪儿玩玩吧。","py":"Zhège jiàqī zánmen qù nǎr wánwan ba.","vi":"Kỳ nghỉ này mình đi đâu chơi đi."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"好啊，你想去哪儿，咱们就去哪儿。","py":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr.","vi":"Được đấy, anh muốn đi đâu thì mình sẽ đi đó."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"你喜欢海，找个海边住几天，怎么样？","py":"Nǐ xǐhuan hǎi, zhǎo gè hǎibiān zhù jǐ tiān, zěnmeyàng?","vi":"Em thích biển, hay là mình tìm chỗ nào gần biển ở lại vài ngày nhé?"},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"现在去海边有点儿冷。","py":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","vi":"Bây giờ mà đi biển thì hơi lạnh."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"那去草原吧？草原一点儿也不冷。","py":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Vậy đi thảo nguyên đi. Ở vùng thảo nguyên không lạnh chút nào cả."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"这个主意好！我好久没骑马了。","py":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qímǎ le.","vi":"Ý kiến này thật tuyệt! Đã lâu lắm rồi em không được cưỡi ngựa."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","py":"Duì, zài cǎoyuán shang qímǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒu yìsi.","vi":"Đúng rồi, cưỡi ngựa, ăn thịt cừu và ngắm trăng trên thảo nguyên chắc chắn sẽ rất tuyệt vời."},{"section":"Bài khóa 2","context":"在王一飞家客厅，杨同乐和王一飞在聊天儿。Dương Đồng Lạc và Vương Nhất Phi đang trò chuyện trong phòng khách nhà Vương Nhất Phi.","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"出去玩的机票买好了吗？","py":"Chūqù wán de jīpiào mǎihǎo le ma?","vi":"Em đã mua vé máy bay cho chuyến đi của chúng ta chưa?"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"买好了。星期六上午十点一刻起飞。","py":"Mǎihǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi.","vi":"Em mua xong rồi ạ. Chuyến bay khởi hành lúc 10 giờ 15 phút sáng thứ Bảy."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"宾馆也选好了吗？","py":"Bīnguǎn yě xuǎnhǎo le ma?","vi":"Em đã chọn được khách sạn chưa?"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","py":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!","vi":"Rồi ạ, khách sạn này không giống những khách sạn khác, nó rất đặc biệt, bước ra khỏi khách sạn là có thể nhìn thấy bò và cừu!"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"太好了！你看看要带什么东西？","py":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?","vi":"Tuyệt quá! Em xem chúng mình cần mang theo những gì nào."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我们不用带太多东西，别忘了拿上新买的相机。","py":"Wǒmen búyòng dài tài duō dōngxi, bié wàngle náshàng xīn mǎi de xiàngjī.","vi":"Mình không cần mang quá nhiều đồ đâu, đừng quên mang chiếc máy ảnh mới mua là được."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"一定不会忘带的。我现在就去准备行李。","py":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli.","vi":"Chắc chắn sẽ không quên mang theo đâu. Bây giờ anh đi thu dọn hành lý đây."},{"section":"Bài khóa 3","context":"在机场，杨同乐和王一飞走出来，跟他们预约的司机兼导游见面。Dương Đồng Lạc và Vương Nhất Phi đi ra phía ngoài sân bay và gặp lái xe kiêm hướng dẫn viên mà họ đã đặt trước.","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","py":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ.","vi":"Chào mừng quý khách! Em là tài xế của anh chị, em họ Lý, cứ gọi em là Tiểu Lý."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您好！不好意思，飞机晚点了，让您久等了。","py":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","vi":"Chào em! Xin lỗi vì chuyến bay của chúng tôi bị hoãn nên em đã phải đợi lâu."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"没关系。除了这个行李箱以外，还有别的东西吗？","py":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Không sao ạ. Ngoài chiếc va li này ra, anh chị còn đồ gì khác không?"},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"还有一个包，我自己拿就可以。","py":"Hái yǒu yí gè bāo, wǒ zìjǐ ná jiù kěyǐ.","vi":"Chỉ còn một chiếc túi nữa thôi, anh tự xách được."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"车在一层，请跟我来。","py":"Chē zài yì céng, qǐng gēn wǒ lái.","vi":"Xe đang đỗ ở tầng một, mời anh chị đi theo em."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我们住的宾馆离机场远吗？","py":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?","vi":"Khách sạn của chúng tôi có xa sân bay không?"},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","py":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen.","vi":"Không xa đâu, khoảng ba mươi phút là đến. Sau khi đến nơi, anh chị có thể nghỉ ngơi một lát trước, em sẽ gọi cho anh chị khi đến giờ ăn tối."},{"section":"Bài khóa 4","context":"在宾馆房间，王一飞在写日记。Vương Nhất Phi đang viết nhật ký ở trong phòng khách sạn.","audio":"04-7.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"今天是我们旅游的第一天。我们很早就起床去机场了，没想到飞机晚点了。我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","py":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān. Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le. Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí. Tā tèbié rèqíng, lùshang gěi wǒmen jièshàole hěn duō dōngxi, hái zhǔnbèile shuǐguǒ. Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì.","vi":"Hôm nay là ngày đầu tiên của chuyến du lịch. Chúng tôi đã dậy rất sớm để ra sân bay, nào ngờ đâu chuyến bay lại bị trễ. Khi chúng tôi tới nơi thì trời đã tối, nhưng tài xế của chúng tôi, Tiểu Lý, vẫn đợi chúng tôi ở sân bay mà không hề tỏ ra mất kiên nhẫn. Tiểu Lý vô cùng nhiệt tình, dọc đường đã kể cho chúng tôi nghe rất nhiều thứ, còn chuẩn bị sẵn một ít trái cây. Phòng khách sạn cũng đẹp đúng như tôi tưởng tượng, vừa rộng rãi, vừa sạch sẽ, tôi rất hài lòng về nó."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定格式“一……也/都+不/没……”","py":"Gùdìng géshì “yī... yě/dōu + bù/méi...”","title":"Cấu trúc cố định “一……也/都+不/没……”","explain":"固定格式“一……也/都+不/没……”表示完全否定。有时候，“一+量词”还可以用“一点儿”来表示。当谓语是形容词时，通常用“一点儿也/都+不/没+形容词”表示完全否定。\nCấu trúc cố định “一……也/都 + 不/没……” biểu thị ý nghĩa phủ định hoàn toàn. “一 + lượng từ” đôi khi có thể được thay bằng “一点儿”. Khi vị ngữ là tính từ, thường dùng cấu trúc “一点儿也/都 + 不/没 + tính từ” để biểu thị phủ định hoàn toàn.","examples":[{"zh":"她一件衣服都不想买。","py":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vi":"Cô ấy một bộ quần áo cũng không muốn mua.","hl":"一件……都不"},{"zh":"我一个中国电影也没看过。","py":"Wǒ yí gè Zhōngguó diànyǐng yě méi kànguo.","vi":"Tôi chưa từng xem một bộ phim Trung Quốc nào cả.","hl":"一个……也没"},{"zh":"我一点儿东西也不想吃。","py":"Wǒ yìdiǎnr dōngxi yě bù xiǎng chī.","vi":"Tôi chẳng muốn ăn chút đồ nào cả.","hl":"一点儿……也不"},{"zh":"草原一点儿也不冷。","py":"Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Thảo nguyên chẳng lạnh chút nào.","hl":"一点儿也不"}],"struct":"一 + Lượng từ + Danh từ + 也/都 + 不/没 + Động từ | 一点儿 + (Danh từ +) 也/都 + 不/没 + Động từ / Tính từ","note":"Nhấn mạnh mức độ phủ định tuyệt đối (hoàn toàn không)."},"g2":{"han":"比较句（9）","py":"Bǐjiàojù (9)","title":"Câu so sánh (9)","explain":"比较句“A跟B一样”表示A和B比较后，结果相同。“一样”的后面可以用形容词表示比较的某一方面，基本结构：A跟B一样+形容词。否定形式是在“一样”的前面加“不”。\nCâu so sánh “A 跟 B 一样” biểu đạt A và B có kết quả giống nhau sau khi so sánh. Sau “一样” có thể dùng tính từ để biểu thị một phương diện so sánh nào đó. Cấu trúc cơ bản: A 跟 B 一样 + tính từ. Hình thức phủ định thêm “不” trước “一样”.","examples":[{"zh":"这家宾馆跟别的都不一样。","py":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng.","vi":"Khách sạn này không giống như những khách sạn khác.","hl":"跟……不一样"},{"zh":"他买的新手机跟我的一样。","py":"Tā mǎi de xīn shǒujī gēn wǒ de yíyàng.","vi":"Chiếc điện thoại mới anh ấy mua giống cái của tôi.","hl":"跟……一样"},{"zh":"这个房间跟那个房间一样大。","py":"Zhège fángjiān gēn nàge fángjiān yíyàng dà.","vi":"Căn phòng này rộng bằng căn phòng kia.","hl":"跟……一样大"}],"struct":"A + 跟 + B + (不) 一样 (+ Tính từ)","note":"Dùng “跟” hoặc “和” đều được; khi có từ chỉ tính chất, đặt tính từ ngay sau “一样”."},"g3":{"han":"固定格式“除了……（以外），……都/还/也……”","py":"Gùdìng géshì “chúle... (yǐwài), ... dōu/hái/yě...”","title":"Cấu trúc cố định “除了……（以外），……都/还/也……”","explain":"“除了……（以外），……都……”表示在一个范围内，排除一部分，其他的都存在相同的情况，其中“以外”可以省略。“除了……（以外），……还/也……”表示排除一部分，补充其他的。句子的主语放在句首，或者放在“还/也”的前面。\nCấu trúc “除了……（以外），……都……” dùng để diễn đạt ý nghĩa sau khi đã loại trừ một phần, những phần còn lại đều giống nhau trong một phạm vi nào đó, “以外” có thể lược bỏ. Cấu trúc “除了……（以外），……还/也……” biểu thị loại trừ một phần và bổ sung thêm phần khác.","examples":[{"zh":"除了我以外，大家都在玩手机。","py":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vi":"Ngoài tôi ra, mọi người đều đang nghịch điện thoại.","hl":"除了……以外，……都"},{"zh":"除了这个汉字，别的汉字我都会写。","py":"Chúle zhège Hànzì, biéde Hànzì wǒ dōu huì xiě.","vi":"Trừ chữ Hán này ra, các chữ Hán khác tôi đều biết viết.","hl":"除了……，……都"},{"zh":"除了这个行李箱以外，还有别的东西吗？","py":"Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Ngoài chiếc va li này ra, còn đồ gì khác không?","hl":"除了……以外，还"},{"zh":"除了唱歌以外，他也喜欢跳舞。","py":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","vi":"Ngoài ca hát ra, anh ấy cũng thích nhảy múa.","hl":"除了……以外，……也"}],"struct":"除了 + A + (以外)，+ B + 都 + ... (loại trừ) | 除了 + A + (以外)，+ ... + 还/也 + ... (bổ sung)","note":"Phân biệt rõ cặp phó từ “都” (ngoại trừ A thì phần còn lại đều) và “还/也” (ngoài A ra còn có thêm)."}},"grammarQuiz":[{"id":"hsk3_b4_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"已经八点一 (____) 了，快起床吧。","opts":[{"t":"刻","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án C (刻): ‘Đã 8 giờ 15 phút rồi, mau dậy đi.’"},{"id":"hsk3_b4_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"飞机晚点了，小李在机场等了很 (____)。","opts":[{"t":"久","ok":true},{"t":"先","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án B (久): ‘Máy bay bị trễ, Tiểu Lý đã đợi ở sân bay rất lâu.’"},{"id":"hsk3_b4_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 打车过去，你们可以慢慢走过去。","opts":[{"t":"先","ok":true},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án A (先): ‘Tôi bắt xe đi sang trước, các bạn có thể thong thả đi bộ qua.’"},{"id":"hsk3_b4_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我对这里的服务非常 (____)，下次还会再来。","opts":[{"t":"满意","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án D (满意): ‘Tôi rất hài lòng với dịch vụ ở đây, lần sau sẽ lại đến.’"},{"id":"hsk3_b4_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们这次在草原上住的宾馆很 (____)，跟别的都不一样。","opts":[{"t":"特别","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false}],"exp":"Đáp án E (特别): ‘Khách sạn lần này chúng tôi ở trên thảo nguyên rất đặc biệt, không giống những nơi khác.’"},{"id":"hsk3_b4_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 草原真是太漂亮了，跟我想的 (____)。\nB: 我觉得草原比我想的更漂亮。","opts":[{"t":"一样","ok":true},{"t":"一直","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án B (一样): ‘Thảo nguyên đẹp quá, giống hệt như tôi tưởng tượng.’"},{"id":"hsk3_b4_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我们搬家了，(____) 你来我们的新家玩。\nB: 好啊，有时间我一定去。","opts":[{"t":"欢迎","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án D (欢迎): ‘Chúng tôi chuyển nhà rồi, chào đón bạn đến nhà mới của chúng tôi chơi.’"},{"id":"hsk3_b4_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 除了要买几个纸箱，还买 (____) 东西吗？\nB: 没有了，谢谢你帮我买。","opts":[{"t":"别的","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false}],"exp":"Đáp án E (别的): ‘Ngoài mấy thùng giấy ra có mua đồ gì khác nữa không?’"},{"id":"hsk3_b4_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 喂，小李，这边天气不好，我们还没起飞呢。\nB: 没关系，我会 (____) 在机场等您。","opts":[{"t":"一直","ok":true},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án A (一直): ‘Không sao đâu, em sẽ luôn đợi anh chị ở sân bay.’"},{"id":"hsk3_b4_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 行李准备好了，你看看还需要带什么东西？\nB: (____) 别忘了带护照。","opts":[{"t":"一定","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án C (一定): ‘Nhất định đừng quên mang hộ chiếu.’"},{"id":"hsk3_b4_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一飞和杨同乐在说什么？","opts":[{"t":"C 假期做什么","ok":true},{"t":"A 明天的天气","ok":false},{"t":"B 喜欢吃什么","ok":false}],"exp":"Hai người đang bàn bạc kỳ nghỉ này đi đâu chơi (“这个假期咱们去哪儿玩玩吧”)."},{"id":"hsk3_b4_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"杨同乐觉得草原怎么样？","opts":[{"t":"C 草原很有意思","ok":true},{"t":"A 草原天气不好","ok":false},{"t":"B 草原比海边冷","ok":false}],"exp":"Dương Đồng Lạc nói: “在草原上骑马、吃羊肉、看月亮，一定很有意思。”"},{"id":"hsk3_b4_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一飞觉得这次出去玩要带什么东西？","opts":[{"t":"B 带新买的相机","ok":true},{"t":"A 什么都不用带","ok":false},{"t":"C 要带很多东西","ok":false}],"exp":"Vương Nhất Phi nói: “我们不用带太多东西，别忘了拿上新买的相机。”"},{"id":"hsk3_b4_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"杨同乐现在去做什么？","opts":[{"t":"C 准备行李","ok":true},{"t":"A 买机票","ok":false},{"t":"B 选宾馆","ok":false}],"exp":"Dương Đồng Lạc nói: “我现在就去准备行李。”"},{"id":"hsk3_b4_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"小李是谁？","opts":[{"t":"B 同乐的司机","ok":true},{"t":"A 同乐的朋友","ok":false},{"t":"C 宾馆的服务员","ok":false}],"exp":"Tiểu Lý tự giới thiệu: “我是你们的司机，我姓李，叫我小李就可以。”"},{"id":"hsk3_b4_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们到宾馆后先做什么？","opts":[{"t":"A 休息","ok":true},{"t":"B 吃晚饭","ok":false},{"t":"C 等朋友","ok":false}],"exp":"Tiểu Lý nói: “两位到了可以先休息休息，晚饭的时候我叫你们。”"},{"id":"hsk3_b4_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"飞机晚点后，司机做什么了？","opts":[{"t":"C 一直在机场等","ok":true},{"t":"A 去宾馆了","ok":false},{"t":"B 去买水果了","ok":false}],"exp":"Bài khóa 4: “但是司机小李一直在机场等我们，一点儿也没着急。”"},{"id":"hsk3_b4_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"他们是什么时候到的？","opts":[{"t":"C 晚上","ok":true},{"t":"A 上午","ok":false},{"t":"B 中午","ok":false}],"exp":"Bài khóa 4: “我们到的时候，天已经黑了...” (trời đã tối tức buổi tối)."}],"chars":["假","期","海","草","原","主","意","骑","马","羊","月","亮","一","定","刻","起","飞","宾","馆","特","别","的","样","牛","相","机","欢","迎","司","晚","点","久","除","了","以","外","先","直","干","净","满","这","家","跟","都","不"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 王一飞为什么不想去海边？ (2) 王一飞为什么觉得去草原好？ (3) 他们在草原上可以做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 他们什么时候坐飞机出去玩？ (2) 王一飞选的宾馆怎么样？ (3) 杨同乐说一定不会忘带什么？","Câu hỏi thảo luận Bài khóa 3: (1) 他们为什么到晚了？ (2) 他们有几个行李箱？ (3) 宾馆离机场远吗？","Câu hỏi thảo luận Bài khóa 4: (1) 他们是怎么去宾馆的？ (2) 王一飞为什么觉得小李很热情？ (3) 宾馆的房间怎么样？"],"workbook":null},"5":{"pages":"38–46","titleZh":"这样的照片才好看","titlePy":"Zhèyàng de zhàopiàn cái hǎokàn","titleVi":"Những bức ảnh như thế này mới đẹp","goals":["能听懂并介绍自己喜欢的休闲生活。Có thể nghe hiểu và giới thiệu được về hoạt động giải trí yêu thích của bản thân.","能听懂并表达两个动作行为接连发生。Có thể nghe hiểu và diễn đạt được hai hành động xảy ra liên tiếp.","掌握存现句（3）的用法，能表达人或事物的出现或消失。Nắm vững cách dùng của câu tồn hiện (3) để miêu tả sự xuất hiện hoặc biến mất của người hoặc sự vật."],"words":[{"zh":"总是","py":"zǒngshì","vi":"luôn luôn","pos":"phó."},{"zh":"终于","py":"zhōngyú","vi":"cuối cùng","pos":"phó."},{"zh":"爬","py":"pá","vi":"leo, leo trèo","pos":"đgt."},{"zh":"山","py":"shān","vi":"núi đồi","pos":"dt."},{"zh":"锻炼","py":"duànliàn","vi":"tập luyện, tập thể dục","pos":"đgt."},{"zh":"照","py":"zhào","vi":"chụp (ảnh)","pos":"đgt."},{"zh":"鞋","py":"xié","vi":"giầy","pos":"dt."},{"zh":"大衣","py":"dàyī","vi":"áo khoác","pos":"dt."},{"zh":"拍照","py":"pāizhào","vi":"chụp ảnh","pos":"đgt."},{"zh":"感兴趣","py":"gǎn xìngqù","vi":"hứng thú, có hứng thú (với)","pos":""},{"zh":"照相","py":"zhàoxiàng","vi":"chụp ảnh","pos":"đgt."},{"zh":"难看","py":"nánkàn","vi":"xấu, khó coi","pos":"tt."},{"zh":"比较","py":"bǐjiào","vi":"so sánh, tương đối","pos":"đgt./phó."},{"zh":"水平","py":"shuǐpíng","vi":"trình độ, mức","pos":"dt."},{"zh":"太阳","py":"tàiyáng","vi":"mặt trời","pos":"dt."},{"zh":"树","py":"shù","vi":"cây","pos":"dt."},{"zh":"干","py":"gàn","vi":"làm","pos":"đgt."},{"zh":"电","py":"diàn","vi":"điện","pos":"dt."},{"zh":"收到","py":"shōudào","vi":"nhận được","pos":"đgt."},{"zh":"封","py":"fēng","vi":"bức, lá (thư)","pos":"lượng."},{"zh":"邮件","py":"yóujiàn","vi":"email, thư điện tử","pos":"dt."},{"zh":"难过","py":"nánguò","vi":"buồn, buồn rầu","pos":"tt."},{"zh":"哈哈","py":"hāhā","vi":"ha ha (tiếng cười)","pos":""},{"zh":"音乐","py":"yīnyuè","vi":"âm nhạc","pos":"dt."},{"zh":"兴趣","py":"xìngqù","vi":"hứng thú","pos":"dt."},{"zh":"会","py":"huì","vi":"buổi gặp mặt, bữa tiệc","pos":"dt."},{"zh":"结束","py":"jiéshù","vi":"kết thúc","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在街上，白家月和李文边散步边聊天儿。Bạch Gia Nguyệt và Lý Văn vừa đi dạo vừa trò chuyện trên đường phố.","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这个星期总是阴天，今天终于晴了。","py":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le.","vi":"Cả tuần nay trời đều âm u, cuối cùng hôm nay hửng nắng lên rồi."},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"现在天气好得很！我们去爬山怎么样？","py":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù páshān zěnmeyàng?","vi":"Thời tiết bây giờ thật tuyệt vời! Hôm nay chúng mình đi leo núi, em thấy thế nào?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好啊！又能锻炼身体，又能照好看的照片。","py":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn.","vi":"Được nhé! Vừa có thể tập thể dục vừa có thể chụp được ảnh đẹp."},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"那我带点儿水和吃的，咱们现在就去？","py":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?","vi":"Vậy anh sẽ mang theo một ít nước và đồ ăn nhé. Chúng mình đi luôn bây giờ à?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","py":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?","vi":"Em quay về thay giày thể thao, lấy áo khoác. Chúng mình có nên rủ chị Nhất Tuyết đi cùng không?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"好主意。给她打个电话吧。","py":"Hǎo zhǔyi. Gěi tā dǎ gè diànhuà ba.","vi":"Ý kiến hay đó. Hãy gọi điện cho chị ấy đi."},{"section":"Bài khóa 2","context":"在出租车上，王一雪和白家月在聊天儿。Vương Nhất Tuyết và Bạch Gia Nguyệt đang trò chuyện trên xe taxi.","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这些照片是谁给您照的？张张都非常好看。","py":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāngzhāng dōu fēicháng hǎokàn.","vi":"Ai đã chụp những bức ảnh này cho chị vậy? Tấm nào trông cũng đẹp."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"一飞。她对拍照一直很感兴趣，经常给我照相。","py":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng.","vi":"Nhất Phi đấy. Em ấy luôn hứng thú với nhiếp ảnh và thường xuyên chụp ảnh cho chị."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我喜欢您大笑的这张，看起来很漂亮。","py":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kàn qǐlái hěn piàoliang.","vi":"Em thực sự thích tấm chị đang cười to này, trông chị rất xinh."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","py":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng.","vi":"Chị cảm thấy tấm này hơi xấu, lúc đó chị không biết Nhất Phi đang chụp ảnh chị."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","py":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, páshān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba.","vi":"Những bức ảnh như thế này mới đẹp ạ. Em cũng thích chụp ảnh, khi đi leo núi em sẽ chụp vài tấm cho chị nhé."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好，我可以比较一下你们两个谁的水平高。","py":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng gè shéi de shuǐpíng gāo.","vi":"Được, vậy chị có thể so sánh xem ai trong hai em có trình độ chụp ảnh cao hơn."},{"section":"Bài khóa 3","context":"在山上，王一雪和白家月边走边聊。Vương Nhất Tuyết và Bạch Gia Nguyệt vừa đi vừa trò chuyện ở trên núi.","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月，这里挺漂亮的，咱们在这里拍照吧。","py":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba.","vi":"Gia Nguyệt, ở đây đẹp thật đấy, mình chụp vài tấm ở đây đi."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这边没有太阳，咱们去那边吧。","py":"Zhèbian méiyǒu tàiyáng, zánmen qù nàbian ba.","vi":"Bên này không có nắng, mình qua bên kia đi."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好。你觉得我站在这些树中间怎么样？","py":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?","vi":"Được thôi. Em thấy chị đứng giữa những cái cây này thì thế nào?"},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"挺好的。等一下，后边走过去两个人。","py":"Tǐng hǎo de. Děng yíxià, hòubian zǒu guòqù liǎng gè rén.","vi":"Đẹp đấy. Chị đợi một lát, phía sau chị có hai người đang đi qua."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我准备好了，你照的时候告诉我。","py":"Wǒ zhǔnbèihǎo le, nǐ zhào de shíhou gàosu wǒ.","vi":"Chị sẵn sàng rồi, hãy nói cho chị biết khi nào em chụp nhé."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"你不用看着我，想干什么都可以。","py":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ.","vi":"Chị không cần phải nhìn em đâu, cứ làm gì thấy tự nhiên nhất là được."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"树上飞来了几只鸟，我就看它们吧。","py":"Shùshang fēi láile jǐ zhī niǎo, wǒ jiù kàn tāmen ba.","vi":"Có mấy con chim vừa bay tới đậu trên cây, vậy chị sẽ ngắm chúng nhé."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"啊，手机没电了。","py":"A, shǒujī méi diàn le.","vi":"Ôi, điện thoại hết pin mất rồi."},{"section":"Bài khóa 4","context":"在咖啡厅里，王一雪给白家月发短信。Vương Nhất Tuyết gửi tin nhắn cho Bạch Gia Nguyệt trong quán cà phê.","audio":"05-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。不知道你对中国的音乐有没有兴趣？我送你一张明天下午音乐会的门票。音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。你觉得怎么样？","py":"Jiāyuè, wǒ shōudàole nǐ de nà fēng yóujiàn, yě kàndàole nǐ gěi wǒ zhào de zhàopiàn, zhāngzhāng dōu hěn piàoliang. Wǒ yǐjīng gàosule Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā. Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù? Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào. Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài. Nǐ juéde zěnmeyàng?","vi":"Chào Gia Nguyệt, chị đã nhận được email của em và xem những bức ảnh em chụp cho chị, tấm nào cũng đẹp cả. Chị đã nói với Nhất Phi rằng trình độ chụp ảnh của em tốt hơn cô ấy, cô ấy rất buồn về chuyện đó đấy, ha ha. Không biết em có hứng thú với âm nhạc Trung Hoa không. Chị tặng em một chiếc vé vào cửa của buổi hoà nhạc chiều mai. Buổi hoà nhạc hơn 7 giờ mới kết thúc, nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé, thưởng thức món ăn Trung Quốc do chị nấu. Em thấy sao?"}],"dialogQuestions":[],"grammar":{"g1":{"han":"程度补语（2）","py":"Chéngdù bǔyǔ (2)","title":"Bổ ngữ trình độ (2)","explain":"程度补语“得很”用在形容词的后面，表示程度高，一般用在口语中。\nBổ ngữ trình độ “得很” thường dùng trong văn nói, đặt sau tính từ, biểu thị mức độ cao.","examples":[{"zh":"现在天气好得很。","py":"Xiànzài tiānqì hǎo de hěn.","vi":"Thời tiết bây giờ đẹp cực kỳ.","hl":"得很"},{"zh":"房间里面热得很。","py":"Fángjiān lǐmian rè de hěn.","vi":"Trong phòng nóng lắm.","hl":"得很"},{"zh":"我觉得爬山累得很。","py":"Wǒ juéde páshān lèi de hěn.","vi":"Tôi thấy leo núi mệt ơi là mệt.","hl":"得很"}],"struct":"Tính từ + 得很","note":"Thường dùng trong khẩu ngữ để tăng cường sắc thái biểu đạt mức độ cao."},"g2":{"han":"量词重叠","py":"Liàngcí chóngdié","title":"Lượng từ lặp lại","explain":"汉语中很多量词可以重叠，用来强调在某个范围内的每个成员都具有某种特征，后面一般用“都”。\nTrong tiếng Trung Quốc, nhiều lượng từ có thể lặp lại để nhấn mạnh mỗi thành viên trong một phạm vi nhất định đều có một đặc điểm nào đó, phía sau thường dùng “都”.","examples":[{"zh":"这些照片张张都非常好看。","py":"Zhèxiē zhàopiàn zhāngzhāng dōu fēicháng hǎokàn.","vi":"Những bức ảnh này tấm nào cũng vô cùng đẹp.","hl":"张张……都"},{"zh":"这些苹果个个都很大。","py":"Zhèxiē píngguǒ gègè dōu hěn dà.","vi":"Những quả táo này quả nào cũng rất to.","hl":"个个都"},{"zh":"我想出去拍照，但是天天下雨。","py":"Wǒ xiǎng chūqù pāizhào, dànshì tiāntiān xiàyǔ.","vi":"Tôi muốn ra ngoài chụp ảnh, nhưng ngày nào trời cũng mưa.","hl":"天天"}],"struct":"Lượng từ lặp (AA) (+ 都) + Vị ngữ","note":"Ý nghĩa tương đương với “每 + lượng từ” (mỗi / cái nào cũng...)."},"g3":{"han":"存现句（3）","py":"Cúnxiànjù (3)","title":"Câu tồn hiện (3)","explain":"汉语中，叙述某个处所有人、事物出现或消失，可以用存现句。基本结构：处所词语+动词+趋向补语/结果补语+（动态助词）+数量短语+人/物。\nTrong tiếng Trung Quốc, để miêu tả sự xuất hiện hoặc biến mất của người hoặc sự vật tại một địa điểm nhất định, người ta sử dụng câu tồn hiện. Cấu trúc cơ bản: Từ ngữ chỉ nơi chốn + động từ + bổ ngữ xu hướng/bổ ngữ kết quả + (trợ từ động thái) + cụm từ chỉ số lượng + danh từ chỉ người/sự vật.","examples":[{"zh":"后边走过去两个人。","py":"Hòubian zǒu guòqù liǎng gè rén.","vi":"Phía sau có hai người đang đi qua.","hl":"走过去两个人"},{"zh":"前面开过来很多车。","py":"Qiánmian kāi guòlái hěn duō chē.","vi":"Phía trước có rất nhiều xe chạy tới.","hl":"开过来很多车"},{"zh":"楼上下来了几个人。","py":"Lóushàng xiàlái le jǐ gè rén.","vi":"Trên lầu đi xuống mấy người.","hl":"下来了几个人"}],"struct":"Từ ngữ nơi chốn + Động từ + Bổ ngữ xu hướng/kết quả (+ 了/着) + Số lượng + Danh từ","note":"Danh từ chỉ người/vật xuất hiện hoặc biến mất ở cuối câu thường mang tính bất định (có số lượng từ)."},"g4":{"han":"紧缩复句“……了……就……”","py":"Jǐnsuō fùjù “...le... jiù...”","title":"Câu ghép rút gọn “……了……就……”","explain":"紧缩复句“……了……就……”表示两个动作行为紧接着发生。如果第二个动作行为也已经完成，则需要在句尾再加一个“了”。基本结构：动词1+了……就+动词2……。\nCâu ghép rút gọn sử dụng cấu trúc “……了……就……” biểu thị hai hành động xảy ra liên tiếp. Nếu hành động thứ hai cũng đã hoàn thành thì cần thêm “了” vào cuối câu. Cấu trúc cơ bản: Động từ 1 + 了……就 + động từ 2……","examples":[{"zh":"你听完了音乐会就来我家吃饭。","py":"Nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn.","vi":"Nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé.","hl":"听完了……就来"},{"zh":"我吃了早饭就去学校了。","py":"Wǒ chīle zǎofàn jiù qù xuéxiào le.","vi":"Tôi ăn sáng xong là đi học luôn rồi.","hl":"吃了……就去……了"},{"zh":"昨天我们下了课就回家了。","py":"Zuótiān wǒmen xiàle kè jiù huíjiā le.","vi":"Hôm qua chúng tôi tan học xong là về nhà luôn.","hl":"下了课就回家了"}],"struct":"(Chủ ngữ +) Động từ 1 + 了 + (Tân ngữ 1) + 就 + Động từ 2 (+ 了)","note":"Hành động 2 xảy ra nối tiếp ngay sau khi hành động 1 hoàn tất."}},"grammarQuiz":[{"id":"hsk3_b5_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他的拍照 (____) 比我高多了。","opts":[{"t":"水平","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án C (水平): ‘Trình độ chụp ảnh của anh ấy cao hơn tôi nhiều.’"},{"id":"hsk3_b5_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 了一封学校的邮件。","opts":[{"t":"收到","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false}],"exp":"Đáp án E (收到): ‘Tôi đã nhận được một bức email của nhà trường.’"},{"id":"hsk3_b5_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"明天又是星期天，我不知道应该 (____) 什么。","opts":[{"t":"干","ok":true},{"t":"照","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án B (干): ‘Ngày mai lại là Chủ nhật rồi, tôi không biết nên làm gì.’"},{"id":"hsk3_b5_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我还没准备好呢，我看着你的时候你再 (____)。","opts":[{"t":"照","ok":true},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án A (照): ‘Tôi vẫn chưa chuẩn bị xong đâu, lúc tôi nhìn bạn thì bạn hãy chụp nhé.’"},{"id":"hsk3_b5_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我觉得前两张照片好看，第三张有点儿 (____)，你选前两张吧。","opts":[{"t":"难看","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án D (难看): ‘Tôi thấy hai tấm đầu đẹp, tấm thứ ba hơi xấu, bạn chọn hai tấm đầu đi.’"},{"id":"hsk3_b5_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 他们的飞机到了吗？\nB: (____) 到了，晚点了五个多小时。","opts":[{"t":"终于","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án C (终于): ‘Cuối cùng cũng tới rồi, trễ mất hơn 5 tiếng đồng hồ.’"},{"id":"hsk3_b5_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 为什么我照的照片 (____) 不好看？\nB: 我姐姐会拍照，我让她教教你。","opts":[{"t":"总是","ok":true},{"t":"结束","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án B (总是): ‘Sao ảnh tôi chụp lúc nào cũng không đẹp nhỉ?’"},{"id":"hsk3_b5_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 喂，你在哪儿？怎么没接电话？\nB: 我在看电影呢，还有十分钟就 (____) 了。","opts":[{"t":"结束","ok":true},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án A (结束): ‘Tôi đang xem phim, còn 10 phút nữa là kết thúc rồi.’"},{"id":"hsk3_b5_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 假期我想去北京，也想去上海，不知道怎么选。\nB: 我帮你 (____) 一下。","opts":[{"t":"比较","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false}],"exp":"Đáp án E (比较): ‘Để tôi giúp bạn so sánh một chút.’"},{"id":"hsk3_b5_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我有两张音乐会的票，咱们一起去吧。\nB: 我对音乐不 (____)。家月喜欢，你问问她。","opts":[{"t":"感兴趣","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án D (感兴趣): ‘Tôi không hứng thú với âm nhạc lắm. Gia Nguyệt thích đấy, bạn hỏi cô ấy đi.’"},{"id":"hsk3_b5_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"今天天气怎么样？","opts":[{"t":"C 晴天","ok":true},{"t":"A 阴天","ok":false},{"t":"B 很热","ok":false}],"exp":"Bạch Gia Nguyệt nói: “这个星期总是阴天，今天终于晴了。”"},{"id":"hsk3_b5_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月为什么要给王一雪打电话？","opts":[{"t":"C 找她爬山","ok":true},{"t":"A 找她吃饭","ok":false},{"t":"B 问她天气","ok":false}],"exp":"Hai người rủ chị Nhất Tuyết cùng đi leo núi."},{"id":"hsk3_b5_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪和白家月在做什么？","opts":[{"t":"C 看照片","ok":true},{"t":"A 拍照","ok":false},{"t":"B 买相机","ok":false}],"exp":"Hai người đang xem các bức ảnh trên xe taxi."},{"id":"hsk3_b5_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"白家月和王一飞都喜欢做什么？","opts":[{"t":"A 拍照","ok":true},{"t":"B 爬山","ok":false},{"t":"C 比较拍照水平","ok":false}],"exp":"Cả Vương Nhất Phi và Bạch Gia Nguyệt đều thích chụp ảnh."},{"id":"hsk3_b5_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月和王一雪在做什么？","opts":[{"t":"A 拍照","ok":true},{"t":"B 看鸟","ok":false},{"t":"C 找手机","ok":false}],"exp":"Hai người đang chụp ảnh trên núi."},{"id":"hsk3_b5_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"拍照的时候，白家月让王一雪干什么？","opts":[{"t":"C 想干什么就干什么","ok":true},{"t":"A 看着她","ok":false},{"t":"B 看着鸟","ok":false}],"exp":"Bạch Gia Nguyệt nói: “你不用看着我，想干什么都可以。”"},{"id":"hsk3_b5_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪觉得照片怎么样？","opts":[{"t":"B 每张都很漂亮","ok":true},{"t":"A 她还没看到","ok":false},{"t":"C 没有一飞照得好","ok":false}],"exp":"Vương Nhất Tuyết viết: “也看到了你给我照的照片，张张都很漂亮。”"},{"id":"hsk3_b5_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪送给白家月什么了？","opts":[{"t":"B 一张门票","ok":true},{"t":"A 一些照片","ok":false},{"t":"C 她做的中国菜","ok":false}],"exp":"Vương Nhất Tuyết viết: “我送你一张明天下午音乐会的门票。”"}],"chars":["总","是","终","于","爬","山","锻","炼","照","鞋","大","衣","拍","感","兴","趣","相","难","看","比","较","水","平","太","阳","树","干","电","收","到","封","邮","件","过","哈","音","乐","会","结","束","这","样","的","片","才","好"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 45): “又”在这个句子中表示这个情况规律性地重复出现。Từ “又” trong câu dùng để biểu thị tình huống lặp lại mang tính quy luật.","Món quà của Tiểu Ngữ (trang 46, video 5-1): 大银幕上的中国故事 — Câu chuyện Trung Hoa qua màn ảnh rộng.","Câu hỏi thảo luận Bài khóa 1: (1) 白家月觉得爬山怎么样？ (2) 李文要带什么东西？ (3) 白家月要先回去做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月喜欢哪张照片？为什么？ (2) 王一雪为什么不喜欢这张照片？ (3) 爬山的时候，白家月打算做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪想站在哪儿拍照？ (2) 白家月为什么要等一下再照？ (3) 白家月的手机怎么了？","Câu hỏi thảo luận Bài khóa 4: (1) 王一雪觉得白家月的拍照水平怎么样？ (2) 音乐会什么时候结束？ (3) 听完音乐会，白家月可能做什么？"],"workbook":null},"6":{"pages":"47–56","titleZh":"高铁上还可以点外卖","titlePy":"Gāotiě shàng hái kěyǐ diǎn wàimài","titleVi":"Trên tàu cao tốc vẫn có thể đặt đồ ăn giao tận nơi","goals":["能听懂并介绍交通方式的特点和出行体验。Có thể nghe hiểu và giới thiệu được đặc điểm của các phương tiện giao thông và trải nghiệm đi lại.","能听懂并使用“如果”表达假设的情况和结果。Có thể nghe hiểu và sử dụng được “如果” để biểu đạt tình huống giả định và kết quả của nó.","掌握“越来越”短语，能描述事物的变化趋势。Nắm vững cấu trúc “越来越” để miêu tả xu hướng thay đổi của sự vật.","了解中国的现代交通方式——高铁。Hiểu về tàu cao tốc – phương thức giao thông hiện đại của Trung Quốc."],"words":[{"zh":"该","py":"gāi","vi":"nên","pos":"đtnn."},{"zh":"打算","py":"dǎsuàn","vi":"dự định, kế hoạch","pos":"đgt./dt."},{"zh":"高铁","py":"gāotiě","vi":"tàu cao tốc","pos":"dt."},{"zh":"行","py":"xíng","vi":"được, có thể","pos":"đgt./tt."},{"zh":"路口","py":"lùkǒu","vi":"giao lộ, lối rẽ, đầu đường","pos":"dt."},{"zh":"小心","py":"xiǎoxīn","vi":"cẩn thận, chú ý","pos":"đgt./tt."},{"zh":"迟到","py":"chídào","vi":"đến muộn","pos":"đgt."},{"zh":"红绿灯","py":"hóng-lǜdēng","vi":"đèn giao thông, đèn xanh đèn đỏ","pos":"dt."},{"zh":"后来","py":"hòulái","vi":"sau đó, về sau","pos":"dt."},{"zh":"急","py":"jí","vi":"gấp, lo lắng","pos":"tt./đgt."},{"zh":"如果","py":"rúguǒ","vi":"nếu","pos":"liên."},{"zh":"以前","py":"yǐqián","vi":"trước đây","pos":"dt."},{"zh":"耳机","py":"ěrjī","vi":"tai nghe","pos":"dt."},{"zh":"充电宝","py":"chōngdiànbǎo","vi":"sạc dự phòng","pos":"dt."},{"zh":"常用","py":"cháng yòng","vi":"thường dùng","pos":""},{"zh":"越","py":"yuè","vi":"càng... (càng...)","pos":"phó."},{"zh":"分开","py":"fēnkāi","vi":"tách ra","pos":"đgt."},{"zh":"检查","py":"jiǎnchá","vi":"kiểm tra","pos":"đgt."},{"zh":"刷","py":"shuā","vi":"quét (thẻ, mã QR...)","pos":"đgt."},{"zh":"检票","py":"jiǎnpiào","vi":"kiểm vé","pos":"đgt."},{"zh":"电梯","py":"diàntī","vi":"thang máy","pos":"dt."},{"zh":"放假","py":"fàngjià","vi":"nghỉ phép, nghỉ lễ","pos":"đgt."},{"zh":"沙发","py":"shāfā","vi":"ghế sofa","pos":"dt."},{"zh":"安静","py":"ānjìng","vi":"yên tĩnh","pos":"tt."},{"zh":"选择","py":"xuǎnzé","vi":"chọn, lựa chọn","pos":"đgt."},{"zh":"必须","py":"bìxū","vi":"phải, nhất định phải","pos":"phó."},{"zh":"北京南站","py":"Běijīng Nán Zhàn","vi":"ga Bắc Kinh Nam","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"在咖啡厅里，李文和白家月在聊天儿。Lý Văn và Bạch Gia Nguyệt đang trò chuyện trong quán cà phê.","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，咱们该买去上海的票了。你打算怎么去上海？","py":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?","vi":"Gia Nguyệt, chúng ta nên mua vé đi Thượng Hải rồi. Em dự định đi bằng phương tiện gì?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我还没坐过高铁，咱们坐高铁去，怎么样？","py":"Wǒ hái méi zuò guo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?","vi":"Em chưa bao giờ đi tàu cao tốc cả. Hay là chúng mình đi bằng tàu cao tốc nhé?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"没问题，从北京到上海的高铁很多，非常方便。","py":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","vi":"Không vấn đề gì. Có rất nhiều chuyến tàu cao tốc từ Bắc Kinh đi Thượng Hải, rất thuận tiện."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"行！怎么买高铁票？","py":"Xíng! Zěnme mǎi gāotiěpiào?","vi":"Được đó. Chúng mình mua vé tàu cao tốc như thế nào?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"用手机App就能买。给我你的护照，我帮你买。","py":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.","vi":"Có thể mua trên ứng dụng di động. Đưa hộ chiếu của em đây, anh sẽ mua giúp cho."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"早就听说过高铁，终于可以坐上了。","py":"Zǎo jiù tīngshuō guo gāotiě, zhōngyú kěyǐ zuò shàng le.","vi":"Em đã nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi tàu cao tốc."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"高铁又快又舒服，你一定会喜欢的。","py":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.","vi":"Tàu cao tốc vừa nhanh vừa thoải mái, chắc chắn em sẽ thích thôi."},{"section":"Bài khóa 2","context":"在车上，刘明开车送白家月和李文去高铁站。Ở trên xe, Lưu Minh lái xe đưa Bạch Gia Nguyệt và Lý Văn đến ga tàu cao tốc.","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"过了前面的路口就到高铁站了。","py":"Guòle qiánmian de lùkǒu jiù dào gāotiězhàn le.","vi":"Đi qua giao lộ phía trước là tới ga tàu cao tốc rồi."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我看见了。马上就到了，这条路车很多，您小心点儿。","py":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.","vi":"Em thấy rồi. Sắp đến nơi rồi, đường này nhiều xe quá, anh đi cẩn thận một chút nhé."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好，你们还有一个小时，应该不会迟到的。","py":"Hǎo, nǐmen hái yǒu yí gè xiǎoshí, yīnggāi bú huì chídào de.","vi":"Được. Còn một tiếng nữa, nên chắc sẽ không bị muộn đâu."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我发现这条路车多，红绿灯也多。","py":"Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō.","vi":"Em thấy con đường này nhiều xe, đèn giao thông cũng nhiều."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是啊，这条路我走过一次，后来再也不走了。","py":"Shì a, zhè tiáo lù wǒ zǒu guo yí cì, hòulái zài yě bù zǒu le.","vi":"Đúng vậy, anh đã đi đường này một lần, về sau không bao giờ đi nữa."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那您今天为什么走了这条路？","py":"Nà nín jīntiān wèi shénme zǒule zhè tiáo lù?","vi":"Vậy tại sao hôm nay anh lại đi đường này?"},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我一急就走错了。如果没走错，二十分钟以前就到了。","py":"Wǒ yì jí jiù zǒu cuò le. Rúguǒ méi zǒu cuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Tại anh bị cuống nên đã đi nhầm. Nếu không đi nhầm thì chúng ta đã đến từ 20 phút trước rồi."},{"section":"Bài khóa 3","context":"在高铁站，李文和白家月排队安检、检票。Lý Văn và Bạch Gia Nguyệt xếp hàng kiểm tra an ninh và soát vé ở ga tàu cao tốc.","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"李文，我的耳机没电了，你有充电宝吗？","py":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","vi":"Lý Văn, tai nghe của em hết pin rồi. Anh có sạc dự phòng không?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"有，这些常用的东西我都放在包里了，我给你拿。","py":"Yǒu, zhèxiē cháng yòng de dōngxi wǒ dōu fàng zài bāo li le, wǒ gěi nǐ ná.","vi":"Có, những đồ thường dùng anh đều để trong túi, để anh lấy cho em."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"前面的人越来越多。","py":"Qiánmian de rén yuèláiyuè duō.","vi":"Phía trước ngày càng có nhiều người hơn."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"对，马上就进高铁站了。咱们一起走，别分开。","py":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","vi":"Đúng vậy, chúng mình sắp tới ga tàu cao tốc rồi. Hãy đi cùng nhau, đừng để bị lạc nhau nhé."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好，你检查一下，高铁票都拿好了吗？","py":"Hǎo, nǐ jiǎnchá yíxià, gāotiěpiào dōu náhǎo le ma?","vi":"Được, anh kiểm tra thử xem vé tàu cao tốc đã mang theo chưa?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"不用拿票，刷护照就能检票进站。","py":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn.","vi":"Không cần cầm vé đâu, chỉ cần quét hộ chiếu của mình để vào ga."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"去哪里检票？","py":"Qù nǎlǐ jiǎnpiào?","vi":"Vậy soát vé ở đâu?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"检票口在二层，我们一会儿坐电梯上去。","py":"Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqù.","vi":"Cửa soát vé ở tầng hai, lát nữa chúng mình sẽ đi thang máy lên."},{"section":"Bài khóa 4","context":"在家里，白家月给安妮打电话介绍自己的旅行。Trong nhà, Bạch Gia Nguyệt gọi điện cho Annie để giới thiệu về chuyến đi của mình.","audio":"06-7.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这次放假，我去了北京，还去了上海。我是从北京南站坐高铁去的上海。我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。坐累了就站一会儿，饿了就点外卖。对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。现在喜欢坐高铁的人越来越多。我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","py":"Zhè cì fàngjià, wǒ qùle Běijīng, hái qùle Shànghǎi. Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi. Wǒ juéde zuò zài gāotiě shang gēn zuò zài jiālǐ de shāfā shang yíyàng, yòu ānjìng yòu shūfu. Zuò lèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài. Duì, nǐ méi tīngcuò, gāotiě shang kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xiàchē, fúwùyuán jiù huì gěi nǐ ná guòlái. Xiànzài xǐhuan zuò gāotiě de rén yuèláiyuè duō. Wǒ bàmā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě.","vi":"Trong kỳ nghỉ lần này, tôi đã đến Bắc Kinh và cũng ghé thăm Thượng Hải. Tôi đi tàu cao tốc từ ga Bắc Kinh Nam đến Thượng Hải. Tôi cảm thấy, ngồi trên tàu có cảm giác giống hệt như đang ngồi trên ghế sofa ở nhà vậy, vừa yên tĩnh vừa thoải mái. Ngồi mỏi rồi thì đứng dậy một lát, đói rồi thì đặt đồ ăn giao tận nơi. Đúng rồi, bạn không nghe nhầm đâu, bạn có thể đặt đồ ăn giao tận nơi ở trên tàu cao tốc. Chỉ cần chọn ga bạn đến và món ăn bạn muốn, bạn không cần phải xuống tàu khi tàu đến ga, nhân viên sẽ mang đến tận chỗ cho bạn. Hiện nay, ngày càng có nhiều người thích đi du lịch bằng tàu cao tốc. Khi bố mẹ tôi đến Trung Quốc chơi, tôi nhất định sẽ đưa họ đi thử tàu cao tốc một chuyến."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定格式“该……了”","py":"Gùdìng géshì “gāi... le”","title":"Cấu trúc cố định “该……了”","explain":"固定格式“该……了”表示到了需要做某事的时候，多在口语中使用。\nCấu trúc cố định “该……了” thường dùng trong văn nói, biểu thị đã đến lúc cần làm một việc gì đó.","examples":[{"zh":"咱们该买去上海的票了。","py":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vi":"Chúng ta nên mua vé đi Thượng Hải rồi.","hl":"该……了"},{"zh":"八点了，该上课了。","py":"Bā diǎn le, gāi shàngkè le.","vi":"8 giờ rồi, đến giờ vào học rồi.","hl":"该……了"},{"zh":"已经很晚了，我该睡觉了。","py":"Yǐjīng hěn wǎn le, wǒ gāi shuìjiào le.","vi":"Đã muộn lắm rồi, tôi nên đi ngủ thôi.","hl":"该……了"}],"struct":"(Chủ ngữ +) 该 + Động từ / Cụm động từ + 了","note":"Thường dùng với ý nhắc nhở đã đến thời điểm thích hợp để làm việc gì."},"g2":{"han":"假设复句“如果……，就……”","py":"Jiǎshè fùjù “rúguǒ..., jiù...”","title":"Câu ghép giả định “如果……，就……”","explain":"假设复句“如果……，就……”中，“如果”后面的分句是一个假设，“就”后面的分句是在这种假设情况下产生的结果。注意，第二个分句的主语要放在“就”的前面。\nTrong câu ghép giả định “如果……，就……”, mệnh đề đứng sau “如果” là giả thuyết, mệnh đề đứng sau “就” là kết quả có được dựa trên giả thuyết đó. Lưu ý, chủ ngữ của mệnh đề thứ hai phải đặt trước “就”.","examples":[{"zh":"如果没走错，二十分钟以前就到了。","py":"Rúguǒ méi zǒu cuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Nếu không đi nhầm thì 20 phút trước đã tới rồi.","hl":"如果……，……就"},{"zh":"如果你需要帮忙，就给我打电话。","py":"Rúguǒ nǐ xūyào bāngmáng, jiù gěi wǒ dǎ diànhuà.","vi":"Nếu bạn cần giúp đỡ thì gọi điện cho tôi.","hl":"如果……，就"},{"zh":"如果有时间，我就去上海玩几天。","py":"Rúguǒ yǒu shíjiān, wǒ jiù qù Shànghǎi wán jǐ tiān.","vi":"Nếu có thời gian, tôi sẽ đi Thượng Hải chơi vài ngày.","hl":"如果……，……就"}],"struct":"如果 + Mệnh đề giả thuyết，(Chủ ngữ 2 +) 就 + Mệnh đề kết quả","note":"Chú ý vị trí chủ ngữ thứ hai luôn đặt trước “就”."},"g3":{"han":"固定短语“越来越”","py":"Gùdìng duǎnyǔ “yuèláiyuè”","title":"Cụm từ cố định “越来越”","explain":"固定短语“越来越”的后面加上形容词或心理动词，表示随着时间的推移而在程度上发生变化。形容词或心理动词前都不能再加程度副词。\nCụm từ cố định “越来越” đứng trước tính từ hoặc động từ chỉ tâm lý, biểu thị mức độ thay đổi theo thời gian. Trước tính từ hoặc động từ chỉ tâm lý không được thêm phó từ chỉ mức độ.","examples":[{"zh":"前面的人越来越多。","py":"Qiánmian de rén yuèláiyuè duō.","vi":"Người phía trước ngày càng đông.","hl":"越来越多"},{"zh":"我越来越喜欢这里的生活了。","py":"Wǒ yuèláiyuè xǐhuan zhèlǐ de shēnghuó le.","vi":"Tôi ngày càng thích cuộc sống ở đây rồi.","hl":"越来越喜欢"},{"zh":"她越来越高，也越来越漂亮了。","py":"Tā yuèláiyuè gāo, yě yuèláiyuè piàoliang le.","vi":"Cô ấy ngày càng cao và cũng ngày càng xinh đẹp hơn.","hl":"越来越……"}],"struct":"Chủ ngữ + 越来越 + Tính từ / Động từ tâm lý (+ 了)","note":"Không dùng thêm các phó từ mức độ như 很, 非常 trước tính từ sau “越来越”."}},"grammarQuiz":[{"id":"hsk3_b6_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我没带钱，可以 (____) 信用卡吗？","opts":[{"t":"刷","ok":true},{"t":"该","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án B (刷): ‘Tôi không mang tiền mặt, có thể quẹt thẻ tín dụng không?’"},{"id":"hsk3_b6_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"不用太早，星期五 (____) 买票就可以。","opts":[{"t":"以前","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false}],"exp":"Đáp án E (以前): ‘Không cần quá sớm, mua vé trước thứ Sáu là được rồi.’"},{"id":"hsk3_b6_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"飞机马上就要起飞了，你的手机 (____) 关机了。","opts":[{"t":"该","ok":true},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án A (该): ‘Máy bay sắp cất cánh rồi, điện thoại của bạn đến lúc phải tắt nguồn rồi.’"},{"id":"hsk3_b6_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"前面的路口人很多，你开慢一点儿，别 (____)。","opts":[{"t":"急","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án C (急): ‘Ngã tư phía trước rất đông người, bạn lái chậm chút, đừng vội.’"},{"id":"hsk3_b6_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她开始的时候说要来，(____) 打电话说不来了。","opts":[{"t":"后来","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án D (后来): ‘Ban đầu cô ấy bảo sẽ đến, sau đó gọi điện nói không đến nữa.’"},{"id":"hsk3_b6_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你一个人开车，路上要 (____)。\nB: 好的，谢谢。","opts":[{"t":"小心","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án C (小心): ‘Bạn tự lái xe một mình, đi đường phải cẩn thận nhé.’"},{"id":"hsk3_b6_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 马上就要出门了，你再 (____) 一下，护照什么的都带了吧？\nB: 都带了，放在包里了。","opts":[{"t":"检查","ok":true},{"t":"选择","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án B (检查): ‘Sắp ra khỏi nhà rồi, bạn kiểm tra lại lần nữa xem hộ chiếu các thứ mang đủ chưa?’"},{"id":"hsk3_b6_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 明天晚上六点的火车，你几点出门？\nB: 我 (____) 四点半出门，晚一点儿也没关系。","opts":[{"t":"打算","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false}],"exp":"Đáp án E (打算): ‘Tôi dự định 4 giờ rưỡi ra khỏi nhà, muộn hơn chút cũng không sao.’"},{"id":"hsk3_b6_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 坐高铁四个多小时，坐飞机两个小时，你想坐什么？\nB: 高铁站比机场近多了，我还是想 (____) 高铁。","opts":[{"t":"选择","ok":true},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án A (选择): ‘Ga tàu cao tốc gần hơn sân bay nhiều, tôi vẫn muốn chọn đi tàu cao tốc.’"},{"id":"hsk3_b6_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我能坐在你旁边吗？\nB: 不行，咱们的票是分开的，你 (____) 坐在前面。","opts":[{"t":"必须","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án D (必须): ‘Không được, vé của chúng ta tách rời nhau, bạn bắt buộc phải ngồi ở phía trước.’"},{"id":"hsk3_b6_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文和白家月打算怎么去上海？","opts":[{"t":"C 坐高铁","ok":true},{"t":"A 开车","ok":false},{"t":"B 坐飞机","ok":false}],"exp":"Bạch Gia Nguyệt đề nghị: “咱们坐高铁去，怎么样？”"},{"id":"hsk3_b6_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文觉得高铁怎么样？","opts":[{"t":"B 又快又舒服","ok":true},{"t":"A 高铁票很贵","ok":false},{"t":"C 买票不方便","ok":false}],"exp":"Lý Văn nói: “高铁又快又舒服，你一定会喜欢的。”"},{"id":"hsk3_b6_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月现在在哪儿？","opts":[{"t":"C 在刘明的车上","ok":true},{"t":"A 在高铁站","ok":false},{"t":"B 在出租车上","ok":false}],"exp":"Bối cảnh: Lưu Minh đang lái xe đưa hai người đến ga tàu cao tốc."},{"id":"hsk3_b6_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"如果没走错，他们什么时候到？","opts":[{"t":"B 二十分钟以前就到了","ok":true},{"t":"A 马上就到了","ok":false},{"t":"C 一个小时以前就到了","ok":false}],"exp":"Lưu Minh nói: “如果没走错，二十分钟以前就到了。”"},{"id":"hsk3_b6_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"常用的东西李文放在哪里？","opts":[{"t":"B 包里","ok":true},{"t":"A 手里","ok":false},{"t":"C 行李箱里","ok":false}],"exp":"Lý Văn nói: “这些常用的东西我都放在包里了”."},{"id":"hsk3_b6_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们在哪里检票进站？","opts":[{"t":"C 二层检票口","ok":true},{"t":"A 车站门口","ok":false},{"t":"B 一层门口","ok":false}],"exp":"Lý Văn nói: “检票口在二层，我们一会儿坐电梯上去。”"},{"id":"hsk3_b6_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"白家月觉得坐高铁怎么样？","opts":[{"t":"B 高铁上很舒服","ok":true},{"t":"A 高铁站很远","ok":false},{"t":"C 高铁上人很多","ok":false}],"exp":"Bài khóa 4: “我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。”"},{"id":"hsk3_b6_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"喜欢坐高铁的人多不多？","opts":[{"t":"C 越来越多","ok":true},{"t":"A 不太多","ok":false},{"t":"B 有点儿多","ok":false}],"exp":"Bài khóa 4: “现在喜欢坐高铁的人越来越多。”"}],"chars":["该","打","算","高","铁","行","路","口","小","心","迟","到","红","绿","灯","后","来","急","如","果","以","前","耳","机","充","电","宝","常","用","越","分","开","检","查","刷","票","梯","放","假","沙","发","安","静","选","择","必","须","北","京","南","站","上","还","可","点","外","卖"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 48): “上”在这里不是表示方向，而是表示实现了某个目标或愿望。Từ “上” ở đây không biểu thị phương hướng, mà biểu thị đạt được một mục tiêu hoặc mong muốn nào đó (ví dụ: 坐上了).","Món quà của Tiểu Ngữ (trang 55, video 6-1): 12306是什么？ — 12306 là gì? (nền tảng đặt vé đường sắt chính thức của Trung Quốc).","Tổng kết học tập Bài 4–6 (trang 55–56): 10 điểm ngữ pháp gồm 一……也/都+不/没……, 比较句(9) 跟……一样, 除了……(以外)，……都/还/也……, 程度补语(2) 得很, 量词重叠, 存现句(3), 紧缩复句 ……了……就……, 该……了, 如果……，就…… và 越来越.","Câu hỏi thảo luận Bài khóa 1: (1) 李文和白家月打算去哪个城市？ (2) 白家月为什么想坐高铁？ (3) 他们打算怎么买高铁票？","Câu hỏi thảo luận Bài khóa 2: (1) 刘明为什么说“应该不会迟到”？ (2) 白家月觉得这条路有什么问题？ (3) 刘明为什么今天走了这条路？","Câu hỏi thảo luận Bài khóa 3: (1) 白家月为什么要用充电宝？ (2) 他们怎么检票进站？ (3) 他们怎么去检票口？","Câu hỏi thảo luận Bài khóa 4: (1) 白家月是怎么去上海的？ (2) 高铁上怎么点外卖？ (3) 白家月想带谁坐高铁？"],"workbook":null},"7":{"pages":"57–66","titleZh":"那条裙子比短裤更好看","titlePy":"Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","titleVi":"Chiếc váy đó đẹp hơn quần soóc","goals":["能听懂并介绍购物的经历。Có thể nghe hiểu và giới thiệu được trải nghiệm mua sắm.","能听懂并评价商品的特点。Có thể nghe hiểu và đánh giá được đặc điểm của sản phẩm.","掌握比较句（10）的用法，能对商品进行比较。Nắm vững cách dùng câu so sánh (10), có thể tiến hành so sánh sản phẩm.","了解中国人的购物方式。Hiểu về phương thức mua sắm của người Trung Quốc."],"words":[{"zh":"辆","py":"liàng","vi":"chiếc (dùng cho xe cộ)","pos":"lượng."},{"zh":"自行车","py":"zìxíngchē","vi":"xe đạp","pos":"dt."},{"zh":"旧","py":"jiù","vi":"cũ","pos":"tt."},{"zh":"矮","py":"ǎi","vi":"thấp, lùn","pos":"tt."},{"zh":"试","py":"shì","vi":"thử","pos":"đgt."},{"zh":"黄色","py":"huángsè","vi":"màu vàng","pos":"dt."},{"zh":"短裤","py":"duǎnkù","vi":"quần soóc","pos":"dt."},{"zh":"大小","py":"dàxiǎo","vi":"kích cỡ","pos":"dt."},{"zh":"合适","py":"héshì","vi":"phù hợp","pos":"tt."},{"zh":"裙子","py":"qúnzi","vi":"váy, đầm","pos":"dt."},{"zh":"更","py":"gèng","vi":"càng, hơn","pos":"phó."},{"zh":"决定","py":"juédìng","vi":"quyết định","pos":"đgt./dt."},{"zh":"西瓜","py":"xīguā","vi":"dưa hấu","pos":"dt."},{"zh":"新鲜","py":"xīnxiān","vi":"tươi, tươi mới","pos":"tt."},{"zh":"甜","py":"tián","vi":"ngọt","pos":"tt."},{"zh":"公斤","py":"gōngjīn","vi":"kilôgam","pos":"lượng."},{"zh":"冰","py":"bīng","vi":"đông, đá","pos":"đgt./dt."},{"zh":"极","py":"jí","vi":"cực kỳ","pos":"phó."},{"zh":"斤","py":"jīn","vi":"cân (0,5 kilôgam)","pos":"lượng."},{"zh":"香蕉","py":"xiāngjiāo","vi":"chuối tiêu","pos":"dt."},{"zh":"一共","py":"yígòng","vi":"tổng cộng","pos":"phó."},{"zh":"毛","py":"máo","vi":"hào (đơn vị tiền tệ)","pos":"lượng."},{"zh":"结婚","py":"jiéhūn","vi":"kết hôn","pos":"đgt."},{"zh":"不但","py":"búdàn","vi":"không những","pos":"liên."},{"zh":"而且","py":"érqiě","vi":"mà còn","pos":"liên."},{"zh":"声","py":"shēng","vi":"tiếng (dùng cho âm thanh), âm thanh","pos":"lượng./dt."},{"zh":"开机","py":"kāijī","vi":"mở máy, bật máy","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，王一雪和刘明商量去买东西。Vương Nhất Tuyết và Lưu Minh đang ở trong nhà bàn bạc về việc đi mua đồ.","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","py":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlái yǒudiǎnr jiù le.","vi":"Chiếc xe đạp này mua khi Tiểu Tuyết được 8 tuổi, nhìn cũng hơi cũ rồi."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是啊，她现在长高了，这辆车已经太矮了。","py":"Shì a, tā xiànzài zhǎnggāo le, zhè liàng chē yǐjīng tài ǎi le.","vi":"Ừ, con bé cao lên rồi, chiếc xe này giờ bị thấp quá."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"商场里开了一家自行车店，咱们给她买辆新的吧。","py":"Shāngchǎng li kāile yì jiā zìxíngchēdiàn, zánmen gěi tā mǎi liàng xīn de ba.","vi":"Có cửa hàng xe đạp mới mở trong trung tâm thương mại, mình hãy mua cho con một cái mới đi."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好，咱们带小雪一起去，让她试一下。","py":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià.","vi":"Được, mình hãy đưa Tiểu Tuyết đi cùng để con bé có thể đi thử."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那今天就去吧！我也想再看看衣服。咱们怎么去？","py":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?","vi":"Vậy thì đi luôn hôm nay đi! Em cũng muốn xem quần áo. Chúng ta đi bằng gì nhỉ?"},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"商场不远，咱们可以走着去。","py":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","vi":"Trung tâm thương mại không xa lắm, mình có thể đi bộ đến đó."},{"section":"Bài khóa 2","context":"在商场，刘明和王一雪买完自行车，又来挑选衣服。Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua xong xe đạp rồi lại chọn quần áo.","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你看我穿这条黄色的短裤好看吗？","py":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","vi":"Anh có nghĩ chiếc quần soóc màu vàng này hợp với em không?"},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"大小合适，但我觉得那条裙子比短裤更好看。","py":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","vi":"Kích cỡ thì vừa đấy, nhưng anh nghĩ chiếc váy kia trông đẹp hơn chiếc quần soóc này."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"裙子比短裤贵一点儿。","py":"Qúnzi bǐ duǎnkù guì yìdiǎnr.","vi":"Váy đắt hơn quần soóc một chút."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"贵多少？","py":"Guì duōshao?","vi":"Đắt hơn bao nhiêu?"},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"裙子480，短裤400。","py":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","vi":"Váy giá 480 đồng, còn quần soóc giá 400 đồng."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","py":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn.","vi":"Váy không đắt hơn quần soóc bao nhiêu cả, hãy lấy chiếc váy đi, em mặc váy trông đẹp hơn."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我多看看再决定。你看，那边有买二送一！","py":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbian yǒu mǎi èr sòng yī!","vi":"Em sẽ xem thêm một chút nữa trước khi quyết định. Anh nhìn xem, đằng kia có chương trình “Mua hai tặng một” kìa!"},{"section":"Bài khóa 3","context":"在商店，王一雪在买东西。Vương Nhất Tuyết đang mua đồ ở cửa hàng.","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"西瓜又大又新鲜，不甜不要钱！","py":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!","vi":"Dưa hấu vừa to vừa tươi. Không ngọt không lấy tiền!"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"西瓜看起来不错，怎么卖？","py":"Xīguā kàn qǐlái búcuò, zěnme mài?","vi":"Dưa hấu trông ngon đấy, bán như thế nào vậy?"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","py":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jíle!","vi":"Năm đồng một cân. Đây, cô hãy thử miếng dưa hấu ướp lạnh này đi, nó cực kỳ ngọt!"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","py":"Shì tǐng tián de! Bāng wǒ xuǎn gè dà diǎnr de, zài lái liǎng jīn xiāngjiāo.","vi":"Đúng là ngọt thật! Phiền anh chọn giúp tôi một quả to hơn, thêm hai cân chuối nữa nhé."},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"一共五十八块五毛。","py":"Yígòng wǔshíbā kuài wǔ máo.","vi":"Tổng cộng là 58,5 đồng ạ."},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我买了这么多，便宜点儿吧。","py":"Wǒ mǎile zhème duō, piányi diǎnr ba.","vi":"Tôi mua nhiều như vậy. Anh có thể giảm giá cho tôi không?"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"您给我五十五吧，不能再便宜了。","py":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le.","vi":"Thôi tính cô 55 đồng nhé, không thể rẻ hơn được nữa đâu ạ."},{"section":"Bài khóa 4","context":"在家里，刘明在看电视。Lưu Minh đang xem ti vi ở trong nhà.","audio":"07-7.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这几天我们在新家坐着看电视的时候，又发现了新问题。房子大了，电视看起来就有点儿小。这个电视是我们结婚时买的，是时候换个新电视了。今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机。我看了好几个，都很满意，晚上让一雪来决定吧。","py":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiànle xīn wèntí. Fángzi dà le, diànshì kàn qǐlái jiù yǒudiǎnr xiǎo. Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn gè xīn diànshì le. Jīntiān wǒ yìzhí zài wǎngshang xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn, yǒude diànshì jiào tā yì shēng jiù néng kāijī. Wǒ kànle hǎo jǐ gè, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba.","vi":"Mấy ngày nay, khi ngồi xem ti vi trong căn nhà mới, chúng tôi đã phát hiện ra một vấn đề mới. Nhà rộng hơn nên chiếc ti vi trông có vẻ hơi nhỏ. Chiếc ti vi này chúng tôi mua khi mới kết hôn, cũng đã đến lúc phải mua cái mới rồi. Tôi đã tìm mua ti vi trên mạng cả ngày, không ngờ rằng ti vi bây giờ không những rẻ mà còn tiện dụng hơn rất nhiều, có loại ti vi bạn chỉ cần gọi một tiếng là mở máy. Tôi đã xem vài chiếc, đều rất hài lòng. Tôi sẽ để Nhất Tuyết quyết định vào tối nay."}],"dialogQuestions":[],"grammar":{"g1":{"han":"连动句（2）","py":"Liándòngjù (2)","title":"Câu liên động (2)","explain":"动态助词“着”用于连动句的第一个动词后面，表示进行第二个动作时的状态或方式。基本结构：动词1+着+（宾语1）+动词2+（宾语2）。\nTrợ từ động thái “着” được dùng sau động từ thứ nhất trong câu liên động, biểu thị trạng thái hoặc cách thức khi thực hiện hành động thứ hai. Cấu trúc cơ bản: động từ 1 + 着 + (tân ngữ 1) + động từ 2 + (tân ngữ 2).","examples":[{"zh":"咱们可以走着去。","py":"Zánmen kěyǐ zǒuzhe qù.","vi":"Chúng ta có thể đi bộ đến đó.","hl":"走着去"},{"zh":"弟弟吃着苹果写作业。","py":"Dìdi chīzhe píngguǒ xiě zuòyè.","vi":"Em trai vừa ăn táo vừa làm bài tập.","hl":"吃着苹果写作业"},{"zh":"他们坐着看电视。","py":"Tāmen zuòzhe kàn diànshì.","vi":"Họ ngồi xem ti vi.","hl":"坐着看电视"}],"struct":"Chủ ngữ + Động từ 1 + 着 (+ Tân ngữ 1) + Động từ 2 (+ Tân ngữ 2)","note":"Động từ 1 + 着 làm phương thức/trạng thái kèm theo của động từ 2."},"g2":{"han":"比较句（10）","py":"Bǐjiàojù (10)","title":"Câu so sánh (10)","explain":"“A不比B+形容词”的意思是A和B差不多。这个结构通常用于强调两者情况接近，或反驳别人说法的语境中。\nCấu trúc “A 不比 B + tính từ” có nghĩa là A và B gần giống nhau. Cấu trúc này thường dùng trong ngữ cảnh nhấn mạnh sự tương đồng giữa hai sự vật hoặc để phản bác ý kiến của người khác.","examples":[{"zh":"裙子不比短裤贵多少。","py":"Qúnzi bù bǐ duǎnkù guì duōshao.","vi":"Váy không đắt hơn quần soóc bao nhiêu.","hl":"不比……贵多少"},{"zh":"他的中文不比你好。","py":"Tā de Zhōngwén bù bǐ nǐ hǎo.","vi":"Tiếng Trung của anh ấy chẳng giỏi hơn bạn đâu.","hl":"不比……好"},{"zh":"他跑得不比我快多少。","py":"Tā pǎo de bù bǐ wǒ kuài duōshao.","vi":"Anh ấy chạy chẳng nhanh hơn tôi bao nhiêu.","hl":"不比……快多少"}],"struct":"A + 不比 + B + Tính từ (+ 多少/一点儿)","note":"Khác với “A没有B…” (A kém B); “A不比B…” nhấn mạnh A không vượt hơn B (hoặc ngang bằng/kém một chút)."},"g3":{"han":"程度补语（3）","py":"Chéngdù bǔyǔ (3)","title":"Bổ ngữ trình độ (3)","explain":"程度补语“极了”用在形容词或心理动词后面，表示人或事物的性质或者状态，或人的心理感受达到很高的程度。\nBổ ngữ trình độ “极了” đặt sau tính từ hoặc động từ chỉ tâm lý, biểu thị tính chất, trạng thái của người hoặc sự vật, hoặc cảm xúc của con người đạt đến mức độ rất cao.","examples":[{"zh":"这块冰西瓜甜极了。","py":"Zhè kuài bīng xīguā tián jíle.","vi":"Miếng dưa hấu ướp lạnh này ngọt cực kỳ.","hl":"甜极了"},{"zh":"今年夏天热极了。","py":"Jīnnián xiàtiān rè jíle.","vi":"Mùa hè năm nay nóng vô cùng.","hl":"热极了"},{"zh":"这本书我喜欢极了。","py":"Zhè běn shū wǒ xǐhuan jíle.","vi":"Quyển sách này tôi thích cực kỳ.","hl":"喜欢极了"}],"struct":"Tính từ / Động từ tâm lý + 极了","note":"Có thể dùng cho cả cảm xúc tích cực và tiêu cực để diễn đạt mức độ cao."},"g4":{"han":"递进复句“不但……，而且……”","py":"Dìjìn fùjù “búdàn..., érqiě...”","title":"Câu ghép tăng tiến “不但……，而且……”","explain":"递进复句“不但……，而且……”连接两个分句，表示递进关系。如果两个分句的主语相同，那么“不但”要放在第一个主语后面；如果两个分句的主语不同，那么“不但”要放在第一个主语的前面。\nCâu ghép tăng tiến “不但……，而且……” dùng để nối hai mệnh đề, biểu thị quan hệ tăng tiến. Nếu chủ ngữ của hai mệnh đề giống nhau thì “不但” đặt sau chủ ngữ thứ nhất; nếu chủ ngữ của hai mệnh đề khác nhau thì “不但” đặt trước chủ ngữ thứ nhất.","examples":[{"zh":"现在的电视不但便宜，而且用着非常方便。","py":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vi":"Ti vi bây giờ không những rẻ mà dùng còn rất tiện.","hl":"不但……，而且"},{"zh":"家月不但喜欢唱歌，而且唱得很好听。","py":"Jiāyuè búdàn xǐhuan chànggē, érqiě chàng de hěn hǎotīng.","vi":"Gia Nguyệt không chỉ thích hát mà hát còn rất hay.","hl":"不但……，而且"},{"zh":"不但家月会说汉语，而且天中也会说汉语。","py":"Búdàn Jiāyuè huì shuō Hànyǔ, érqiě Tiānzhōng yě huì shuō Hànyǔ.","vi":"Không chỉ Gia Nguyệt biết nói tiếng Hán mà Thiên Trung cũng biết nói tiếng Hán.","hl":"不但……，而且……也"}],"struct":"Chủ ngữ + 不但……，而且…… (cùng chủ ngữ) | 不但 + Chủ ngữ 1……，而且 + Chủ ngữ 2…… (khác chủ ngữ)","note":"Chú ý vị trí của “不但” phụ thuộc vào việc hai phân câu có cùng chủ ngữ hay không."}},"grammarQuiz":[{"id":"hsk3_b7_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你的手机很 (____)，买个新的吧。","opts":[{"t":"旧","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"声","ok":false}],"exp":"Đáp án D (旧): ‘Điện thoại của bạn cũ lắm rồi, mua cái mới đi.’"},{"id":"hsk3_b7_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她比我大两岁，但是比我还 (____) 一点儿。","opts":[{"t":"矮","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án C (矮): ‘Cô ấy lớn hơn tôi hai tuổi, nhưng lại thấp hơn tôi một chút.’"},{"id":"hsk3_b7_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这条短裤比那条 (____) 合适，买这条吧。","opts":[{"t":"更","ok":true},{"t":"试","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án B (更): ‘Chiếc quần soóc này phù hợp hơn chiếc kia, mua chiếc này đi.’"},{"id":"hsk3_b7_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们都听见了他在教室外面的笑 (____)。","opts":[{"t":"声","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false}],"exp":"Đáp án E (声): ‘Chúng tôi đều nghe thấy tiếng cười của cậu ấy bên ngoài lớp học.’"},{"id":"hsk3_b7_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"上网买东西很方便，你应该 (____) 一下。","opts":[{"t":"试","ok":true},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án A (试): ‘Mua đồ qua mạng rất tiện, bạn nên thử một lần xem.’"},{"id":"hsk3_b7_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 假期的时候你们去哪儿旅游？\nB: 我想去看海，不知道这个时间是不是 (____)。","opts":[{"t":"合适","ok":true},{"t":"一共","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án B (合适): ‘Tôi muốn đi ngắm biển, không biết thời điểm này có thích hợp không.’"},{"id":"hsk3_b7_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你们两个准备什么时候 (____)？\nB: 可能今年10月，到时候一定告诉你。","opts":[{"t":"结婚","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án D (结婚): ‘Hai người định khi nào kết hôn?’"},{"id":"hsk3_b7_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你帮我看看，我的手机为什么不能 (____)？\nB: 让小李帮你看，你新买的这个手机跟他的一样。","opts":[{"t":"开机","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false}],"exp":"Đáp án E (开机): ‘Bạn xem giúp tôi sao điện thoại của tôi không bật nguồn lên được?’"},{"id":"hsk3_b7_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 网上的房子太多了，我还没有 (____) 去看哪一个。\nB: 你可以先在网上看房，我教你。","opts":[{"t":"决定","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án C (决定): ‘Nhà trên mạng nhiều quá, tôi vẫn chưa quyết định đi xem căn nào.’"},{"id":"hsk3_b7_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 请问，这些水果多少钱？\nB: 苹果两斤，八块；香蕉四斤，十二块。(____) 二十块。","opts":[{"t":"一共","ok":true},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án A (一共): ‘Táo hai cân 8 đồng; chuối bốn cân 12 đồng. Tổng cộng 20 đồng.’"},{"id":"hsk3_b7_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"小雪的自行车是什么时候买的？","opts":[{"t":"C 她八岁的时候买的","ok":true},{"t":"A 昨天买的","ok":false},{"t":"B 今天买的","ok":false}],"exp":"Vương Nhất Tuyết nói: “这辆自行车是小雪八岁的时候买的...”"},{"id":"hsk3_b7_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"他们怎么去商场？","opts":[{"t":"A 走路","ok":true},{"t":"B 打车","ok":false},{"t":"C 骑自行车","ok":false}],"exp":"Lưu Minh nói: “商场不远，咱们可以走着去。”"},{"id":"hsk3_b7_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"课文里说，下面哪个更贵？","opts":[{"t":"B 裙子","ok":true},{"t":"A 短裤","ok":false},{"t":"C 运动鞋","ok":false}],"exp":"Váy 480 đồng đắt hơn quần soóc 400 đồng."},{"id":"hsk3_b7_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪后来是怎么决定的？","opts":[{"t":"C 看看再说","ok":true},{"t":"A 买裙子","ok":false},{"t":"B 买裤子","ok":false}],"exp":"Vương Nhất Tuyết nói: “我多看看再决定。”"},{"id":"hsk3_b7_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪在买什么？","opts":[{"t":"C 西瓜和香蕉","ok":true},{"t":"A 苹果","ok":false},{"t":"B 牛奶","ok":false}],"exp":"Vương Nhất Tuyết chọn mua một quả dưa hấu to và hai cân chuối."},{"id":"hsk3_b7_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"这些水果一共花了多少钱？","opts":[{"t":"A 五十五块","ok":true},{"t":"B 五十八块","ok":false},{"t":"C 五十八块五毛","ok":false}],"exp":"Sau khi mặc cả, người bán hàng đồng ý tính giá 55 đồng (“您给我五十五吧”)."},{"id":"hsk3_b7_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明发现了什么新问题？","opts":[{"t":"C 电视有点儿小","ok":true},{"t":"A 电视太旧了","ok":false},{"t":"B 房子太大了","ok":false}],"exp":"Bài khóa 4: “房子大了，电视看起来就有点儿小。”"},{"id":"hsk3_b7_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明选电视的时候发现了什么？","opts":[{"t":"A 新电视很方便","ok":true},{"t":"B 新电视不便宜","ok":false},{"t":"C 不能在网上选电视","ok":false}],"exp":"Bài khóa 4: “现在的电视不但便宜，而且用着非常方便...”"}],"chars":["辆","自","行","车","旧","矮","试","黄","色","短","裤","大","小","合","适","裙","子","更","决","定","西","瓜","新","鲜","甜","公","斤","冰","极","香","蕉","一","共","毛","结","婚","不","但","而","且","声","开","机","那","条","比","好","看"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 60): 比较句中的形容词前面可以用副词“还”或者“更”表示程度加深。Trong câu so sánh, phó từ “还” hoặc “更” có thể đứng trước tính từ để làm tăng thêm mức độ.","Tiểu Ngữ giúp sức (trang 60): “买二送一”是商店打折时常用的表达，意思是“你买两个东西，我送你一个东西”。当然有时候你也会看到“买一送一”“买三送一”这样的打折活动。“买二送一” là cách nói thường dùng khi cửa hàng có chương trình khuyến mãi, nghĩa là “Bạn mua hai món thì được tặng một món”.","Tiểu Ngữ giúp sức (trang 62): “不甜不要钱”常用在广告语中，这句话省略了主语，完整语句应该是：“如果这个西瓜不甜，我们就不要钱。”","Món quà của Tiểu Ngữ (trang 66, video 7-1): 中国人购物方式的转变 — Sự thay đổi về phương thức mua sắm của người Trung Quốc.","Câu hỏi thảo luận Bài khóa 1: (1) 他们为什么想给小雪买新自行车？ (2) 他们为什么想带小雪一起去？ (3) 王一雪还想买什么？","Câu hỏi thảo luận Bài khóa 2: (1) 刘明觉得短裤怎么样？ (2) 王一雪为什么不想买裙子？ (3) 裙子比短裤贵多少？","Câu hỏi thảo luận Bài khóa 3: (1) 西瓜多少钱一斤？ (2) 王一雪买了什么水果？ (3) 店员给王一雪便宜了多少钱？","Câu hỏi thảo luận Bài khóa 4: (1) 刘明家的电视是什么时候买的？ (2) 刘明想在哪儿买新电视？ (3) 刘明为什么觉得新电视用着很方便？"],"workbook":null},"8":{"pages":"67–75","titleZh":"今天我出院了","titlePy":"Jīntiān wǒ chūyuàn le","titleVi":"Hôm nay tôi xuất viện rồi","goals":["能听懂并描述看病经历及用药方法。Có thể nghe hiểu và miêu tả được kinh nghiệm đi khám bệnh và cách dùng thuốc.","能听懂并交流身体状况和健康习惯。Có thể nghe hiểu và trao đổi được về tình trạng sức khoẻ và thói quen lành mạnh.","掌握时量补语（2）的用法，能表达动作结束后延续到现在的时长。Nắm vững cách dùng của bổ ngữ thời lượng (2), để diễn đạt khoảng thời gian kéo dài từ khi hành động kết thúc đến hiện tại."],"words":[{"zh":"最近","py":"zuìjìn","vi":"gần đây","pos":"dt."},{"zh":"常","py":"cháng","vi":"thường, thường xuyên","pos":"phó."},{"zh":"体育馆","py":"tǐyùguǎn","vi":"nhà thi đấu","pos":"dt."},{"zh":"习惯","py":"xíguàn","vi":"thói quen, quen với","pos":"dt./đgt."},{"zh":"胖","py":"pàng","vi":"béo","pos":"tt."},{"zh":"健康","py":"jiànkāng","vi":"khoẻ mạnh","pos":"tt."},{"zh":"以后","py":"yǐhòu","vi":"sau, sau này, về sau","pos":"dt."},{"zh":"羽毛球","py":"yǔmáoqiú","vi":"cầu lông","pos":"dt."},{"zh":"耳朵","py":"ěrduo","vi":"tai","pos":"dt."},{"zh":"感冒","py":"gǎnmào","vi":"bị cảm, cảm","pos":"đgt./dt."},{"zh":"发烧","py":"fāshāo","vi":"sốt","pos":"đgt."},{"zh":"低","py":"dī","vi":"thấp","pos":"tt."},{"zh":"关心","py":"guānxīn","vi":"quan tâm","pos":"đgt."},{"zh":"注意","py":"zhùyì","vi":"chú ý","pos":"đgt."},{"zh":"突然","py":"tūrán","vi":"đột nhiên, đột ngột","pos":"tt."},{"zh":"住院","py":"zhùyuàn","vi":"nằm viện","pos":"đgt."},{"zh":"担心","py":"dānxīn","vi":"lo lắng","pos":"đgt."},{"zh":"腿","py":"tuǐ","vi":"chân","pos":"dt."},{"zh":"病人","py":"bìngrén","vi":"bệnh nhân","pos":"dt."},{"zh":"差不多","py":"chàbuduō","vi":"gần như, tương tự, xấp xỉ","pos":"phó./tt."},{"zh":"得","py":"děi","vi":"phải, cần","pos":"đtnn."},{"zh":"开心","py":"kāixīn","vi":"vui vẻ","pos":"tt."},{"zh":"出院","py":"chūyuàn","vi":"xuất viện","pos":"đgt."},{"zh":"开","py":"kāi","vi":"kê (đơn thuốc)","pos":"đgt."},{"zh":"种","py":"zhǒng","vi":"loại","pos":"lượng."},{"zh":"方法","py":"fāngfǎ","vi":"phương pháp","pos":"dt."},{"zh":"其他","py":"qítā","vi":"khác","pos":"đt."},{"zh":"心里","py":"xīnlǐ","vi":"trong lòng","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在学校的体育馆，李文遇到了陈天中。Lý Văn đã gặp Trần Thiên Trung ở nhà thi đấu của trường.","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"天中，最近常看见你来体育馆。","py":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","vi":"Thiên Trung, dạo này mình hay thấy bạn ở nhà thi đấu."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我每天下午都来跑一个小时步。","py":"Wǒ měitiān xiàwǔ dōu lái pǎo yí gè xiǎoshí bù.","vi":"Chiều nào mình cũng đến đây chạy bộ một tiếng."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"你的运动习惯真不错。","py":"Nǐ de yùndòng xíguàn zhēn búcuò.","vi":"Thói quen tập luyện của bạn rất tốt."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","py":"Yīnwèi wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng.","vi":"Bởi vì năm nay mình đã tăng hơn mười cân, mình thực sự không thể để béo thêm được nữa, như vậy không khoẻ đâu."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我下课以后常去打羽毛球，你也来玩吧。","py":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba.","vi":"Mình thường chơi cầu lông sau giờ học, bạn cũng đến chơi cùng chúng mình nhé!"},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我知道，但是你们的水平太高了，我打得不怎么样。","py":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng.","vi":"Mình biết, nhưng trình độ của các bạn cao quá, mình chơi không được tốt lắm."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"没关系，我可以教你。","py":"Méi guānxi, wǒ kěyǐ jiāo nǐ.","vi":"Không sao đâu mà. Mình có thể dạy bạn."},{"section":"Bài khóa 2","context":"在教室，安妮问候陈天中。Annie hỏi thăm Trần Thiên Trung ở trong lớp học.","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"你怎么了？看上去有点儿不舒服。","py":"Nǐ zěnme le? Kàn shàngqu yǒudiǎnr bù shūfu.","vi":"Bạn bị làm sao vậy? Trông bạn không được khoẻ lắm."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"昨天游完泳以后，耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua, sau khi bơi xong, mình cứ bị đau tai."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"是不是感冒了？发烧吗？","py":"Shì bu shì gǎnmào le? Fāshāo ma?","vi":"Liệu có phải bị cảm rồi không? Bạn có bị sốt không?"},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"好像发低烧了。","py":"Hǎoxiàng fā dīshāo le.","vi":"Hình như sốt nhẹ rồi."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"我送你去医院，让医生检查一下吧。","py":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba.","vi":"Mình đưa bạn đến bệnh viện để bác sĩ kiểm tra nhé."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我先回去睡一觉，可能休息休息就好了。","py":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le.","vi":"Mình sẽ về nhà chợp mắt một lát trước đã, chắc là nghỉ ngơi xong thì sẽ ổn thôi."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"好吧，如果下午还发烧，就一定要去看医生。","py":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng.","vi":"Được rồi, nếu chiều nay vẫn còn sốt thì nhất định phải đi khám bác sĩ đấy nhé."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"谢谢关心，我会注意的。","py":"Xièxie guānxīn, wǒ huì zhùyì de.","vi":"Cảm ơn sự quan tâm của bạn, mình sẽ chú ý hơn."},{"section":"Bài khóa 3","context":"在医院病房，安妮探望陈天中。Annie đến thăm Trần Thiên Trung ở phòng bệnh của bệnh viện.","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你怎么突然住院了？大家都很担心你。","py":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","vi":"Tại sao bạn đột nhiên lại phải nhập viện thế? Mọi người thực sự rất lo lắng cho bạn."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我的腿疼了几个星期了，医生说需要住院做检查。","py":"Wǒ de tuǐ téngle jǐ gè xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá.","vi":"Mình đã bị đau chân mấy tuần nay rồi, bác sĩ nói mình cần nhập viện để làm một số xét nghiệm."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你看起来一点儿也不像病人。","py":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén.","vi":"Trông bạn chẳng giống bệnh nhân chút nào cả."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","py":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vi":"Đúng vậy, mình hiếm khi bị ốm. Lần cuối mình đến bệnh viện là gần hai năm trước rồi."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你每天跑步，有时候还去游泳，是不是运动太多了？","py":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bu shì yùndòng tài duō le?","vi":"Ngày nào bạn cũng chạy bộ, có lúc còn đi bơi nữa, liệu có phải do bạn đã tập luyện quá sức không?"},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"医生也这么说，但是还得做完检查才能知道。","py":"Yīshēng yě zhème shuō, dànshì hái děi zuòwán jiǎnchá cái néng zhīdào.","vi":"Bác sĩ cũng nói như vậy, tuy nhiên chúng ta sẽ phải đợi kết quả kiểm tra thì mới biết chắc chắn được."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"别担心！听医生的话，好好休息，你的腿一定能好。","py":"Bié dānxīn! Tīng yīshēng de huà, hǎohāo xiūxi, nǐ de tuǐ yídìng néng hǎo.","vi":"Đừng lo lắng! Chỉ cần làm theo lời khuyên của bác sĩ, nghỉ ngơi thật nhiều, chân của bạn sẽ sớm hồi phục thôi."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"谢谢。有人来看我，我就开心多了。","py":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le.","vi":"Cảm ơn bạn. Có người tới thăm mình, mình đã vui lắm rồi."},{"section":"Bài khóa 4","context":"在家里，陈天中吃药、休息。Trần Thiên Trung uống thuốc và nghỉ ngơi ở nhà.","audio":"08-7.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"今天我出院了。出院前，医生给我开了几种药，而且告诉了我吃药的方法。有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。除了吃药，医生还说最重要的是多休息。我都记在心里了，回家以后一定会多注意。希望我的腿能快一点儿好。","py":"Jīntiān wǒ chūyuàn le. Chūyuàn qián, yīshēng gěi wǒ kāile jǐ zhǒng yào, érqiě gàosule wǒ chīyào de fāngfǎ. Yǒu yì zhǒng yào xūyào měitiān shuìqián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fànhòu chī. Chúle chīyào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi. Wǒ dōu jì zài xīnlǐ le, huíjiā yǐhòu yídìng huì duō zhùyì. Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo.","vi":"Hôm nay tôi xuất viện rồi. Trước khi ra viện, bác sĩ đã kê cho tôi vài loại thuốc, đồng thời hướng dẫn cách uống thuốc cho tôi. Có một loại thuốc mỗi tối cần uống một lần trước khi đi ngủ, những loại khác uống ba lần một ngày sau bữa ăn. Ngoài việc uống thuốc, bác sĩ còn nói với tôi rằng nghỉ ngơi đầy đủ là điều quan trọng nhất. Tôi đã ghi nhớ điều đó trong lòng rồi, sau khi về nhà nhất định sẽ chăm sóc bản thân thật tốt. Hy vọng chân tôi sẽ sớm khỏi."}],"dialogQuestions":[],"grammar":{"g1":{"han":"趋向补语的引申用法（1）","py":"Qūxiàng bǔyǔ de yǐnshēn yòngfǎ (1)","title":"Cách dùng mở rộng của bổ ngữ xu hướng (1)","explain":"趋向补语“下去”用在动词或形容词后面，表示已经开始的动作或者状态还要继续。\nBổ ngữ xu hướng “下去” đặt sau động từ hoặc tính từ, biểu thị hành động hoặc trạng thái đã bắt đầu và sẽ tiếp tục diễn ra.","examples":[{"zh":"我今年胖了十多斤，不能再胖下去了。","py":"Wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqù le.","vi":"Năm nay mình tăng hơn chục cân rồi, không thể tiếp tục béo thêm được nữa.","hl":"胖下去"},{"zh":"她读完了第一个问题，后面的你读下去。","py":"Tā dúwánle dì-yī gè wèntí, hòumian de nǐ dú xiàqù.","vi":"Cô ấy đọc xong câu hỏi thứ nhất rồi, phần sau bạn đọc tiếp đi.","hl":"读下去"},{"zh":"这几天太热了，如果再热下去就不能出门了。","py":"Zhè jǐ tiān tài rè le, rúguǒ zài rè xiàqù jiù bù néng chūmén le.","vi":"Mấy hôm nay nóng quá, nếu cứ nóng tiếp thế này thì không ra ngoài được mất.","hl":"热下去"}],"struct":"Động từ / Tính từ + 下去","note":"Mang nghĩa tiếp tục duy trì hoặc phát triển theo hướng hiện tại."},"g2":{"han":"离合词（2）","py":"Líhécí (2)","title":"Từ li hợp (2)","explain":"离合词一般不能直接加宾语。使用离合词的句子中如果有补语，一般都放在离合词的中间。\nTừ li hợp thường không thể trực tiếp mang tân ngữ. Trong câu sử dụng từ li hợp, nếu có bổ ngữ thì thường đặt bổ ngữ ở giữa hai phần của từ li hợp.","examples":[{"zh":"昨天游完泳以后，我的耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua sau khi bơi xong, tai mình cứ hơi đau.","hl":"游完泳"},{"zh":"今年夏天只下了两次雨。","py":"Jīnnián xiàtiān zhǐ xiàle liǎng cì yǔ.","vi":"Mùa hè năm nay trời chỉ mưa có hai lần.","hl":"下了两次雨"},{"zh":"小张下个月跟他女朋友结婚。","py":"Xiǎo Zhāng xià gè yuè gēn tā nǚpéngyou jiéhūn.","vi":"Tháng sau Tiểu Trương kết hôn với bạn gái cậu ấy.","hl":"跟……结婚"}],"struct":"Động tố + (了/过/完/bổ ngữ/số lượng từ...) + Danh tố (vd: 游完泳, 跑一个小时步, 下两次雨)","note":"Từ li hợp như 游泳, 跑步, 结婚, 见面 không mang tân ngữ trực tiếp mà tách ra để chèn bổ ngữ vào giữa."},"g3":{"han":"时量补语（2）","py":"Shíliàng bǔyǔ (2)","title":"Bổ ngữ thời lượng (2)","explain":"时量补语用在动词的后面，表示动作或者状态持续时间的长短。有些动词不能持续，这时动词后的时量补语表示动作从完成到说话时过了多长时间。\nBổ ngữ thời lượng đặt sau động từ, biểu thị khoảng thời gian mà hành động hoặc trạng thái duy trì. Có một số động từ không thể duy trì thì bổ ngữ thời lượng đứng sau động từ biểu thị khoảng thời gian từ lúc hành động hoàn thành đến thời điểm nói.","examples":[{"zh":"我上次来医院已经过去差不多两年了。","py":"Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vi":"Lần trước mình đến bệnh viện đã trôi qua gần hai năm rồi.","hl":"差不多两年了"},{"zh":"她回家两个月了。","py":"Tā huíjiā liǎng gè yuè le.","vi":"Cô ấy về nhà được hai tháng rồi.","hl":"两个月了"},{"zh":"开学已经三个多星期了。","py":"Kāixué yǐjīng sān gè duō xīngqī le.","vi":"Khai giảng đã hơn ba tuần rồi.","hl":"三个多星期了"}],"struct":"Động từ (không kéo dài) (+ Tân ngữ) + Khoảng thời gian + 了","note":"Dùng với các động từ kết thúc ngay (毕业, 结婚, 来, 到, 离开, 出院...) để tính thời gian từ lúc xảy ra tới hiện tại."},"g4":{"han":"固定格式“……以前/以后/前/后”","py":"Gùdìng géshì “...yǐqián/yǐhòu/qián/hòu”","title":"Cấu trúc cố định “……以前/以后/前/后”","explain":"“时间/事件+以前/前”表示某个时间或事件之前；“时间/事件+以后/后”表示某个时间或事件之后。\n“Thời gian/sự việc + 以前/前” biểu thị trước một thời điểm hoặc một sự kiện nào đó; “Thời gian/sự việc + 以后/后” biểu thị sau một thời điểm hoặc một sự kiện nào đó.","examples":[{"zh":"这种药需要每天睡前吃一次。","py":"Zhè zhǒng yào xūyào měitiān shuìqián chī yí cì.","vi":"Loại thuốc này mỗi ngày cần uống một lần trước khi đi ngủ.","hl":"睡前"},{"zh":"我们决定下班后一起去看个电影。","py":"Wǒmen juédìng xiàbān hòu yìqǐ qù kàn gè diànyǐng.","vi":"Chúng tôi quyết định sau khi tan làm cùng đi xem một bộ phim.","hl":"下班后"},{"zh":"考完试以后，咱们一起去旅游吧。","py":"Kǎowán shì yǐhòu, zánmen yìqǐ qù lǚyóu ba.","vi":"Sau khi thi xong, chúng ta cùng đi du lịch nhé.","hl":"考完试以后"}],"struct":"Thời điểm / Động từ / Cụm chủ vị + 以前/前 | 以后/后","note":"Trong tiếng Trung mốc thời gian/sự việc đứng trước 以前/以后, ngược trật tự với tiếng Việt (“trước/sau khi...”)."}},"grammarQuiz":[{"id":"hsk3_b8_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"李医生特别 (____) 病人。","opts":[{"t":"关心","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án D (关心): ‘Bác sĩ Lý đặc biệt quan tâm đến bệnh nhân.’"},{"id":"hsk3_b8_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"医生说你下个星期 (____) 回来检查一下。","opts":[{"t":"得","ok":true},{"t":"开","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án B (得): ‘Bác sĩ bảo tuần sau bạn cần phải quay lại kiểm tra một lần.’"},{"id":"hsk3_b8_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"您一直很健康，有什么好的锻炼 (____) 吗？","opts":[{"t":"方法","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false}],"exp":"Đáp án E (方法): ‘Ngài luôn khoẻ mạnh như vậy, có phương pháp rèn luyện nào hay không?’"},{"id":"hsk3_b8_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"如果你的病好了，医生就不会给你 (____) 药了。","opts":[{"t":"开","ok":true},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án A (开): ‘Nếu bệnh của bạn khỏi rồi thì bác sĩ sẽ không kê thuốc cho bạn nữa.’"},{"id":"hsk3_b8_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"感冒的时候能吃这 (____) 药吗？你再问一下医生。","opts":[{"t":"种","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án C (种): ‘Lúc bị cảm có uống được loại thuốc này không? Bạn hỏi lại bác sĩ thử xem.’"},{"id":"hsk3_b8_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你什么时候能出院？\nB: 可能两天 (____)，我还需要做几个检查。","opts":[{"t":"以后","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false}],"exp":"Đáp án E (以后): ‘Có lẽ hai ngày nữa, tôi còn cần làm vài xét nghiệm.’"},{"id":"hsk3_b8_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你是不是生病了？\nB: 是，我昨天晚上 (____) 头疼、发烧，吃完药好多了。","opts":[{"t":"突然","ok":true},{"t":"注意","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án B (突然): ‘Đúng vậy, tối qua tôi đột nhiên đau đầu, sốt, uống thuốc xong đỡ nhiều rồi.’"},{"id":"hsk3_b8_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你的腿可以走路，但是还不能运动。\nB: 我知道了，我会 (____) 的。","opts":[{"t":"注意","ok":true},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án A (注意): ‘Tôi biết rồi, tôi sẽ chú ý.’"},{"id":"hsk3_b8_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 刘医生，您下个星期来医院吗？\nB: 我下个星期一不来，(____) 时间都在。","opts":[{"t":"其他","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án D (其他): ‘Thứ Hai tuần sau tôi không tới, các thời gian khác đều có mặt.’"},{"id":"hsk3_b8_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你疼了多长时间了？\nB: 有时候疼，有时候不疼，(____) 一个月吧。","opts":[{"t":"差不多","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án C (差不多): ‘Lúc đau lúc không, xấp xỉ một tháng rồi.’"},{"id":"hsk3_b8_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"陈天中为什么每天运动？","opts":[{"t":"C 他不想再胖下去了","ok":true},{"t":"A 他喜欢跑步","ok":false},{"t":"B 他要学打羽毛球","ok":false}],"exp":"Trần Thiên Trung nói: “因为我今年胖了十多斤，不能再胖下去了...”"},{"id":"hsk3_b8_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文要教陈天中做什么？","opts":[{"t":"C 打羽毛球","ok":true},{"t":"A 跑步","ok":false},{"t":"B 打篮球","ok":false}],"exp":"Lý Văn nói anh hay chơi cầu lông và có thể dạy Trần Thiên Trung."},{"id":"hsk3_b8_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"陈天中怎么了？","opts":[{"t":"C 耳朵不舒服","ok":true},{"t":"A 头疼","ok":false},{"t":"B 发高烧","ok":false}],"exp":"Trần Thiên Trung nói: “昨天游完泳以后，耳朵一直有点儿疼。”"},{"id":"hsk3_b8_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"如果下午还发烧，应该怎么办？","opts":[{"t":"A 去看医生","ok":true},{"t":"B 吃点儿药","ok":false},{"t":"C 回家休息","ok":false}],"exp":"Annie dặn: “如果下午还发烧，就一定要去看医生。”"},{"id":"hsk3_b8_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"陈天中上次来医院是什么时候？","opts":[{"t":"C 两年前","ok":true},{"t":"A 几个星期前","ok":false},{"t":"B 一个月前","ok":false}],"exp":"Trần Thiên Trung nói: “我上次来医院已经过去差不多两年了。”"},{"id":"hsk3_b8_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"陈天中为什么觉得开心多了？","opts":[{"t":"A 有人来看他","ok":true},{"t":"B 他的腿不疼了","ok":false},{"t":"C 马上就能回家了","ok":false}],"exp":"Trần Thiên Trung nói: “有人来看我，我就开心多了。”"},{"id":"hsk3_b8_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"陈天中现在怎么样了？","opts":[{"t":"A 出院了","ok":true},{"t":"B 病都好了","ok":false},{"t":"C 还不能回家","ok":false}],"exp":"Bài khóa 4: “今天我出院了。”"},{"id":"hsk3_b8_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"医生说什么最重要？","opts":[{"t":"B 多休息","ok":true},{"t":"A 多走路","ok":false},{"t":"C 吃药的方法","ok":false}],"exp":"Bài khóa 4: “医生还说最重要的是多休息。”"}],"chars":["最","近","常","体","育","馆","习","惯","胖","健","康","以","后","羽","毛","球","耳","朵","感","冒","发","烧","低","关","心","注","意","突","然","住","院","担","腿","病","人","差","不","多","得","开","出","种","方","法","其","他","里","今","天","我","了"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 68): “不怎么样”是一个口语表达，意思是不太好、很一般，带有谦虚或评价不高的语气。Cụm từ “不怎么样” là cách diễn đạt dùng trong văn nói, có nghĩa “không được tốt lắm, không ổn lắm, bình thường thôi”, thường mang ngữ khí khiêm tốn hoặc đánh giá không cao.","Món quà của Tiểu Ngữ (trang 75, video 8-1): 在中国看病 — Đi khám bệnh ở Trung Quốc.","Câu hỏi thảo luận Bài khóa 1: (1) 陈天中每天下午去体育馆做什么？ (2) 李文下课以后经常做什么？ (3) 陈天中羽毛球打得怎么样？","Câu hỏi thảo luận Bài khóa 2: (1) 陈天中是什么时候开始不舒服的？ (2) 安妮想怎么帮助他？ (3) 陈天中想不想去医院？他想做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 陈天中为什么住院了？ (2) 安妮觉得陈天中为什么腿疼？ (3) 医生是怎么说陈天中的腿的？","Câu hỏi thảo luận Bài khóa 4: (1) 陈天中出院前，医生做了什么？ (2) 医生给陈天中开的药应该怎么吃？ (3) 陈天中回家以后应该注意什么？"],"workbook":null},"9":{"pages":"76–85","titleZh":"打不好没关系","titlePy":"Dǎ bu hǎo méi guānxi","titleVi":"Chơi không tốt cũng không sao","goals":["能听懂并介绍体育比赛的名称、运动员、影响等信息。Có thể nghe hiểu và giới thiệu được các thông tin như tên các cuộc thi thể thao, vận động viên và ảnh hưởng của nó...","能听懂并使用可能补语说明情况的可能性。Có thể nghe hiểu và sử dụng được bổ ngữ khả năng để diễn đạt khả năng xảy ra sự việc.","掌握“越A越B”格式的用法，能说明事物或情况的变化。Nắm vững cách dùng của cấu trúc “越 A 越 B” để diễn đạt sự thay đổi của sự vật hoặc tình huống."],"words":[{"zh":"校园","py":"xiàoyuán","vi":"khuôn viên trường","pos":"dt."},{"zh":"卡","py":"kǎ","vi":"thẻ","pos":"dt."},{"zh":"球场","py":"qiúchǎng","vi":"sân bóng","pos":"dt."},{"zh":"为了","py":"wèile","vi":"vì, để","pos":"giới."},{"zh":"运动会","py":"yùndònghuì","vi":"đại hội thể dục thể thao","pos":"dt."},{"zh":"男生","py":"nánshēng","vi":"nam sinh, nam giới","pos":"dt."},{"zh":"练","py":"liàn","vi":"luyện, tập","pos":"đgt."},{"zh":"参加","py":"cānjiā","vi":"tham gia","pos":"đgt."},{"zh":"网球","py":"wǎngqiú","vi":"quần vợt, tennis","pos":"dt."},{"zh":"比赛","py":"bǐsài","vi":"trận đấu, thi đấu","pos":"dt./đgt."},{"zh":"练习","py":"liànxí","vi":"luyện tập, bài tập","pos":"đgt./dt."},{"zh":"好多","py":"hǎoduō","vi":"khá nhiều","pos":"số."},{"zh":"几乎","py":"jīhū","vi":"hầu như","pos":"phó."},{"zh":"只是","py":"zhǐshì","vi":"chỉ là, nhưng","pos":"phó./liên."},{"zh":"啤酒","py":"píjiǔ","vi":"bia","pos":"dt."},{"zh":"回","py":"huí","vi":"vụ, lần","pos":"lượng."},{"zh":"紧张","py":"jǐnzhāng","vi":"căng thẳng, hồi hộp","pos":"tt."},{"zh":"主要","py":"zhǔyào","vi":"chủ yếu, chính","pos":"tt."},{"zh":"受到","py":"shòudào","vi":"bị, nhận, chịu, nhận được","pos":"đgt."},{"zh":"影响","py":"yǐngxiǎng","vi":"sự ảnh hưởng, ảnh hưởng","pos":"dt./đgt."},{"zh":"得分","py":"défēn","vi":"ghi điểm, ghi bàn, tỉ số","pos":"đgt./dt."},{"zh":"体育","py":"tǐyù","vi":"thể dục, thể thao","pos":"dt."},{"zh":"世界","py":"shìjiè","vi":"thế giới","pos":"dt."},{"zh":"运动员","py":"yùndòngyuán","vi":"vận động viên","pos":"dt."},{"zh":"得到","py":"dédào","vi":"đạt được, nhận được","pos":"đgt."},{"zh":"成绩","py":"chéngjì","vi":"thành tích, kết quả","pos":"dt."},{"zh":"奥运会","py":"Àoyùnhuì","vi":"Thế vận hội Olympic","pos":"dt. riêng"},{"zh":"刘长春","py":"Liú Chángchūn","vi":"Lưu Trường Xuân","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"在图书馆门口，李文向白家月跑过去。Ở trước cửa thư viện, Lý Văn chạy về phía Bạch Gia Nguyệt.","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，对不起，我昨天忘了还你校园卡了。","py":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuánkǎ le.","vi":"Gia Nguyệt, xin lỗi hôm qua anh đã quên trả thẻ sinh viên cho em."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"没关系。你怎么这么快就过来了？","py":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?","vi":"Không sao đâu. Sao anh đến đây nhanh thế?"},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我正在球场打球呢，接了你的电话就跑过来了。","py":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le.","vi":"Anh đang chơi bóng rổ trên sân, nhận điện thoại của em xong liền chạy tới đây ngay."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị cho Đại hội thể dục thể thao, các anh ngày nào cũng tập luyện."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"是啊！你打算参加运动会吗？","py":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","vi":"Đúng vậy! Em có định tham gia Đại hội thể dục thể thao không?"},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我想参加网球比赛，最近一直在练习。","py":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","vi":"Em định tham gia thi quần vợt, gần đây em đã luyện tập liên tục."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"好，到时候我去看你的比赛。","py":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài.","vi":"Tuyệt, tới lúc đó anh sẽ đến xem trận đấu của em nhé."},{"section":"Bài khóa 2","context":"在校园里，李文和白家月在聊天儿。Lý Văn và Bạch Gia Nguyệt đang trò chuyện trong công viên.","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，你跟我们一起打羽毛球吧？","py":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","vi":"Gia Nguyệt, em đến chơi cầu lông cùng bọn anh nhé?"},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我好多多年没打羽毛球了，几乎忘了怎么打了。","py":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le.","vi":"Đã nhiều năm rồi em không chơi cầu lông, gần như quên mất cách chơi rồi."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"不是比赛，打不好没关系。","py":"Bú shì bǐsài, dǎ bu hǎo méi guānxi.","vi":"Có phải thi đấu đâu, chơi không tốt cũng không sao mà."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这么多同学一起打，如果总是接不住球，就太不好意思了。","py":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bu zhù qiú, jiù tài bù hǎoyìsi le.","vi":"Nhiều người cùng chơi thế kia, lỡ em không đỡ được quả nào thì ngại lắm."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"你想得太多了！大家打球只是为了锻炼身体。","py":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ.","vi":"Em nghĩ nhiều quá rồi! Mọi người chơi cầu chỉ để rèn luyện sức khoẻ thôi mà."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我先自己练练吧，下周再跟你们一起打。","py":"Wǒ xiān zìjǐ liànlian ba, xià zhōu zài gēn nǐmen yìqǐ dǎ.","vi":"Em sẽ tự tập luyện trước đã, tuần sau em sẽ tham gia cùng các anh."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"我在教天中打羽毛球，你可以过来跟我们一起练。","py":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn.","vi":"Anh đang dạy Thiên Trung chơi cầu lông, em có thể đến tập cùng bọn anh nhé."},{"section":"Bài khóa 3","context":"在李文家，李文、白家月和陈天中一起看电视。Lý Văn xem phim cùng Bạch Gia Nguyệt và Trần Thiên Trung tại nhà của anh ấy.","audio":"09-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"足球比赛已经开始了，快过来看吧！","py":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!","vi":"Trận đấu bóng đá đã bắt đầu rồi, mau lại đây xem đi!"},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"李文","name":"Lý Văn","zh":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","py":"Nǐmen xiān kàn, bīngxiāng li yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià.","vi":"Các bạn cứ xem trước đi, trong tủ lạnh có bia và đồ uống, mình đi lấy nhé."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"今天怎么回事？总是踢不进去！","py":"Jīntiān zěnme huí shì? Zǒngshì tī bu jìnqù!","vi":"Hôm nay bị sao vậy nhỉ? Họ sút mãi mà chẳng vào!"},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","py":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le.","vi":"Mấy cầu thủ kỳ cựu bị ốm, các cầu thủ mới thì quá căng thẳng vì đây là lần đầu họ tham gia một trận đấu quan trọng."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"李文","name":"Lý Văn","zh":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","py":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le.","vi":"Đúng rồi, các cầu thủ chủ lực không thi đấu nên những người khác cũng bị ảnh hưởng theo."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"越看越着急。我不看了，你们告诉我得分吧。","py":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosu wǒ défēn ba.","vi":"Càng xem càng thấy sốt ruột. Mình không xem nữa đâu, lát các bạn báo mình tỉ số nhé."},{"section":"Bài khóa 4","context":"在家里，李文准备演讲稿。Lý Văn chuẩn bị bài phát biểu ở trong nhà.","audio":"09-7.mp3","speaker":"李文","name":"Lý Văn","zh":"我喜欢看体育比赛，最爱看的就是奥运会。奥运会是世界上影响最大的体育比赛。从1896年到2024年，每次奥运会都有非常多的运动员参加。第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。虽然他没有得到好成绩，但是他让世界认识了中国。","py":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì. Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài. Cóng yībājiǔliù nián dào èrlíng\u0027èrsì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā. Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yījiǔsān\u0027èr nián cānjiāle yībǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài. Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshile Zhōngguó.","vi":"Tôi thích xem các trận thi đấu thể thao, thích xem nhất là Thế vận hội Olympic. Thế vận hội Olympic là giải thi đấu thể thao có sức ảnh hưởng lớn nhất trên thế giới. Từ năm 1896 đến 2024, mỗi kỳ Thế vận hội Olympic đều có rất nhiều vận động viên tham gia. Vận động viên Trung Quốc đầu tiên tham gia Olympic là Lưu Trường Xuân, ông đã thi đấu ở các cự ly chạy 100m và 200m vào năm 1932. Mặc dù ông không đạt được kết quả cao, nhưng ông đã khiến cả thế giới biết đến Trung Quốc."}],"dialogQuestions":[],"grammar":{"g1":{"han":"目的复句“为了……，……”","py":"Mùdì fùjù “wèile..., ...”","title":"Câu ghép chỉ mục đích “为了……，……”","explain":"目的复句“为了……，……”中，“为了”后面的小句表示目的，另一个小句表示为了达到目的采取的行动。\nTrong câu ghép chỉ mục đích “为了……，……”, mệnh đề đứng sau “为了” biểu thị mục đích, mệnh đề còn lại biểu thị hành động được thực hiện để đạt mục đích đó.","examples":[{"zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị đại hội thể thao, mấy bạn nam ngày nào cũng tập bóng.","hl":"为了"},{"zh":"为了考上大学，她每天努力学习。","py":"Wèile kǎoshàng dàxué, tā měitiān nǔlì xuéxí.","vi":"Để thi đỗ đại học, ngày nào cô ấy cũng chăm chỉ học tập.","hl":"为了"},{"zh":"为了早点儿到家，我打算坐飞机回去。","py":"Wèile zǎo diǎnr dàojiā, wǒ dǎsuàn zuò fēijī huíqù.","vi":"Để về nhà sớm một chút, tôi dự định đi máy bay về.","hl":"为了"}],"struct":"为了 + Mục đích，+ Chủ ngữ + Hành động","note":"Vế chỉ mục đích đặt trước hoặc có thể đảo sau động từ chính."},"g2":{"han":"可能补语","py":"Kěnéng bǔyǔ","title":"Bổ ngữ khả năng","explain":"在动词和结果补语或趋向补语之间插入“得”或“不”构成可能补语，表示条件是否容许实现某种结果或趋向。肯定形式是“动词+得+补语”，否定形式是“动词+不+补语”，疑问形式是“动词+得+补语+动词+不+补语”或者“动词+得+补语+吗”。\nThêm “得” hoặc “不” vào giữa động từ và bổ ngữ kết quả hoặc bổ ngữ xu hướng để tạo thành bổ ngữ khả năng, biểu thị điều kiện có cho phép thực hiện một kết quả hoặc phương hướng nào đó hay không.","examples":[{"zh":"打不好没关系。","py":"Dǎ bu hǎo méi guānxi.","vi":"Chơi không tốt cũng không sao.","hl":"打不好"},{"zh":"这本书你看得懂看不懂？","py":"Zhè běn shū nǐ kàn de dǒng kàn bu dǒng?","vi":"Quyển sách này bạn có đọc hiểu không?","hl":"看得懂看不懂"},{"zh":"你只有一个星期的时间，学得会游泳吗？","py":"Nǐ zhǐ yǒu yí gè xīngqī de shíjiān, xué de huì yóuyǒng ma?","vi":"Bạn chỉ có thời gian một tuần, liệu có học được bơi không?","hl":"学得会……吗"}],"struct":"Khẳng định: Động từ + 得 + Bổ ngữ | Phủ định: Động từ + 不 + Bổ ngữ | Nghi vấn: Động từ + 得 + Bổ ngữ + Động từ + 不 + Bổ ngữ / ...吗？","note":"Trong bài khóa có các ví dụ tiêu biểu: 打不好, 接不住, 踢不进去."},"g3":{"han":"固定格式“越A越B”","py":"Gùdìng géshì “yuè A yuè B”","title":"Cấu trúc cố định “越 A 越 B”","explain":"固定格式“越A越B”的句子中，A和B可以都是动词性短语或形容词性短语，也可以是一个是动词性短语，另一个是形容词性短语，表示B随着A的变化而变化。\nTrong câu sử dụng cấu trúc cố định “越 A 越 B”, A và B có thể đều là cụm động từ hoặc cụm tính từ, cũng có thể A là cụm động từ, B là cụm tính từ, để biểu thị B thay đổi theo sự thay đổi của A.","examples":[{"zh":"今天的足球比赛我越看越着急。","py":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vi":"Trận bóng đá hôm nay tôi càng xem càng sốt ruột.","hl":"越看越着急"},{"zh":"妈妈越说，他越不高兴。","py":"Māma yuè shuō, tā yuè bù gāoxìng.","vi":"Mẹ càng nói, cậu ấy càng không vui.","hl":"越说……越不高兴"},{"zh":"我想认识中国朋友，越多越好。","py":"Wǒ xiǎng rènshi Zhōngguó péngyou, yuè duō yuè hǎo.","vi":"Tôi muốn làm quen với bạn Trung Quốc, càng nhiều càng tốt.","hl":"越多越好"}],"struct":"(Chủ ngữ +) 越 + A + (Chủ ngữ 2 +) 越 + B","note":"Chú ý nếu có hai chủ ngữ khác nhau thì mỗi chủ ngữ đứng trước “越” tương ứng."}},"grammarQuiz":[{"id":"hsk3_b9_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我的腿不舒服，所以没 (____) 这次网球比赛。","opts":[{"t":"参加","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án D (参加): ‘Chân tôi không khoẻ nên không tham gia giải đấu quần vợt lần này.’"},{"id":"hsk3_b9_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"学校的 (____) 上，每天都有很多同学在那儿做运动。","opts":[{"t":"球场","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án C (球场): ‘Trên sân bóng của trường ngày nào cũng có rất nhiều bạn học tập thể dục ở đó.’"},{"id":"hsk3_b9_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"运动员们为了得到好 (____)，每天要练十多个小时。","opts":[{"t":"成绩","ok":true},{"t":"世界","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án B (成绩): ‘Các vận động viên để giành được thành tích tốt, mỗi ngày phải tập hơn chục tiếng đồng hồ.’"},{"id":"hsk3_b9_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"受到天气的 (____)，今天的足球比赛要晚两个小时开始。","opts":[{"t":"影响","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false}],"exp":"Đáp án E (影响): ‘Bị ảnh hưởng bởi thời tiết, trận bóng đá hôm nay sẽ bắt đầu muộn hơn hai tiếng.’"},{"id":"hsk3_b9_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这位运动员觉得 (____) 上最重要的运动会就是奥运会。","opts":[{"t":"世界","ok":true},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án A (世界): ‘Vận động viên này cảm thấy đại hội thể thao quan trọng nhất trên thế giới chính là Thế vận hội Olympic.’"},{"id":"hsk3_b9_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 她游泳游得快吗？\nB: 她 (____) 每天都游，现在游得特别快。","opts":[{"t":"几乎","ok":true},{"t":"只是","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án B (几乎): ‘Cô ấy hầu như ngày nào cũng bơi, bây giờ bơi cực kỳ nhanh.’"},{"id":"hsk3_b9_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 他们以前每年都是第一名，为什么今年成绩这么不好？\nB: 我觉得 (____) 是因为好多老球员病了。","opts":[{"t":"主要","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án C (主要): ‘Tôi thấy chủ yếu là do rất nhiều cầu thủ kỳ cựu bị ốm.’"},{"id":"hsk3_b9_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你打得这么好，是羽毛球运动员吗？\nB: 打羽毛球 (____) 我的兴趣，我不是运动员。","opts":[{"t":"只是","ok":true},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án A (只是): ‘Chơi cầu lông chỉ là sở thích của tôi thôi, tôi không phải vận động viên.’"},{"id":"hsk3_b9_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: (____) 我爸爸的影响，我十几岁就开始打网球了。\nB: 现在你也开始影响我，我也喜欢上了打网球。","opts":[{"t":"受到","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false}],"exp":"Đáp án E (受到): ‘Chịu ảnh hưởng từ bố tôi, mười mấy tuổi tôi đã bắt đầu chơi quần vợt rồi.’"},{"id":"hsk3_b9_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我听说你参加了学校的运动会？\nB: 是的。虽然没有 (____) 很好的成绩，但是我认识了很多新朋友。","opts":[{"t":"得到","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án D (得到): ‘Tuy không giành được thành tích cao nhưng tôi đã quen được nhiều bạn mới.’"},{"id":"hsk3_b9_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文昨天忘了做什么了？","opts":[{"t":"B 还白家月校园卡","ok":true},{"t":"A 去学校打球","ok":false},{"t":"C 给白家月打电话","ok":false}],"exp":"Lý Văn nói: “家月，对不起，我昨天忘了还你校园卡了。”"},{"id":"hsk3_b9_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"运动会的时候，李文要做什么？","opts":[{"t":"C 看白家月的比赛","ok":true},{"t":"A 游泳","ok":false},{"t":"B 踢足球","ok":false}],"exp":"Lý Văn nói: “好，到时候我去看你的比赛。”"},{"id":"hsk3_b9_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月在说什么？","opts":[{"t":"C 打羽毛球","ok":true},{"t":"A 运动会","ok":false},{"t":"B 打网球","ok":false}],"exp":"Lý Văn rủ Bạch Gia Nguyệt chơi cầu lông: “家月，你跟我们一起打羽毛球吧？”"},{"id":"hsk3_b9_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"大家为什么一起打球？","opts":[{"t":"B 为了锻炼身体","ok":true},{"t":"A 为了比赛","ok":false},{"t":"C 为了参加运动会","ok":false}],"exp":"Lý Văn nói: “大家打球只是为了锻炼身体。”"},{"id":"hsk3_b9_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们在做什么？","opts":[{"t":"A 看足球比赛","ok":true},{"t":"B 准备踢足球","ok":false},{"t":"C 准备参加比赛","ok":false}],"exp":"Trần Thiên Trung gọi hai bạn lại xem trận đấu bóng đá trên TV."},{"id":"hsk3_b9_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月为什么着急？","opts":[{"t":"B 球一直踢不进去","ok":true},{"t":"A 老球员生病了","ok":false},{"t":"C 看不到比赛的得分","ok":false}],"exp":"Bạch Gia Nguyệt nói: “今天怎么回事？总是踢不进去！”"},{"id":"hsk3_b9_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文在说什么体育比赛？","opts":[{"t":"A 奥运会","ok":true},{"t":"B 短跑比赛","ok":false},{"t":"C 中国的体育比赛","ok":false}],"exp":"Bài khóa 4 giới thiệu về Thế vận hội Olympic (“最爱看的就是奥运会”)."},{"id":"hsk3_b9_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘长春参加了哪个比赛？","opts":[{"t":"A 100米短跑","ok":true},{"t":"B 200米游泳","ok":false},{"t":"C 5000米长跑","ok":false}],"exp":"Bài khóa 4: “他1932年参加了100米和200米短跑比赛。”"}],"chars":["校","园","卡","球","场","为","了","运","动","会","男","生","练","参","加","网","比","赛","习","好","多","几","乎","只","是","啤","酒","回","紧","张","主","要","受","到","影","响","得","分","体","育","世","界","员","成","绩","奥","刘","长","春","打","不","没","关","系"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 79): “接”的本义是托住、承受，这里“接球”的意思是回球或者把球打回去。Nghĩa gốc của “接” là đỡ, nhận, tiếp nhận; “接球” trong trường hợp này có nghĩa là trả bóng hoặc đánh bóng trả lại.","Tổng kết học tập Bài 7–9 (trang 84–85): 9 điểm ngữ pháp gồm 连动句(2), 比较句(10) A不比B+形容词, 程度补语(3) 极了, 递进复句 不但……，而且……, 趋向补语的引申用法(1) 下去, 离合词(2), 时量补语(2), ……以前/以后/前/后, 为了……，……, 可能补语 và 越A越B.","Câu hỏi thảo luận Bài khóa 1: (1) 李文为什么来得很快？ (2) 李文每天在做什么？ (3) 白家月最近在做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 李文叫白家月一起做什么？ (2) 白家月为什么不想去？ (3) 白家月想先做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 李文要去冰箱里拿什么？ (2) 今天的足球比赛踢得怎么样？ (3) 球员们受到什么影响了？","Câu hỏi thảo luận Bài khóa 4: (1) 奥运会是一个什么样的体育比赛？ (2) 1932年，中国运动员的比赛成绩怎么样？ (3) 刘长春的影响是什么？"],"workbook":null},"10":{"pages":"86–94","titleZh":"你明天再把书还给我","titlePy":"Nǐ míngtiān zài bǎ shū huán gěi wǒ","titleVi":"Ngày mai em trả lại sách cho cô nhé","goals":["能听懂并介绍学习和考试情况。Có thể nghe hiểu và giới thiệu được tình hình học tập và thi cử.","能听懂并谈论学习中遇到的问题，交流学习方法。Có thể nghe hiểu và thảo luận được những vấn đề gặp phải trong học tập, trao đổi phương pháp học.","掌握“把”字句（1）的用法，能描述事物位置的变化。Nắm vững cách dùng câu chữ “把” (1) để miêu tả được sự thay đổi vị trí của sự vật.","了解中国的教育体系和升学制度。Hiểu về hệ thống giáo dục và chế độ lên lớp của Trung Quốc."],"words":[{"zh":"数学","py":"shùxué","vi":"môn Toán, toán học","pos":"dt."},{"zh":"认真","py":"rènzhēn","vi":"chăm chỉ, nghiêm túc","pos":"tt."},{"zh":"笔记","py":"bǐjì","vi":"ghi chép","pos":"dt."},{"zh":"清楚","py":"qīngchu","vi":"rõ ràng, hiểu rõ","pos":"tt./đgt."},{"zh":"黑板","py":"hēibǎn","vi":"bảng đen","pos":"dt."},{"zh":"把","py":"bǎ","vi":"dùng để đưa tân ngữ của động từ lên trước động từ","pos":"giới."},{"zh":"作业","py":"zuòyè","vi":"bài tập về nhà","pos":"dt."},{"zh":"遍","py":"biàn","vi":"lượt","pos":"lượng."},{"zh":"提高","py":"tígāo","vi":"nâng cao","pos":"đgt."},{"zh":"历史","py":"lìshǐ","vi":"môn Lịch sử, lịch sử","pos":"dt."},{"zh":"难","py":"nán","vi":"khó, khó khăn","pos":"tt."},{"zh":"要求","py":"yāoqiú","vi":"yêu cầu, đòi hỏi","pos":"dt./đgt."},{"zh":"差","py":"chà","vi":"kém, thiếu","pos":"tt./đgt."},{"zh":"复习","py":"fùxí","vi":"ôn tập","pos":"đgt."},{"zh":"外语","py":"wàiyǔ","vi":"ngoại ngữ","pos":"dt."},{"zh":"当然","py":"dāngrán","vi":"đương nhiên, dĩ nhiên","pos":"phó."},{"zh":"遇到","py":"yùdào","vi":"gặp, gặp phải","pos":"đgt."},{"zh":"办公室","py":"bàngōngshì","vi":"văn phòng, phòng làm việc","pos":"dt."},{"zh":"页","py":"yè","vi":"trang (giấy, sách)","pos":"lượng."},{"zh":"对话","py":"duìhuà","vi":"đối thoại, hội thoại, trò chuyện","pos":"đgt."},{"zh":"明白","py":"míngbai","vi":"hiểu, rõ ràng","pos":"đgt./tt."},{"zh":"讲","py":"jiǎng","vi":"giảng, giải thích","pos":"đgt."},{"zh":"句","py":"jù","vi":"câu (nói, văn)","pos":"lượng."},{"zh":"句子","py":"jùzi","vi":"câu","pos":"dt."},{"zh":"年级","py":"niánjí","vi":"khối lớp","pos":"dt."},{"zh":"后年","py":"hòunián","vi":"năm kia, năm sau","pos":"dt."},{"zh":"一般","py":"yìbān","vi":"bình thường, phổ biến","pos":"tt."},{"zh":"努力","py":"nǔlì","vi":"chăm chỉ, nỗ lực","pos":"tt./đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在教室里，刘小雪跟同学聊学习方法。Lưu Tiểu Tuyết trò chuyện với bạn học về phương pháp học tập ở trong lớp học.","audio":"10-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"你的数学越来越好，能不能介绍一下学习方法？","py":"Nǐ de shùxué yuèláiyuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?","vi":"Môn Toán của bạn càng ngày càng tốt lên. Bạn có thể chia sẻ phương pháp học tập của mình không?"},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"没有什么特别的方法，认真听课，认真记笔记。","py":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","vi":"Không có phương pháp gì đặc biệt cả, chú ý nghe giảng trong lớp và chăm chỉ ghi chép thôi."},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"我看过你的笔记，记得非常清楚。","py":"Wǒ kànguo nǐ de bǐjì, jì de fēicháng qīngchu.","vi":"Mình đã thấy vở ghi của bạn rồi, ghi chép rất rõ ràng."},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","py":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vi":"Những vấn đề mà cô giáo viết trên bảng đều rất quan trọng, vì vậy mình sẽ ghi hết vào vở."},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"你说得对。我没有记笔记的习惯。","py":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn.","vi":"Bạn nói rất đúng. Mình không có thói quen ghi chép bài."},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"笔记挺重要的，我每天写作业以前，都要看一遍。","py":"Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn.","vi":"Vở ghi thực sự rất quan trọng. Hàng ngày, mình luôn xem lại chúng một lần trước khi làm bài tập về nhà."},{"section":"Bài khóa 1","context":"","audio":"10-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"这个方法真好！我以后也试试，希望能提高成绩。","py":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì.","vi":"Phương pháp này thật tuyệt vời! Sau này mình cũng thử xem sao, hy vọng sẽ có thể nâng cao thành tích học tập."},{"section":"Bài khóa 2","context":"在教室里，刘小雪跟同学聊昨天的考试。Lưu Tiểu Tuyết trò chuyện với bạn học về bài kiểm tra hôm qua ở trong lớp học.","audio":"10-3.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"小雪，昨天的考试，你考得怎么样？","py":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?","vi":"Tiểu Tuyết, bài kiểm tra hôm qua bạn làm bài thế nào?"},{"section":"Bài khóa 2","context":"","audio":"10-3.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"我觉得历史有点儿难，你呢？","py":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?","vi":"Mình thấy lịch sử hơi khó một chút, còn bạn thì sao?"},{"section":"Bài khóa 2","context":"","audio":"10-3.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","py":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuòcuòle hǎo jǐ gè tí, kǎo de tǐng chà de.","vi":"Mình đã không đọc kĩ yêu cầu làm bài của bài kiểm tra môn Toán, nên làm sai mấy câu liền, bài làm không tốt lắm."},{"section":"Bài khóa 2","context":"","audio":"10-3.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"明天还有考试呢，别想那么多了，先复习外语吧。","py":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba.","vi":"Ngày mai còn có bài kiểm tra khác nữa, đừng nghĩ về nó quá nhiều, giờ hãy tập trung vào việc ôn tập ngoại ngữ nhé."},{"section":"Bài khóa 2","context":"","audio":"10-3.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"外语作业里有几个问题，我可以问问你吗？","py":"Wàiyǔ zuòyè li yǒu jǐ gè wèntí, wǒ kěyǐ wènwen nǐ ma?","vi":"Mình có vài câu hỏi về bài tập ngoại ngữ, mình có thể hỏi bạn được không?"},{"section":"Bài khóa 2","context":"","audio":"10-3.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"当然可以。在学习上，遇到什么问题都可以问我。","py":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vi":"Tất nhiên rồi! Cứ hỏi mình bất cứ điều gì liên quan đến việc học nhé."},{"section":"Bài khóa 2","context":"……（稍后 / Một lát sau）","audio":"10-3.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","py":"Bù hǎoyìsi, zhè jǐ gè tí wǒ yě bú huì. Zánmen háishi yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba.","vi":"Xin lỗi, mình cũng không biết cách giải những câu này. Chúng ta hãy cùng đến văn phòng để hỏi cô Lý đi."},{"section":"Bài khóa 3","context":"在李老师办公室，刘小雪跟同学问问题。Lưu Tiểu Tuyết cùng bạn học hỏi bài ở trong phòng làm việc của cô Lý.","audio":"10-5.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"李老师，书上有几个问题，我们想问问您。","py":"Lǐ lǎoshī, shū shang yǒu jǐ gè wèntí, wǒmen xiǎng wènwen nín.","vi":"Thưa cô Lý, chúng em muốn hỏi cô một vài câu hỏi trong sách giáo khoa ạ."},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"李老师","name":"Cô Lý","zh":"好，坐下说吧，哪个题不会？","py":"Hǎo, zuòxia shuō ba, nǎge tí bú huì?","vi":"Được, các em ngồi đi, các em không biết giải câu nào?"},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"书上第五页的这个对话我看不懂，小雪也不明白。","py":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai.","vi":"Em không hiểu đoạn hội thoại ở trang 5 trong sách, Tiểu Tuyết cũng không hiểu chỗ đó ạ."},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"李老师","name":"Cô Lý","zh":"我课上讲过这几句话，再给你们讲一遍。","py":"Wǒ kè shang jiǎngguo zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn.","vi":"Cô đã giảng những câu này trên lớp rồi, để cô giảng lại một lần nữa nhé."},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"旁白","name":"Dẫn chuyện","zh":"（李老师给学生讲题。）","py":"(Lǐ lǎoshī gěi xuésheng jiǎng tí.)","vi":"(Cô Lý giải thích câu hỏi cho học sinh.)"},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"我终于懂了。这些句子一点儿也不难。","py":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán.","vi":"Cuối cùng em cũng hiểu rồi. Những câu này chẳng khó chút nào cả!"},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"我也明白了，谢谢您，李老师。","py":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī.","vi":"Em cũng hiểu rồi ạ. Em cảm ơn cô Lý."},{"section":"Bài khóa 3","context":"","audio":"10-5.mp3","speaker":"李老师","name":"Cô Lý","zh":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","py":"Wǒ zhè běn shū shang hái yǒu jǐ gè liànxí, nǐmen huíjiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ.","vi":"Trong quyển sách này của cô còn có vài bài tập nữa, các em hãy thử làm ở nhà nhé, ngày mai trả lại sách cho cô."},{"section":"Bài khóa 4","context":"在家里，刘小雪在写邮件。Lưu Tiểu Tuyết đang viết email ở trong nhà.","audio":"10-7.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"家月姐姐：你最近怎么样？忙不忙？我现在上初中二年级，学习越来越忙，后年就要考高中了。中国的学校一般是小学六年，初中三年，高中三年。妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。家月姐姐，你知道吗？在你的影响下，我也开始喜欢拍照了。下次你再来北京，我给你看看我照的照片。","py":"Jiāyuè jiějie: Nǐ zuìjìn zěnmeyàng? Máng bu máng? Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuèláiyuè máng, hòunián jiù yào kǎo gāozhōng le. Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián. Māma shuō xiǎng kǎoshàng hǎo dàxué, jiù děi shàng yí gè hǎo gāozhōng; wèile kǎoshàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí gè búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì. Jiāyuè jiějie, nǐ zhīdào ma? Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le. Xià cì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn.","vi":"Chị Gia Nguyệt thân mến! Dạo này chị thế nào rồi ạ? Chị có bận lắm không? Bây giờ em đang học lớp 8, việc học của em ngày càng bận hơn, năm sau nữa em sẽ thi cấp 3 rồi ạ. Trường học ở Trung Quốc thường gồm sáu năm tiểu học (cấp 1), ba năm trung học cơ sở (cấp 2) và ba năm trung học phổ thông (cấp 3). Mẹ em nói rằng để thi đỗ một trường đại học tốt, thì cần phải thi đỗ một trường cấp 3 tốt. Để thi đỗ một trường cấp 3 tốt, cần có thành tích học tập tốt ở cấp 2. Vì vậy hiện giờ em đang rất cố gắng học hành. Chị có biết không chị Gia Nguyệt? Do ảnh hưởng của chị, em đã bắt đầu yêu thích nhiếp ảnh rồi đấy. Lần tới chị đến Bắc Kinh, em sẽ cho chị xem vài bức ảnh em đã chụp."}],"dialogQuestions":[],"grammar":{"g1":{"han":"“把”字句（1）","py":"“Bǎ” zìjù (1)","title":"Câu chữ “把” (1)","explain":"“把”字句表示对确定的人或事物做出相应的动作，使其发生位置上的改变，否定副词“不/没”和能愿动词应该放在“把”字的前面。基本结构：主语+（不/没/能愿动词）+把+宾语+动词+在/到+地点。\nCâu chữ “把” miêu tả việc thực hiện một hành động tác động tới người hoặc sự vật đã xác định, khiến vị trí của nó thay đổi. Phó từ phủ định “不/没” và động từ năng nguyện phải đặt trước “把”. Cấu trúc cơ bản: Chủ ngữ + (不/没/động từ năng nguyện) + 把 + tân ngữ + động từ + 在/到 + địa điểm.","examples":[{"zh":"我会把这些题都记在本子上。","py":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","vi":"Mình sẽ ghi hết những bài tập này vào vở.","hl":"把这些题都记在本子上"},{"zh":"老师把作业本放到桌子上了。","py":"Lǎoshī bǎ zuòyèběn fàng dào zhuōzi shang le.","vi":"Cô giáo đã đặt vở bài tập lên trên bàn rồi.","hl":"把作业本放到桌子上"},{"zh":"你不能把名字写在这里。","py":"Nǐ bù néng bǎ míngzi xiě zài zhèlǐ.","vi":"Bạn không thể viết tên ở đây.","hl":"不能把名字写在这里"}],"struct":"Chủ ngữ + (不/没/Động từ năng nguyện) + 把 + Tân ngữ + Động từ + 在/到 + Địa điểm","note":"Tân ngữ sau “把” phải là đối tượng xác định (như 这..., 那..., hoặc đã được nhắc đến). Không đặt “不/没” sau “把”."},"g2":{"han":"固定格式“在……上/中/下”","py":"Gùdìng géshì “zài... shàng/zhōng/xià”","title":"Cấu trúc cố định “在……上/中/下”","explain":"介词“在”和方位词“上”“中”“下”组成的“在……上/中/下”格式可表示范围、时间、条件等。\n1. “在+名词/名词性短语+上”表示范围、方面。\n2. “在……中”表示动作发生或状态存在的环境、时间等。\n3. “在+有定语的双音节动词+下”表示条件。\nGiới từ “在” kết hợp với các từ phương vị “上”, “中”, “下” tạo thành cấu trúc “在……上/中/下”, biểu thị phạm vi, thời gian, điều kiện...","examples":[{"zh":"在学习上，遇到什么问题都可以问我。","py":"Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","vi":"Trong học tập, gặp vấn đề gì đều có thể hỏi mình.","hl":"在学习上"},{"zh":"在比赛中，他得分最高。","py":"Zài bǐsài zhōng, tā défēn zuì gāo.","vi":"Trong trận đấu, cậu ấy ghi điểm cao nhất.","hl":"在比赛中"},{"zh":"在老师的帮助下，我的成绩提高很快。","py":"Zài lǎoshī de bāngzhù xià, wǒ de chéngjì tígāo hěn kuài.","vi":"Dưới sự giúp đỡ của thầy cô, thành tích của tôi nâng cao rất nhanh.","hl":"在老师的帮助下"}],"struct":"在 + Danh từ/Cụm danh từ + 上 (phạm vi) | 在……中 (bối cảnh/thời gian) | 在 + Định ngữ + Động từ hai âm tiết + 下 (điều kiện)","note":"Các cụm rất hay gặp: 在学习上, 在工作上, 在生活上, 在……的影响下, 在……的帮助下."},"g3":{"han":"“把”字句（2）","py":"“Bǎ” zìjù (2)","title":"Câu chữ “把” (2)","explain":"“把”字句表示通过动作使确定的事物发生关系上的转移。基本结构：主语+把+宾语₁+动词+给+宾语₂。\nCâu chữ “把” biểu thị thông qua hành động khiến sự vật đã được xác định xảy ra sự chuyển đổi về quan hệ. Cấu trúc cơ bản: Chủ ngữ + 把 + tân ngữ₁ + động từ + 给 + tân ngữ₂.","examples":[{"zh":"你明天再把书还给我。","py":"Nǐ míngtiān zài bǎ shū huán gěi wǒ.","vi":"Ngày mai em trả lại sách cho cô nhé.","hl":"把书还给我"},{"zh":"我把礼物送给她了。","py":"Wǒ bǎ lǐwù sòng gěi tā le.","vi":"Tôi đã tặng món quà cho cô ấy rồi.","hl":"把礼物送给她"},{"zh":"请你把这本书带给老师。","py":"Qǐng nǐ bǎ zhè běn shū dài gěi lǎoshī.","vi":"Phiền bạn mang quyển sách này cho thầy/cô giáo.","hl":"把这本书带给老师"}],"struct":"Chủ ngữ + 把 + Tân ngữ₁ + Động từ (还/送/带/发/借...) + 给 + Tân ngữ₂","note":"Thường dùng với các động từ mang nghĩa chuyển giao như 还, 送, 带, 借, 发."}},"grammarQuiz":[{"id":"hsk3_b10_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我再说一 (____)，请大家认真听。","opts":[{"t":"遍","ok":true},{"t":"难","ok":false},{"t":"差","ok":false},{"t":"讲","ok":false},{"t":"清楚","ok":false}],"exp":"Đáp án A (遍): ‘Tôi nói lại một lượt nữa, mọi người chú ý lắng nghe.’"},{"id":"hsk3_b10_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你的汉字写得太 (____) 了，要多练习才能写得好。","opts":[{"t":"差","ok":true},{"t":"遍","ok":false},{"t":"难","ok":false},{"t":"讲","ok":false},{"t":"清楚","ok":false}],"exp":"Đáp án C (差): ‘Chữ Hán của bạn viết kém quá rồi, cần luyện tập nhiều mới viết đẹp được.’"},{"id":"hsk3_b10_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"老师上课说什么我没听 (____)，你再告诉我一下吧。","opts":[{"t":"清楚","ok":true},{"t":"遍","ok":false},{"t":"难","ok":false},{"t":"差","ok":false},{"t":"讲","ok":false}],"exp":"Đáp án E (清楚): ‘Cô giáo giảng gì trên lớp tôi nghe chưa rõ, bạn nói lại cho tôi một chút nhé.’"},{"id":"hsk3_b10_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"李老师，可以给我 (____) 一下我做错的这几个题吗？","opts":[{"t":"讲","ok":true},{"t":"遍","ok":false},{"t":"难","ok":false},{"t":"差","ok":false},{"t":"清楚","ok":false}],"exp":"Đáp án D (讲): ‘Cô Lý ơi, cô có thể giảng giúp em mấy câu em làm sai này không ạ?’"},{"id":"hsk3_b10_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"今天这几个题有点儿 (____)，好多同学都没听明白。","opts":[{"t":"难","ok":true},{"t":"遍","ok":false},{"t":"差","ok":false},{"t":"讲","ok":false},{"t":"清楚","ok":false}],"exp":"Đáp án B (难): ‘Mấy bài tập hôm nay hơi khó một chút, rất nhiều bạn đều nghe chưa hiểu.’"},{"id":"hsk3_b10_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 今天的作业你写完了吗？\nB: 没有，老师 (____) 写500个字，我只写了一半。","opts":[{"t":"要求","ok":true},{"t":"认真","ok":false},{"t":"复习","ok":false},{"t":"提高","ok":false},{"t":"当然","ok":false}],"exp":"Đáp án D (要求): ‘Chưa, cô giáo yêu cầu viết 500 chữ, mình mới viết được một nửa.’"},{"id":"hsk3_b10_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你有什么 (____) 外语水平的好方法吗？\nB: 没什么特别的，多听多说就行了。","opts":[{"t":"提高","ok":true},{"t":"认真","ok":false},{"t":"复习","ok":false},{"t":"要求","ok":false},{"t":"当然","ok":false}],"exp":"Đáp án C (提高): ‘Bạn có phương pháp nào hay để nâng cao trình độ ngoại ngữ không?’"},{"id":"hsk3_b10_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你还在想考试的事吗？一次考试没考好没关系。\nB: 好，我不想了。我以后会好好 (____) 的。","opts":[{"t":"复习","ok":true},{"t":"认真","ok":false},{"t":"提高","ok":false},{"t":"要求","ok":false},{"t":"当然","ok":false}],"exp":"Đáp án B (复习): ‘Được rồi, mình không nghĩ nữa đâu. Sau này mình sẽ ôn tập thật tốt.’"},{"id":"hsk3_b10_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我高中的时候没遇到好老师，所以成绩越来越差。\nB: 老师 (____) 重要，但是自己的努力也很重要。","opts":[{"t":"当然","ok":true},{"t":"认真","ok":false},{"t":"复习","ok":false},{"t":"提高","ok":false},{"t":"要求","ok":false}],"exp":"Đáp án E (当然): ‘Thầy cô đương nhiên quan trọng, nhưng nỗ lực của bản thân cũng rất quan trọng.’"},{"id":"hsk3_b10_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这次你数学考试考了100分，你是怎么做到的？\nB: 做完以后，我又 (____) 地检查了一遍。","opts":[{"t":"认真","ok":true},{"t":"复习","ok":false},{"t":"提高","ok":false},{"t":"要求","ok":false},{"t":"当然","ok":false}],"exp":"Đáp án A (认真): ‘Làm xong rồi, mình lại kiểm tra cẩn thận lại một lượt nữa.’"},{"id":"hsk3_b10_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"同学让刘小雪做什么？","opts":[{"t":"C 介绍学习方法","ok":true},{"t":"A 看笔记","ok":false},{"t":"B 认真记笔记","ok":false}],"exp":"Bạn học hỏi Lưu Tiểu Tuyết: “能不能介绍一下学习方法？”"},{"id":"hsk3_b10_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"同学听了刘小雪的学习方法后，有什么打算？","opts":[{"t":"B 认真记笔记","ok":true},{"t":"A 认真听课","ok":false},{"t":"C 每天写作业","ok":false}],"exp":"Bạn học nói mình chưa có thói quen ghi chép bài và muốn thử áp dụng phương pháp ghi chép của Tiểu Tuyết."},{"id":"hsk3_b10_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"刘小雪觉得昨天的考试怎么样？","opts":[{"t":"B 历史有点儿难","ok":true},{"t":"A 外语没考好","ok":false},{"t":"C 数学考得还可以","ok":false}],"exp":"Lưu Tiểu Tuyết nói: “我觉得历史有点儿难，你呢？”"},{"id":"hsk3_b10_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"关于那几个外语题，可以知道什么？","opts":[{"t":"B 要去问老师","ok":true},{"t":"A 小雪会做","ok":false},{"t":"C 小雪的同学会做","ok":false}],"exp":"Lưu Tiểu Tuyết cũng không biết làm nên rủ bạn cùng đến văn phòng hỏi cô Lý."},{"id":"hsk3_b10_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们的问题在书上第几页？","opts":[{"t":"A 第五页","ok":true},{"t":"B 第七页","ok":false},{"t":"C 第十五页","ok":false}],"exp":"Bạn học nói: “书上第五页的这个对话我看不懂，小雪也不明白。”"},{"id":"hsk3_b10_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"李老师讲完，刘小雪和同学听懂了吗？","opts":[{"t":"B 都明白了","ok":true},{"t":"A 没听懂","ok":false},{"t":"C 还有几个不明白","ok":false}],"exp":"Sau khi cô Lý giảng lại, bạn học nói “我终于懂了” và Tiểu Tuyết nói “我也明白了”."},{"id":"hsk3_b10_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘小雪现在读几年级？","opts":[{"t":"B 初中二年级","ok":true},{"t":"A 小学六年级","ok":false},{"t":"C 高中一年级","ok":false}],"exp":"Bài khóa 4: “我现在上初中二年级，学习越来越忙...”"},{"id":"hsk3_b10_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"在白家月的影响下，刘小雪喜欢做什么了？","opts":[{"t":"A 拍照","ok":true},{"t":"B 努力学习","ok":false},{"t":"C 给朋友看照片","ok":false}],"exp":"Bài khóa 4: “在你的影响下，我也开始喜欢拍照了。”"}],"chars":["数","学","认","真","笔","记","清","楚","黑","板","把","作","业","遍","提","高","历","史","难","要","求","差","复","习","外","语","当","然","遇","到","办","公","室","页","对","话","明","白","讲","句","子","年","级","后","一","般","努","力","你","天","再","书","还","给","我"],"rhyme":null,"notes":["Món quà của Tiểu Ngữ (trang 94, video 10-1): 中国的义务教育 — Giáo dục bắt buộc ở Trung Quốc.","Câu hỏi thảo luận Bài khóa 1: (1) 刘小雪的数学为什么越来越好？ (2) 刘小雪觉得老师写在黑板上的题重要吗？ (3) 刘小雪的同学打算怎么做？为什么？","Câu hỏi thảo luận Bài khóa 2: (1) 明天还有什么考试？ (2) 同学要问刘小雪什么问题？ (3) 刘小雪和同学为什么一起去办公室？","Câu hỏi thảo luận Bài khóa 3: (1) 刘小雪的同学听明白了吗？ (2) 李老师上课的时候讲过这几句话吗？ (3) 李老师为什么给他们一本书？","Câu hỏi thảo luận Bài khóa 4: Giới thiệu hệ thống giáo dục 6-3-3 ở Trung Quốc (小学六年，初中三年，高中三年) và đối chiếu với hệ thống lên lớp tại quốc gia bạn sinh sống."],"workbook":null},"11":{"pages":"95–103","titleZh":"看来我没办法解决这个问题","titlePy":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí","titleVi":"Xem ra em không thể giải quyết vấn đề này","goals":["能听懂并交流工作情况。Có thể nghe hiểu và trao đổi được tình hình công việc.","能听懂并谈论职业选择和工作感受。Có thể nghe hiểu và thảo luận được về lựa chọn nghề nghiệp và cảm nhận trong công việc.","掌握“看来”的用法，能对事件进行推测和分析。Nắm vững cách sử dụng của “看来” để đưa ra suy đoán và phân tích sự việc."],"words":[{"zh":"会议","py":"huìyì","vi":"cuộc họp, hội nghị","pos":"dt."},{"zh":"经理","py":"jīnglǐ","vi":"giám đốc","pos":"dt."},{"zh":"开会","py":"kāihuì","vi":"họp","pos":"đgt."},{"zh":"后天","py":"hòutiān","vi":"ngày kia","pos":"dt."},{"zh":"地点","py":"dìdiǎn","vi":"địa điểm","pos":"dt."},{"zh":"室","py":"shì","vi":"phòng","pos":"dt."},{"zh":"发","py":"fā","vi":"gửi","pos":"đgt."},{"zh":"笔记本（电脑）","py":"bǐjìběn (diànnǎo)","vi":"máy tính xách tay","pos":"dt."},{"zh":"或者","py":"huòzhě","vi":"hoặc, hoặc là","pos":"liên."},{"zh":"声音","py":"shēngyīn","vi":"âm thanh","pos":"dt."},{"zh":"看来","py":"kànlái","vi":"xem ra, dường như, có vẻ như","pos":"đgt."},{"zh":"办法","py":"bànfǎ","vi":"biện pháp, cách","pos":"dt."},{"zh":"解决","py":"jiějué","vi":"giải quyết","pos":"đgt."},{"zh":"只能","py":"zhǐ néng","vi":"chỉ có thể","pos":""},{"zh":"别人","py":"biérén","vi":"người khác","pos":"đt."},{"zh":"请假","py":"qǐngjià","vi":"xin nghỉ, xin nghỉ phép","pos":"đgt."},{"zh":"同事","py":"tóngshì","vi":"đồng nghiệp","pos":"dt."},{"zh":"休假","py":"xiūjià","vi":"nghỉ phép","pos":"đgt."},{"zh":"怕","py":"pà","vi":"sợ","pos":"đgt."},{"zh":"邮箱","py":"yóuxiāng","vi":"hộp thư điện tử","pos":"dt."},{"zh":"老张","py":"Lǎo Zhāng","vi":"ông Trương, anh Trương","pos":"dt. riêng"},{"zh":"愿意","py":"yuànyì","vi":"sẵn lòng, bằng lòng","pos":"đtnn."},{"zh":"城市","py":"chéngshì","vi":"thành phố","pos":"dt."},{"zh":"离开","py":"líkāi","vi":"rời khỏi","pos":"đgt."},{"zh":"机会","py":"jīhuì","vi":"cơ hội","pos":"dt."},{"zh":"生活","py":"shēnghuó","vi":"cuộc sống, sinh sống","pos":"dt./đgt."},{"zh":"为","py":"wèi","vi":"vì","pos":"giới."},{"zh":"或","py":"huò","vi":"hoặc, hoặc là","pos":"liên."}],"dialog":[{"section":"Bài khóa 1","context":"在办公室里，王一雪跟杨同乐在讨论工作。Vương Nhất Tuyết và Dương Đồng Lạc đang thảo luận công việc trong văn phòng.","audio":"11-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"会议下午几点开始？","py":"Huìyì xiàwǔ jǐ diǎn kāishǐ?","vi":"Chiều nay mấy giờ bắt đầu họp nhỉ?"},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"今天下午经理不在，不开会了。","py":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le.","vi":"Chiều nay giám đốc không ở công ty nên không họp nữa."},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那什么时候开会？","py":"Nà shénme shíhou kāihuì?","vi":"Vậy khi nào sẽ họp đấy?"},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","py":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì-yī huìyìshì. Wǒ zhèngyào gěi dàjiā fā yóujiàn.","vi":"10 giờ sáng ngày kia, địa điểm họp đã được rời sang Phòng họp số 1. Em đang gửi email cho mọi người đây."},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","py":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vi":"Trong cuộc họp, chúng ta dùng máy tính của phòng họp hay máy tính cá nhân vậy?"},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"会议室的电脑或者自己的电脑都可以。","py":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vi":"Máy tính của phòng họp hay máy tính cá nhân đều được."},{"section":"Bài khóa 1","context":"","audio":"11-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","py":"Nà dào shíhou zánmen zǎo diǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiēhǎo ba.","vi":"Vậy tới khi đó, chúng ta hãy tới sớm một chút, em kết nối máy tính hộ chị được không?"},{"section":"Bài khóa 2","context":"在会议室，王一雪跟杨同乐在做会前准备。Vương Nhất Tuyết và Dương Đồng Lạc đang chuẩn bị cho cuộc họp ở trong phòng họp.","audio":"11-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"电脑接好了吗？","py":"Diànnǎo jiēhǎo le ma?","vi":"Máy tính đã kết nối xong chưa?"},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"已经接好了，您开机看看有没有问题。","py":"Yǐjīng jiēhǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","vi":"Kết nối xong rồi. Chị thử bật lên xem có vấn đề gì không."},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"现在什么都看不见。","py":"Xiànzài shénme dōu kàn bu jiàn.","vi":"Hiện tại chị không nhìn thấy gì cả."},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我检查一下哪里出问题了……您再试一下。","py":"Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le... nín zài shì yíxià.","vi":"Để em kiểm tra xem chỗ nào có vấn đề... Chị hãy thử lại một lần nữa xem."},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"看见了，但是听不见声音。","py":"Kànjiàn le, dànshì tīng bu jiàn shēngyīn.","vi":"Nhìn thấy rồi, nhưng không nghe thấy tiếng."},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"现在呢？","py":"Xiànzài ne?","vi":"Bây giờ thì sao?"},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"听得见声音，但是声音有点儿小，听不清楚。","py":"Tīng de jiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīng bu qīngchu.","vi":"Chị có thể nghe thấy rồi, nhưng âm thanh quá nhỏ, không nghe rõ."},{"section":"Bài khóa 2","context":"","audio":"11-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāng bangmáng le.","vi":"Xem ra em không thể giải quyết được vấn đề này rồi, chỉ có thể nhờ người khác giúp thôi."},{"section":"Bài khóa 3","context":"在办公室里，王一雪跟杨同乐在聊天儿。Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong văn phòng.","audio":"11-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"同乐，你看见老张了吗？","py":"Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","vi":"Đồng Lạc, em có nhìn thấy anh Trương đâu không?"},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"老张没来。他说家里有点儿事，所以请假了。","py":"Lǎo Zhāng méi lái. Tā shuō jiāli yǒudiǎnr shì, suǒyǐ qǐngjià le.","vi":"Anh Trương chưa đến. Anh ấy nói gia đình có một số việc cần phải giải quyết nên đã xin nghỉ phép rồi."},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好几个同事都休假了，开会前这么多工作我怕干不完。","py":"Hǎo jǐ gè tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán.","vi":"Mấy đồng nghiệp đều nghỉ phép hết rồi, e rằng chị sẽ không thể hoàn thành tất cả công việc này trước cuộc họp mất."},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","py":"Shí\u0027èr diǎn duō le, zánmen xiān qù chīfàn ba. Chīwán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","vi":"Đã hơn 12 giờ rồi, chúng ta đi ăn trưa trước đi. Sau khi ăn xong, em sẽ cùng chị hoàn thành những công việc này."},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","py":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng li.","vi":"Em đi ăn trước đi, chị muốn làm thêm một lát nữa. Chị cần gửi những thứ này đến địa chỉ email của công ty trước cuộc họp ngày mai."},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您没看到邮件吗？经理还没回来呢，下周才能开会。","py":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xià zhōu cái néng kāihuì.","vi":"Chị chưa xem email à? Giám đốc vẫn chưa về nên cuộc họp đã được dời sang tuần sau rồi."},{"section":"Bài khóa 3","context":"","audio":"11-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那不着急了。走，吃饭去。","py":"Nà bù zháojí le. Zǒu, chīfàn qù.","vi":"Thế thì không phải vội nữa rồi. Nào, đi ăn thôi."},{"section":"Bài khóa 4","context":"在家里，王一雪在写日记。Vương Nhất Tuyết đang ngồi viết nhật ký ở trong nhà.","audio":"11-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"前几天，上海的同事来北京了。一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","py":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le. Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi. Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎoxuě hé Xiǎomíng yě hái xiǎo, wǒ qù biéde chéngshì gōngzuò jiù yào líkāi tāmen. Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ láishuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vi":"Vài ngày trước, một số đồng nghiệp ở Thượng Hải đã đến Bắc Kinh. Lúc dùng bữa cùng nhau, họ nói với tôi rằng, gần đây rất nhiều đồng nghiệp đã chuyển đến Thượng Hải làm việc, hỏi tôi liệu có muốn đi Thượng Hải không. Tôi nghĩ như thế này: Hiện giờ, chồng và con tôi đều đang ở Bắc Kinh, công việc của Lưu Minh cực kì bận rộn, Tiểu Tuyết và Tiểu Minh vẫn còn nhỏ, nếu tôi đến thành phố khác làm việc thì buộc phải rời xa các con. Mặc dù Thượng Hải có thể mang lại cơ hội nghề nghiệp tốt hơn, nhưng đối với tôi mà nói, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay việc học mà phải rời xa gia đình."}],"dialogQuestions":[],"grammar":{"g1":{"han":"“还是”和“或者”","py":"“Háishi” hé “huòzhě”","title":"“还是” và “或者”","explain":"“还是”一般用在疑问句中，提出两个或多个选项，希望对方从中做出选择。“或者”主要用在陈述句中，不能用在疑问句中。\n“还是” thường được dùng trong câu hỏi, đưa ra hai hoặc nhiều phương án để người nghe lựa chọn. “或者” thường được dùng trong câu trần thuật, không dùng trong câu hỏi.","examples":[{"zh":"我们用会议室的电脑还是自己的笔记本电脑？","py":"Wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","vi":"Chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?","hl":"还是"},{"zh":"会议室的电脑或者自己的电脑都可以。","py":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","vi":"Máy tính của phòng họp hoặc máy tính của mình đều được.","hl":"或者"},{"zh":"你可以坐地铁或者打车去学校。","py":"Nǐ kěyǐ zuò dìtiě huòzhě dǎchē qù xuéxiào.","vi":"Bạn có thể đi tàu điện ngầm hoặc bắt taxi đến trường.","hl":"或者"}],"struct":"A + 还是 + B？ (câu hỏi lựa chọn) | A + 或者 + B (câu trần thuật)","note":"Trong câu trần thuật có mệnh đề nghi vấn phụ (như 我不知道他去还是不去), vẫn dùng 还是."},"g2":{"han":"固定短语“看来”","py":"Gùdìng duǎnyǔ “kànlái”","title":"Cụm từ cố định “看来”","explain":"固定短语“看来”后面加上一个结论，表示说话人通过观察、思考后，对当前情况的分析或推测。\nSau cụm từ cố định “看来” có thể thêm một kết luận, thể hiện sự phân tích hoặc suy đoán của người nói về tình huống hiện tại thông qua việc quan sát hoặc suy nghĩ.","examples":[{"zh":"看来我没办法解决这个问题。","py":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí.","vi":"Xem ra em không thể giải quyết vấn đề này.","hl":"看来"},{"zh":"这么晚了，看来他今天不会来了。","py":"Zhème wǎn le, kànlái tā jīntiān bú huì lái le.","vi":"Muộn thế này rồi, xem ra hôm nay anh ấy sẽ không tới đâu.","hl":"看来"},{"zh":"电梯坏了，看来咱们只能走下去了。","py":"Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqù le.","vi":"Thang máy hỏng rồi, xem ra chúng ta chỉ có thể đi bộ xuống thôi.","hl":"看来"}],"struct":"Nhận định/Tình huống + ，+ 看来 + Kết luận","note":"Đặt trước chủ ngữ của câu kết luận để dẫn ra phán đoán dựa trên thực tế."},"g3":{"han":"“把”字句（3）","py":"“Bǎ” zìjù (3)","title":"Câu chữ “把” (3)","explain":"“把”字句表示动作对确定的人或事物产生某种结果。基本结构：“主语+把+宾语+动词+结果补语”。\nCâu chữ “把” biểu thị hành động tác động lên một đối tượng xác định và tạo ra kết quả cụ thể. Cấu trúc cơ bản: Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ kết quả.","examples":[{"zh":"我跟您一起把这些工作做完。","py":"Wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","vi":"Em cùng chị làm xong hết những công việc này.","hl":"把这些工作做完"},{"zh":"妈妈把衣服洗干净了。","py":"Māma bǎ yīfu xǐ gānjìng le.","vi":"Mẹ đã giặt sạch quần áo rồi.","hl":"把衣服洗干净"},{"zh":"他还没把笔记本电脑接好呢。","py":"Tā hái méi bǎ bǐjìběn diànnǎo jiēhǎo ne.","vi":"Cậu ấy vẫn chưa kết nối xong máy tính xách tay đâu.","hl":"把笔记本电脑接好"}],"struct":"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ kết quả (+ 了)","note":"Các bổ ngữ kết quả thường gặp: 完, 好, 干净, 清楚, 对, 错."},"g4":{"han":"固定格式“对……来说”","py":"Gùdìng géshì “duì... láishuō”","title":"Cấu trúc cố định “对……来说”","explain":"固定格式“对……来说”指明观点、感受或情况所属的对象。\nCấu trúc cố định “对……来说” dùng để chỉ rõ đối tượng liên quan trực tiếp đến một quan điểm, cảm nhận hoặc tình huống cụ thể.","examples":[{"zh":"对我来说，生活也很重要，我不愿意为工作或学习离开家人。","py":"Duì wǒ láishuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","vi":"Đối với tôi mà nói, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa gia đình.","hl":"对我来说"},{"zh":"对她来说，学习汉语很有意思。","py":"Duì tā láishuō, xuéxí Hànyǔ hěn yǒuyìsi.","vi":"Đối với cô ấy mà nói, học tiếng Hán rất thú vị.","hl":"对她来说"},{"zh":"对孩子来说，玩也是一种学习。","py":"Duì háizi láishuō, wán yě shì yì zhǒng xuéxí.","vi":"Đối với trẻ em mà nói, chơi cũng là một cách học.","hl":"对孩子来说"}],"struct":"对 + Người / Đối tượng + 来说，+ Quan điểm / Đánh giá","note":"Thường đứng ở đầu câu làm trạng ngữ nêu lập trường hoặc góc nhìn của đối tượng được nhắc tới."}},"grammarQuiz":[{"id":"hsk3_b11_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这是同事们 (____) 你准备的礼物。","opts":[{"t":"为","ok":true},{"t":"发","ok":false},{"t":"怕","ok":false},{"t":"或者","ok":false},{"t":"机会","ok":false}],"exp":"Đáp án C (为): ‘Đây là món quà mà các đồng nghiệp chuẩn bị cho bạn.’"},{"id":"hsk3_b11_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"下班以前我得把这封邮件 (____) 给大家。","opts":[{"t":"发","ok":true},{"t":"怕","ok":false},{"t":"为","ok":false},{"t":"或者","ok":false},{"t":"机会","ok":false}],"exp":"Đáp án A (发): ‘Trước khi tan làm tôi phải gửi bức email này cho mọi người.’"},{"id":"hsk3_b11_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"今天好几个人请假了，我们明天 (____) 后天再开会吧。","opts":[{"t":"或者","ok":true},{"t":"发","ok":false},{"t":"怕","ok":false},{"t":"为","ok":false},{"t":"机会","ok":false}],"exp":"Đáp án D (或者): ‘Hôm nay mấy người xin nghỉ rồi, ngày mai hoặc ngày kia chúng ta họp lại nhé.’"},{"id":"hsk3_b11_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"每次开会我都不说话，因为我总是 (____) 说错话。","opts":[{"t":"怕","ok":true},{"t":"发","ok":false},{"t":"为","ok":false},{"t":"或者","ok":false},{"t":"机会","ok":false}],"exp":"Đáp án B (怕): ‘Mỗi lần họp tôi đều không phát biểu, vì tôi luôn sợ nói nhầm.’"},{"id":"hsk3_b11_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这次去上海开会是个好 (____)，你可以多认识一些新同事。","opts":[{"t":"机会","ok":true},{"t":"发","ok":false},{"t":"怕","ok":false},{"t":"为","ok":false},{"t":"或者","ok":false}],"exp":"Đáp án E (机会): ‘Lần này đi Thượng Hải họp là một cơ hội tốt, bạn có thể làm quen thêm vài đồng nghiệp mới.’"},{"id":"hsk3_b11_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你为什么要 (____) 现在的公司？\nB: 对我来说，多跟家人在一起比工作更重要。","opts":[{"t":"离开","ok":true},{"t":"办法","ok":false},{"t":"解决","ok":false},{"t":"只能","ok":false},{"t":"愿意","ok":false}],"exp":"Đáp án D (离开): ‘Tại sao bạn lại muốn rời khỏi công ty hiện tại?’"},{"id":"hsk3_b11_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 工作中遇到不能 (____) 的问题，你怎么办？\nB: 请同事帮忙，多跟他们学习。","opts":[{"t":"解决","ok":true},{"t":"办法","ok":false},{"t":"只能","ok":false},{"t":"离开","ok":false},{"t":"愿意","ok":false}],"exp":"Đáp án B (解决): ‘Trong công việc gặp phải vấn đề không giải quyết được thì bạn làm thế nào?’"},{"id":"hsk3_b11_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 每次遇到问题，他都会帮我们一起想 (____)。\nB: 所以大家都喜欢和他做朋友。","opts":[{"t":"办法","ok":true},{"t":"解决","ok":false},{"t":"只能","ok":false},{"t":"离开","ok":false},{"t":"愿意","ok":false}],"exp":"Đáp án A (办法): ‘Mỗi lần gặp vấn đề, anh ấy đều giúp chúng tôi cùng nghĩ cách.’"},{"id":"hsk3_b11_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你 (____) 去别的城市工作吗？\nB: 经理已经问过我了，我还没想好呢。","opts":[{"t":"愿意","ok":true},{"t":"办法","ok":false},{"t":"解决","ok":false},{"t":"只能","ok":false},{"t":"离开","ok":false}],"exp":"Đáp án E (愿意): ‘Bạn có bằng lòng sang thành phố khác làm việc không?’"},{"id":"hsk3_b11_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这么多工作今天做不完了，(____) 明天再说。\nB: 行，明天我和你一起把这些做完。","opts":[{"t":"只能","ok":true},{"t":"办法","ok":false},{"t":"解决","ok":false},{"t":"离开","ok":false},{"t":"愿意","ok":false}],"exp":"Đáp án C (只能): ‘Nhiều việc thế này hôm nay không làm xong được, đành để mai tính tiếp.’"},{"id":"hsk3_b11_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一雪和杨同乐在说什么？","opts":[{"t":"A 下午的会议","ok":true},{"t":"B 经理在哪儿","ok":false},{"t":"C 怎么发邮件","ok":false}],"exp":"Vương Nhất Tuyết hỏi: “会议下午几点开始？” — hai người thảo luận về cuộc họp chiều nay."},{"id":"hsk3_b11_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"杨同乐为什么要给大家发邮件？","opts":[{"t":"C 告诉大家会议时间和地点","ok":true},{"t":"A 找大家来开会","ok":false},{"t":"B 告诉大家带笔记本电脑","ok":false}],"exp":"Dương Đồng Lạc nói: “后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。”"},{"id":"hsk3_b11_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"杨同乐在帮助王一雪做什么？","opts":[{"t":"C 解决电脑的问题","ok":true},{"t":"A 发邮件","ok":false},{"t":"B 看邮件","ok":false}],"exp":"Hai người kiểm tra màn hình và âm thanh máy tính trước cuộc họp."},{"id":"hsk3_b11_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"杨同乐解决这个问题了吗？","opts":[{"t":"C 没有，要找别人来帮忙","ok":true},{"t":"A 解决了","ok":false},{"t":"B 没有，要上网查一下","ok":false}],"exp":"Dương Đồng Lạc nói: “看来我没办法解决这个问题，只能找别人来帮帮忙了。”"},{"id":"hsk3_b11_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪这几天为什么特别忙？","opts":[{"t":"C 好几个同事没来","ok":true},{"t":"A 经理不在","ok":false},{"t":"B 每天开会","ok":false}],"exp":"Vương Nhất Tuyết nói: “好几个同事都休假了，开会前这么多工作我怕干不完。”"},{"id":"hsk3_b11_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"杨同乐吃完饭要做什么？","opts":[{"t":"C 帮王一雪把工作做完","ok":true},{"t":"A 帮同事请假","ok":false},{"t":"B 给公司发邮件","ok":false}],"exp":"Dương Đồng Lạc nói: “吃完饭，我跟您一起把这些工作做完。”"},{"id":"hsk3_b11_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪最近在想什么问题？","opts":[{"t":"C 愿意不愿意去别的城市工作","ok":true},{"t":"A 上海的机会多不多","ok":false},{"t":"B 喜欢不喜欢现在的工作","ok":false}],"exp":"Đồng nghiệp hỏi chị có muốn chuyển sang Thượng Hải làm việc hay không."},{"id":"hsk3_b11_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪为什么不想去上海工作？","opts":[{"t":"B 她不愿意离开家人","ok":true},{"t":"A 上海没有什么机会","ok":false},{"t":"C 她不认识上海的同事","ok":false}],"exp":"Vương Nhất Tuyết viết: “我不愿意为工作或学习离开家人。”"}],"chars":["会","议","经","理","开","后","天","地","点","室","发","笔","记","本","电","脑","或","者","声","音","看","来","办","法","解","决","只","能","别","人","请","假","同","事","休","怕","邮","箱","老","张","愿","意","城","市","离","机","生","活","为","我","没","这","个","问","题"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 96): 这里“接”的意思是“连接”。Từ “接” ở đây có nghĩa là “kết nối”.","Câu hỏi thảo luận Bài khóa 1: (1) 今天为什么不开会了？ (2) 会议换到了什么时间和地点？ (3) 王一雪需要杨同乐帮忙做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 开机以后，电脑有什么问题？ (2) 杨同乐检查以后，电脑怎么样了？ (3) 听见声音以后，又出现了什么问题？","Câu hỏi thảo luận Bài khóa 3: (1) 老张今天为什么没来上班？ (2) 王一雪为什么没时间吃饭？ (3) 明天公司开会吗？","Câu hỏi thảo luận Bài khóa 4: (1) 上海的同事告诉王一雪什么了？ (2) 王一雪觉得去上海工作有什么好处？ (3) 对王一雪来说，工作和生活哪个更重要？"],"workbook":null},"12":{"pages":"104–114","titleZh":"这个季节天气变化很快","titlePy":"Zhège jìjié tiānqì biànhuà hěn kuài","titleVi":"Thời tiết thay đổi rất nhanh vào mùa này","goals":["能听懂并谈论天气变化。Có thể nghe hiểu và nói được về sự thay đổi của thời tiết.","能听懂并介绍某地的气候情况及自己对季节的喜好。Có thể nghe hiểu và giới thiệu được khí hậu của một nơi, đồng thời thể hiện sở thích cá nhân về các mùa.","掌握“就”的用法，能强调数量少或例外情况。Nắm vững cách sử dụng “就” để nhấn mạnh số lượng ít hoặc trường hợp ngoại lệ.","了解北京的四季特点。Hiểu về đặc điểm của bốn mùa ở Bắc Kinh."],"words":[{"zh":"街","py":"jiē","vi":"phố, đường phố","pos":"dt."},{"zh":"开花","py":"kāihuā","vi":"nở hoa, trổ hoa","pos":"đgt."},{"zh":"公园","py":"gōngyuán","vi":"công viên","pos":"dt."},{"zh":"船","py":"chuán","vi":"thuyền","pos":"dt."},{"zh":"工作日","py":"gōngzuòrì","vi":"ngày làm việc","pos":"dt."},{"zh":"地方","py":"dìfang","vi":"địa điểm, nơi","pos":"dt."},{"zh":"刚才","py":"gāngcái","vi":"vừa rồi, lúc nãy","pos":"dt."},{"zh":"刮","py":"guā","vi":"(gió) thổi","pos":"đgt."},{"zh":"风","py":"fēng","vi":"gió","pos":"dt."},{"zh":"新闻","py":"xīnwén","vi":"tin tức","pos":"dt."},{"zh":"伞","py":"sǎn","vi":"ô, dù","pos":"dt."},{"zh":"借","py":"jiè","vi":"mượn","pos":"đgt."},{"zh":"把","py":"bǎ","vi":"cái, chiếc (vật có tay cầm)","pos":"lượng."},{"zh":"雨衣","py":"yǔyī","vi":"áo mưa","pos":"dt."},{"zh":"变","py":"biàn","vi":"thay đổi","pos":"đgt."},{"zh":"季节","py":"jìjié","vi":"mùa","pos":"dt."},{"zh":"变化","py":"biànhuà","vi":"thay đổi, sự thay đổi","pos":"đgt./dt."},{"zh":"冬天","py":"dōngtiān","vi":"mùa đông","pos":"dt."},{"zh":"常常","py":"chángcháng","vi":"thường xuyên","pos":"phó."},{"zh":"关注","py":"guānzhù","vi":"quan tâm","pos":"đgt."},{"zh":"四季","py":"sìjì","vi":"bốn mùa","pos":"dt."},{"zh":"春天","py":"chūntiān","vi":"mùa xuân","pos":"dt."},{"zh":"夏天","py":"xiàtiān","vi":"mùa hè","pos":"dt."},{"zh":"凉快","py":"liángkuai","vi":"mát mẻ","pos":"tt."},{"zh":"秋天","py":"qiūtiān","vi":"mùa thu","pos":"dt."},{"zh":"叶子","py":"yèzi","vi":"lá","pos":"dt."},{"zh":"变成","py":"biànchéng","vi":"trở thành, biến thành","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在街上，王一飞和白家月边走边聊。Vương Nhất Phi và Bạch Gia Nguyệt vừa đi vừa trò chuyện trên đường phố.","audio":"12-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"王老师，您看，这条街上的树都开花了。","py":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shang de shù dōu kāihuā le.","vi":"Cô Vương, cô nhìn kìa! Hàng cây dọc con phố này đã nở hoa rồi."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"上周我去公园坐船了，公园里的花也开了。","py":"Shàng zhōu wǒ qù gōngyuán zuòchuán le, gōngyuán li de huā yě kāi le.","vi":"Tuần trước cô đi thuyền trong công viên, hoa ở đó cũng nở rồi."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"天气这么好，下午我也想去公园坐船。","py":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuòchuán.","vi":"Thời tiết đẹp như vậy, chiều nay em muốn đi chèo thuyền trong công viên."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"去吧！今天是工作日，人应该不多。","py":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","vi":"Đi đi em! Hôm nay vẫn là ngày làm việc nên chắc sẽ không có nhiều người đâu."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"您有时间吗？我想跟您一起去。","py":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","vi":"Cô có thời gian không ạ? Em muốn đi cùng cô."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我今天下午有课，不能去太远的地方。","py":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.","vi":"Chiều nay cô có giờ dạy nên không thể đi xa được."},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那咱们换一天去？","py":"Nà zánmen huàn yì tiān qù?","vi":"Vậy chúng ta để hôm khác đi ạ?"},{"section":"Bài khóa 1","context":"","audio":"12-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"行。或者明天去，或者后天去，我给你打电话。","py":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vi":"Được, hoặc là ngày mai, hoặc là ngày kia, cô sẽ gọi điện cho em."},{"section":"Bài khóa 2","context":"在街上，王一飞和白家月一起散步。Vương Nhất Phi và Bạch Gia Nguyệt đang đi dạo cùng nhau trên đường phố.","audio":"12-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"刚才还是大晴天呢，怎么突然就刮起风来了？","py":"Gāngcái háishi dà qíngtiān ne, zěnme tūrán jiù guāqǐ fēng lái le?","vi":"Vừa nãy trời còn đang nắng, bỗng nhiên lại nổi gió to thế nhỉ?"},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"好像新闻里说今天有雨。","py":"Hǎoxiàng xīnwén li shuō jīntiān yǒu yǔ.","vi":"Bản tin hình như nói rằng hôm nay trời sẽ mưa đấy."},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"啊？我每天书包里都放着雨伞，就今天没带。","py":"Á? Wǒ měitiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vi":"Thật ạ? Em thường để ô trong cặp sách, nhưng hôm nay em lại không mang theo."},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我可以借给你，我车里有一把伞和一件雨衣。","py":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē li yǒu yì bǎ sǎn hé yí jiàn yǔyī.","vi":"Cô có thể cho em mượn một cái, trong xe của cô có cả ô và áo mưa."},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"谢谢，希望下午天气能变好。","py":"Xièxie, xīwàng xiàwǔ tiānqì néng biànhǎo.","vi":"Em cảm ơn cô, hy vọng chiều nay trời sẽ tốt hơn."},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"这个季节天气变化很快。","py":"Zhège jìjié tiānqì biànhuà hěn kuài.","vi":"Thời tiết thay đổi rất nhanh vào mùa này."},{"section":"Bài khóa 2","context":"","audio":"12-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"雨已经下起来了，咱们快点儿走吧。","py":"Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba.","vi":"Trời đã bắt đầu mưa rồi kìa, mình mau đi thôi."},{"section":"Bài khóa 3","context":"在教室里，王一飞和白家月躲雨。Vương Nhất Phi và Bạch Gia Nguyệt đang trú mưa trong lớp học.","audio":"12-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"您来这里已经一年多了，习惯了吧？","py":"Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?","vi":"Cô đã đến đây hơn một năm rồi, cô quen với cuộc sống ở đây chưa ạ?"},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"别的早就习惯了，就是天气我还不太习惯。","py":"Biéde zǎojiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.","vi":"Cô đã quen với hầu hết mọi thứ, nhưng cô vẫn chưa quen với thời tiết ở đây."},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"为什么？您不喜欢这里的天气吗？","py":"Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?","vi":"Tại sao ạ? Cô không thích thời tiết ở đây sao?"},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我觉得冬天太冷了。","py":"Wǒ juéde dōngtiān tài lěng le.","vi":"Cô cảm thấy mùa đông ở đây lạnh quá."},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"冬天虽然冷，但是下雪的时候特别漂亮。","py":"Dōngtiān suīrán lěng, dànshì xiàxuě de shíhou tèbié piàoliang.","vi":"Tuy mùa đông lạnh, nhưng nó đặc biệt đẹp khi tuyết rơi ạ."},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","py":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xiàxuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vi":"Cô cũng thích tuyết. Bắc Kinh thường xuyên có tuyết rơi, nhưng nghe nói năm nay tuyết mới chỉ rơi có một lần thôi."},{"section":"Bài khóa 3","context":"","audio":"12-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","py":"Wǒ méi guānzhùguo Běijīng de tiānqì, dànshì xīnwén li shuōguo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.","vi":"Em không theo dõi thời tiết ở Bắc Kinh, nhưng tin tức nói rằng, mùa đông năm nay rất nhiều nơi tuyết rơi rất ít."},{"section":"Bài khóa 4","context":"在家里，王一飞在写日记。Vương Nhất Phi đang ngồi viết nhật ký ở trong nhà.","audio":"12-7.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我离开北京到这里工作一年多了。这一年多住下来，我还是更喜欢北京的四季。北京的春天最舒服，天气不冷不热。夏天白天很热，但是晚上比较凉快。秋天树上的叶子都变成了红色、黄色，非常漂亮。冬天不但冷，而且风很大，我最不喜欢冬天。每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","py":"Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le. Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì. Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè. Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai. Qiūtiān shù shang de yèzi dōu biànchéngle hóngsè, huángsè, fēicháng piàoliang. Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān. Měi gè rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?","vi":"Đã hơn một năm kể từ khi tôi rời Bắc Kinh để đến đây làm việc. Hơn một năm nay sống ở đây, tôi vẫn thích bốn mùa rõ rệt ở Bắc Kinh hơn. Mùa xuân ở Bắc Kinh dễ chịu nhất, trời không quá lạnh cũng không quá nóng. Mùa hè ban ngày vô cùng nóng, nhưng buổi tối lại mát mẻ dễ chịu. Vào mùa thu, những chiếc lá chuyển sang sắc đỏ và vàng, vô cùng đẹp. Mùa đông không chỉ lạnh mà gió còn rất to, tôi không thích mùa đông nhất. Mỗi người đều có mùa yêu thích của mình, bạn thích mùa nào nhất?"}],"dialogQuestions":[],"grammar":{"g1":{"han":"选择复句“或者……，或者……”","py":"Xuǎnzé fùjù “huòzhě..., huòzhě...”","title":"Câu ghép lựa chọn “或者……，或者……”","explain":"选择复句“或者……，或者……”表示在两个或多个可能的选项中选择一个，多用于口语。\nCâu ghép lựa chọn “或者……，或者……” thường dùng trong văn nói, biểu thị lựa chọn một trong số hai hoặc nhiều phương án khác nhau.","examples":[{"zh":"或者明天去，或者后天去，我给你打电话。","py":"Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","vi":"Hoặc là ngày mai đi, hoặc là ngày kia đi, cô sẽ gọi điện cho em.","hl":"或者……，或者……"},{"zh":"我们或者今天去电影院看电影，或者明天在家看电影。","py":"Wǒmen huòzhě jīntiān qù diànyǐngyuàn kàn diànyǐng, huòzhě míngtiān zài jiā kàn diànyǐng.","vi":"Chúng ta hoặc là hôm nay ra rạp xem phim, hoặc là ngày mai ở nhà xem phim.","hl":"或者……，或者……"},{"zh":"晚饭你自己选，或者吃中国菜，或者吃日本菜，或者吃泰国菜。","py":"Wǎnfàn nǐ zìjǐ xuǎn, huòzhě chī Zhōngguó cài, huòzhě chī Rìběn cài, huòzhě chī Tàiguó cài.","vi":"Bữa tối bạn tự chọn đi, hoặc ăn món Trung, hoặc ăn món Nhật, hoặc ăn món Thái.","hl":"或者……，或者……"}],"struct":"或者 + Lựa chọn 1，或者 + Lựa chọn 2 (，或者 + Lựa chọn 3...)","note":"Dùng trong câu trần thuật hoặc câu cầu khiến để đưa ra các khả năng lựa chọn."},"g2":{"han":"趋向补语的引申用法（2）","py":"Qūxiàng bǔyǔ de yǐnshēn yòngfǎ (2)","title":"Cách dùng mở rộng của bổ ngữ xu hướng (2)","explain":"趋向补语“起来”用在动词或形容词后面，表示动作开始进行或进入一个新的状态。如果动词带宾语，宾语应该在“起”和“来”的中间。\nBổ ngữ xu hướng “起来” đặt sau động từ hoặc tính từ, biểu thị sự bắt đầu của hành động hoặc hành động chuyển sang trạng thái mới. Nếu động từ có tân ngữ, tân ngữ đặt giữa “起” và “来”.","examples":[{"zh":"雨已经下起来了。","py":"Yǔ yǐjīng xià qǐlái le.","vi":"Trời đã bắt đầu mưa rồi.","hl":"下起来"},{"zh":"最近天气热起来了。","py":"Zuìjìn tiānqì rè qǐlái le.","vi":"Gần đây thời tiết bắt đầu nóng lên rồi.","hl":"热起来"},{"zh":"怎么突然刮起风来了？","py":"Zěnme tūrán guāqǐ fēng lái le?","vi":"Sao đột nhiên lại nổi gió lên thế?","hl":"刮起风来"}],"struct":"Động từ / Tính từ + 起来 (+ 了) | Động từ + 起 + Tân ngữ + 来 (+ 了)","note":"Nếu động từ có tân ngữ đi kèm (như 刮风, 下雨, 唱歌), tân ngữ đặt giữa 起 và 来: 刮起风来."},"g3":{"han":"范围副词“就”","py":"Fànwéi fùcí “jiù”","title":"Phó từ chỉ phạm vi “就”","explain":"范围副词“就”用在带有数量词的动词前面，表示说话人认为数量少、程度轻、时间短等意义。“就”用在名词或名词性主语前，表示例外情况。\nPhó từ chỉ phạm vi “就” đặt trước động từ mang số lượng để biểu thị số lượng ít, mức độ thấp hoặc thời gian ngắn. “就” cũng có thể đặt trước danh từ hoặc cụm danh từ để biểu thị tình huống ngoại lệ.","examples":[{"zh":"北京常常下雪，但听说今年就下了一次。","py":"Běijīng chángcháng xiàxuě, dàn tīngshuō jīnnián jiù xiàle yí cì.","vi":"Bắc Kinh thường có tuyết rơi, nhưng nghe nói năm nay chỉ rơi có một lần.","hl":"就下了一次"},{"zh":"我每天书包里都放着雨伞，就今天没带。","py":"Wǒ měitiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","vi":"Ngày nào trong cặp tôi cũng để sẵn ô, chỉ có hôm nay là không mang.","hl":"就今天"},{"zh":"你们点的菜都挺好吃的，就我点的这个菜不太好吃。","py":"Nǐmen diǎn de cài dōu tǐng hǎochī de, jiù wǒ diǎn de zhège cài bú tài hǎochī.","vi":"Các món các bạn gọi đều ngon cả, chỉ có món này tôi gọi là không ngon lắm.","hl":"就我点的这个菜"}],"struct":"就 + Động từ + Số lượng từ (số lượng ít) | 就 + Danh từ / Cụm danh từ (ngoại lệ)","note":"Trong nghĩa chỉ số lượng ít hoặc ngoại lệ, “就” tương đương với “chỉ” (只)."},"g4":{"han":"趋向补语的引申用法（3）","py":"Qūxiàng bǔyǔ de yǐnshēn yòngfǎ (3)","title":"Cách dùng mở rộng của bổ ngữ xu hướng (3)","explain":"趋向补语“下来”用在动词后，表示完成一个费时、费力、需要克服一定困难的动作行为。\nBổ ngữ xu hướng “下来” được đặt sau động từ, biểu thị một hành động cần nhiều thời gian, công sức hoặc vượt qua khó khăn để hoàn thành.","examples":[{"zh":"这一年多住下来，我还是更喜欢北京的四季。","py":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","vi":"Sống suốt hơn một năm nay rồi, tôi vẫn thích bốn mùa ở Bắc Kinh hơn.","hl":"住下来"},{"zh":"这半年练下来，他画画的水平提高了不少。","py":"Zhè bàn nián liàn xiàlái, tā huàhuà de shuǐpíng tígāole bù shǎo.","vi":"Kiên trì luyện tập suốt nửa năm nay, trình độ vẽ tranh của cậu ấy tiến bộ không ít.","hl":"练下来"},{"zh":"5000米的长跑比赛，没想到我跑下来了。","py":"Wǔqiān mǐ de chángpǎo bǐsài, méi xiǎngdào wǒ pǎo xiàlái le.","vi":"Cuộc thi chạy đường dài 5000m, không ngờ tôi đã chạy hết được.","hl":"跑下来了"}],"struct":"Khoảng thời gian / Động từ + 下来","note":"Thường đi kèm với biểu thị thời gian dài hoặc nhiệm vụ đòi hỏi sự kiên trì (住下来, 练下来, 跑下来, 学下来)."}},"grammarQuiz":[{"id":"hsk3_b12_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"突然 (____) 起风来了，可能会下雨。","opts":[{"t":"刮","ok":true},{"t":"季节","ok":false},{"t":"把","ok":false},{"t":"借","ok":false},{"t":"地方","ok":false}],"exp":"Đáp án A (刮): ‘Đột nhiên nổi gió lên rồi, có thể trời sẽ mưa.’"},{"id":"hsk3_b12_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我在昨天拍照的 (____) 等你，别走错了。","opts":[{"t":"地方","ok":true},{"t":"刮","ok":false},{"t":"季节","ok":false},{"t":"把","ok":false},{"t":"借","ok":false}],"exp":"Đáp án E (地方): ‘Mình đợi bạn ở chỗ hôm qua chụp ảnh nhé, đừng đi nhầm đấy.’"},{"id":"hsk3_b12_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这 (____) 雨伞不大不小，可以放在书包里。","opts":[{"t":"把","ok":true},{"t":"刮","ok":false},{"t":"季节","ok":false},{"t":"借","ok":false},{"t":"地方","ok":false}],"exp":"Đáp án C (把): ‘Chiếc ô này kích cỡ vừa phải, có thể để vào trong cặp sách.’"},{"id":"hsk3_b12_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我把这件雨衣 (____) 给你吧，我开车不需要穿。","opts":[{"t":"借","ok":true},{"t":"刮","ok":false},{"t":"季节","ok":false},{"t":"把","ok":false},{"t":"地方","ok":false}],"exp":"Đáp án D (借): ‘Tôi cho bạn mượn chiếc áo mưa này nhé, tôi lái xe nên không cần mặc.’"},{"id":"hsk3_b12_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这个 (____) 北京不冷不热，很多人都在这个时候来旅游。","opts":[{"t":"季节","ok":true},{"t":"刮","ok":false},{"t":"把","ok":false},{"t":"借","ok":false},{"t":"地方","ok":false}],"exp":"Đáp án B (季节): ‘Mùa này Bắc Kinh không lạnh không nóng, nhiều người đến du lịch vào thời điểm này.’"},{"id":"hsk3_b12_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这里的冬天 (____) 下雪吗？\nB: 不是，每年就二月雪最多。","opts":[{"t":"常常","ok":true},{"t":"刚才","ok":false},{"t":"关注","ok":false},{"t":"变成","ok":false},{"t":"变","ok":false}],"exp":"Đáp án D (常常): ‘Mùa đông ở đây có thường xuyên có tuyết rơi không?’"},{"id":"hsk3_b12_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: (____) 下大雨了，天气凉快了很多。\nB: 没错，每天都能这么凉快就好了。","opts":[{"t":"刚才","ok":true},{"t":"关注","ok":false},{"t":"变成","ok":false},{"t":"常常","ok":false},{"t":"变","ok":false}],"exp":"Đáp án A (刚才): ‘Lúc nãy trời mưa to rồi, thời tiết mát mẻ hơn nhiều.’"},{"id":"hsk3_b12_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这几天天气不好，我怕下午的飞机会晚点。\nB: 放心吧，我一直在 (____) 天气，下午是晴天。","opts":[{"t":"关注","ok":true},{"t":"刚才","ok":false},{"t":"变成","ok":false},{"t":"常常","ok":false},{"t":"变","ok":false}],"exp":"Đáp án B (关注): ‘Yên tâm đi, mình vẫn luôn theo dõi thời tiết, chiều nay trời nắng.’"},{"id":"hsk3_b12_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这里以前是一片草地，现在 (____) 了学校和医院。\nB: 是啊，变化真大，都不认识了。","opts":[{"t":"变成","ok":true},{"t":"刚才","ok":false},{"t":"关注","ok":false},{"t":"常常","ok":false},{"t":"变","ok":false}],"exp":"Đáp án C (变成): ‘Trước đây chỗ này là một bãi cỏ, giờ đã biến thành trường học và bệnh viện rồi.’"},{"id":"hsk3_b12_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 下了一晚上的雪，外面全都 (____) 白了。\nB: 是的，太漂亮了！我是第一次见到这么大的雪，咱们出去看看吧。","opts":[{"t":"变","ok":true},{"t":"刚才","ok":false},{"t":"关注","ok":false},{"t":"变成","ok":false},{"t":"常常","ok":false}],"exp":"Đáp án E (变): ‘Tuyết rơi suốt một đêm, bên ngoài biến thành màu trắng hết cả rồi.’"},{"id":"hsk3_b12_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"这条街的环境怎么样？","opts":[{"t":"C 树都开花了","ok":true},{"t":"A 人很多","ok":false},{"t":"B 树很少","ok":false}],"exp":"Bạch Gia Nguyệt nói: “王老师，您看，这条街上的树都开花了。”"},{"id":"hsk3_b12_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"她们今天为什么不去公园？","opts":[{"t":"C 王老师没时间","ok":true},{"t":"A 今天天气不好","ok":false},{"t":"B 今天是工作日","ok":false}],"exp":"Cô Vương Nhất Phi nói: “我今天下午有课，不能去太远的地方。”"},{"id":"hsk3_b12_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"新闻里说今天会是什么天气？","opts":[{"t":"C 下雨","ok":true},{"t":"A 晴天","ok":false},{"t":"B 下雪","ok":false}],"exp":"Vương Nhất Phi nói: “好像新闻里说今天有雨。”"},{"id":"hsk3_b12_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"这个季节的天气是什么样的？","opts":[{"t":"A 变化很快","ok":true},{"t":"B 经常下雨","ok":false},{"t":"C 每天晴天","ok":false}],"exp":"Vương Nhất Phi nói: “这个季节天气变化很快。”"},{"id":"hsk3_b12_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一飞来这里多长时间了？","opts":[{"t":"A 一年多了","ok":true},{"t":"B 两年多了","ok":false},{"t":"C 好多年了","ok":false}],"exp":"Bạch Gia Nguyệt nói: “您来这里已经一年多了，习惯了吧？”"},{"id":"hsk3_b12_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月是怎么知道今年很多地方都下雪少的？","opts":[{"t":"A 看新闻","ok":true},{"t":"B 问王老师","ok":false},{"t":"C 听朋友说","ok":false}],"exp":"Bạch Gia Nguyệt nói: “但是新闻里说过，今年冬天很多地方雪下得都少了。”"},{"id":"hsk3_b12_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一飞喜欢哪个城市的四季？","opts":[{"t":"A 北京","ok":true},{"t":"B 她工作的地方","ok":false},{"t":"C 没有冬天的城市","ok":false}],"exp":"Vương Nhất Phi viết: “我还是更喜欢北京的四季。”"},{"id":"hsk3_b12_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一飞觉得北京哪个季节最舒服？","opts":[{"t":"A 春天","ok":true},{"t":"B 夏天","ok":false},{"t":"C 秋天","ok":false}],"exp":"Bài khóa 4: “北京的春天最舒服，天气不冷不热。”"}],"chars":["街","开","花","公","园","船","工","作","日","地","方","刚","才","刮","风","新","闻","伞","借","把","雨","衣","变","季","节","化","冬","天","常","关","注","四","春","夏","凉","快","秋","叶","子","成","这","个","气","很"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 110): “不A不B”表示某个状态介于A和B之间，既不是A，也不是B，表达适中的程度。Cụm từ “不A不B” biểu thị một trạng thái nằm giữa A và B, không phải A cũng không phải B, dùng để diễn đạt mức độ ở giữa (不大不小, 不多不少, 不胖不瘦, 不冷不热...).","Món quà của Tiểu Ngữ (trang 113, video 12-1): 中国四季的代表城市 — Một số thành phố tiêu biểu có bốn mùa ở Trung Quốc.","Tổng kết học tập Bài 10–12 (trang 113–114): 11 điểm ngữ pháp gồm “把”字句(1)/(2)/(3), 在……上/中/下, “还是”和“或者”, 看来, 对……来说, 或者……，或者……, 趋向补语的引申用法(2)起来/(3)下来 và 范围副词“就”.","Câu hỏi thảo luận Bài khóa 1: (1) 上周王一飞去公园做什么了？ (2) 白家月今天想做什么？ (3) 她们可能什么时候去公园？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月今天带雨伞了吗？ (2) 王一飞可以借给白家月什么？ (3) 她们现在要做什么？为什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一飞对什么还不太习惯？ (2) 白家月为什么喜欢冬天？ (3) 新闻里说过什么？","Câu hỏi thảo luận Bài khóa 4: (1) 北京的夏天是什么样的？ (2) 北京的秋天是什么样的？ (3) 王一飞为什么最不喜欢冬天？"],"workbook":null},"13":{"pages":"115–123","titleZh":"我的新邻居来自英国","titlePy":"Wǒ de xīn línjū láizì Yīngguó","titleVi":"Hàng xóm mới của tôi đến từ Vương quốc Anh","goals":["能听懂并谈论不同地区生活习惯的差异。Có thể nghe hiểu và thảo luận được sự khác biệt trong thói quen sinh hoạt giữa các vùng.","能听懂并使用感谢、祝福和夸赞等礼貌用语。Có thể hiểu và sử dụng được cách diễn đạt lịch sự như cảm ơn, lời chúc và lời khen.","掌握“一边……，一边……”的用法，能描述同时进行的动作。Nắm vững cách sử dụng của cấu trúc “一边……，一边……” để miêu tả hai hành động diễn ra đồng thời."],"words":[{"zh":"请客","py":"qǐngkè","vi":"đãi khách, mời khách","pos":"đgt."},{"zh":"南方","py":"nánfāng","vi":"miền Nam","pos":"dt."},{"zh":"北方","py":"běifāng","vi":"miền Bắc","pos":"dt."},{"zh":"做法","py":"zuòfǎ","vi":"cách làm","pos":"dt."},{"zh":"不同","py":"bù tóng","vi":"khác nhau","pos":""},{"zh":"加","py":"jiā","vi":"thêm","pos":"đgt."},{"zh":"的话","py":"dehuà","vi":"nếu","pos":"trợ."},{"zh":"做客","py":"zuòkè","vi":"làm khách","pos":"đgt."},{"zh":"邻居","py":"línjū","vi":"hàng xóm, láng giềng","pos":"dt."},{"zh":"放心","py":"fàngxīn","vi":"yên tâm","pos":"đgt."},{"zh":"酒","py":"jiǔ","vi":"rượu","pos":"dt."},{"zh":"放","py":"fàng","vi":"đặt, để","pos":"đgt."},{"zh":"客人","py":"kèrén","vi":"khách, khách hàng","pos":"dt."},{"zh":"晚会","py":"wǎnhuì","vi":"dạ hội (buổi biểu diễn, giao lưu vào buổi tối)","pos":"dt."},{"zh":"礼物","py":"lǐwù","vi":"quà, món quà","pos":"dt."},{"zh":"画家","py":"huàjiā","vi":"hoạ sĩ","pos":"dt."},{"zh":"盘子","py":"pánzi","vi":"đĩa","pos":"dt."},{"zh":"一边","py":"yìbiān","vi":"vừa (...vừa...)","pos":"phó."},{"zh":"聊天儿","py":"liáotiānr","vi":"trò chuyện, nói chuyện, tán gẫu","pos":"đgt."},{"zh":"来自","py":"láizì","vi":"đến từ","pos":"đgt."},{"zh":"夫妻","py":"fūqī","vi":"vợ chồng","pos":"dt."},{"zh":"直到","py":"zhídào","vi":"cho đến, mãi đến","pos":"đgt."},{"zh":"地图","py":"dìtú","vi":"bản đồ","pos":"dt."},{"zh":"点","py":"diǎn","vi":"điểm, chấm nhỏ","pos":"dt."},{"zh":"感到","py":"gǎndào","vi":"cảm thấy","pos":"đgt."},{"zh":"东方","py":"dōngfāng","vi":"phương Đông","pos":"dt."},{"zh":"文化","py":"wénhuà","vi":"văn hoá","pos":"dt."},{"zh":"英国","py":"Yīngguó","vi":"Vương quốc Anh","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"在饭馆，杨同乐请同事吃饭。Dương Đồng Lạc mời đồng nghiệp ăn cơm tại nhà hàng.","audio":"13-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"今天我请客，你们想吃什么就点什么！","py":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","vi":"Hôm nay mình mời nhé, mọi người muốn ăn món gì thì cứ gọi món đó nhé!"},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那我就不客气了。听说这家饭馆的鱼做得很特别？","py":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?","vi":"Vậy thì chị sẽ không khách sáo đâu. Nghe nói món cá ở nhà hàng này rất đặc biệt."},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","py":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bù tóng. Chúle yú, nǐmen hái xiǎng chī shénme?","vi":"Đúng vậy, cách chế biến các món ăn miền Nam khác với các món miền Bắc. Ngoài món cá ra, mọi người còn muốn ăn gì nữa?"},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"同事","name":"Đồng nghiệp","zh":"我不常吃南方菜，还是你决定吧。","py":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba.","vi":"Mình không hay ăn đồ miền Nam, hay các bạn cứ quyết đi nhé."},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"好，那再加一个鸡肉，一个……","py":"Hǎo, nà zài jiā yí gè jīròu, yí gè...","vi":"Được, vậy thêm một món gà và một món..."},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"咱们就三个人，别点那么多。","py":"Zánmen jiù sān gè rén, bié diǎn nàme duō.","vi":"Chỉ có ba người chúng ta thôi mà, đừng gọi nhiều thế."},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"好，那先来这几个菜。","py":"Hǎo, nà xiān lái zhè jǐ gè cài.","vi":"Được, vậy cứ gọi trước những món này nhé."},{"section":"Bài khóa 1","context":"","audio":"13-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","py":"Duìle, xià zhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài.","vi":"Đúng rồi, tuần tới là sinh nhật con trai mình. Nếu như các bạn có thời gian thì hãy ghé nhà mình chơi, mình sẽ nấu vài món Bắc Kinh mời các bạn."},{"section":"Bài khóa 2","context":"在家里，王一雪和刘明为生日会做准备。Vương Nhất Tuyết và Lưu Minh đang chuẩn bị cho bữa tiệc sinh nhật ở nhà.","audio":"13-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"第一次请新邻居来做客，总是担心有什么没准备好。","py":"Dì-yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo.","vi":"Đây là lần đầu tiên chúng ta mời những người hàng xóm mới sang chơi, em cứ lo lắng rằng chúng mình có thể chuẩn bị chưa được đầy đủ."},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"放心吧，我帮你看了，都已经准备好了。","py":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le.","vi":"Yên tâm nhé, anh đã kiểm tra giúp em rồi, chúng ta đều đã chuẩn bị tốt rồi."},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我记得刚才已经把饮料拿出来了，怎么不见了？","py":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bújiàn le?","vi":"Em nhớ vừa xong em đã lấy đồ uống ra rồi, sao không thấy chúng nhỉ?"},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","py":"Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng li le, kèrén lái le zài ná chūlái.","vi":"Anh đã để tất cả đồ uống và rượu vào tủ lạnh rồi. Khách đến thì chúng ta sẽ lấy chúng ra."},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"音乐的声音合适吗？","py":"Yīnyuè de shēngyīn héshì ma?","vi":"Âm lượng nhạc đã phù hợp chưa anh?"},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"你把声音开得太大了，我去关小一点儿。","py":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr.","vi":"Em bật nhạc hơi to rồi, anh sẽ vặn nhỏ xuống một chút."},{"section":"Bài khóa 2","context":"","audio":"13-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好，那我们就等客人来吧。","py":"Hǎo, nà wǒmen jiù děng kèrén lái ba.","vi":"Vâng, vậy bây giờ chúng ta đợi khách đến thôi."},{"section":"Bài khóa 3","context":"在家里，王一雪和刘明办生日会。Vương Nhất Tuyết và Lưu Minh đang tổ chức tiệc sinh nhật ở trong nhà.","audio":"13-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","py":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn.","vi":"Cảm ơn tất cả mọi người đã đến dự tiệc sinh nhật của con trai mình. Mình hy vọng mọi người sẽ có thể chơi thật vui vẻ vào tối nay."},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","py":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèile yí gè xiǎo lǐwù, xīwàng nǐ xǐhuan!","vi":"Chúc mừng sinh nhật Tiểu Minh! Chú đã chuẩn bị một món quà nhỏ, hy vọng cháu thích nó!"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"谢谢您，我可以打开吗？","py":"Xièxie nín, wǒ kěyǐ dǎkāi ma?","vi":"Cháu cảm ơn chú ạ! Cháu có thể mở nó ra không ạ?"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","py":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?","vi":"Đương nhiên rồi. Mẹ cháu có nói rằng cháu rất thích vẽ giống như chị mình vậy, đúng không?"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","py":"Duì, wǒ xiǎng zuò yì míng huàjiā. Ā! Huàbǎn hé huàbǐ, zhè zhèngshì wǒ xūyào de. Wǒ tài xǐhuan le.","vi":"Vâng ạ, cháu muốn trở thành một hoạ sĩ. Ồ, bảng vẽ và bút vẽ, đây chính xác là những gì cháu mong muốn. Cháu thích nó lắm ạ!"},{"section":"Bài khóa 3","context":"","audio":"13-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","py":"Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vi":"Chị đi lấy đĩa đây, chúng ta vừa ăn bánh kem vừa trò chuyện nhé."},{"section":"Bài khóa 4","context":"在家里，王一雪在写日记。Vương Nhất Tuyết đang viết nhật ký ở trong nhà.","audio":"13-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我的新邻居是来自英国的夫妻。上周我去他们家做客了。他们做了很多好吃的，还准备了英国的红茶。那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。后来，他们感到东方的文化很特别，就开始学习中文。今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","py":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī. Shàng zhōu wǒ qù tāmen jiā zuòkè le. Tāmen zuòle hěn duō hǎochī de, hái zhǔnbèile Yīngguó de hóngchá. Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí\u0027èr diǎn duō cái huíjiā. Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmian měi yí gè hóngdiǎn dōu shì tāmen qùguo de dìfang. Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén. Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguó cài.","vi":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ Vương quốc Anh. Tuần trước, tôi đã đến thăm nhà họ. Họ đã nấu rất nhiều món ăn ngon, còn chuẩn bị trà đen Anh Quốc. Hôm đó, chúng tôi đã vừa uống trà đen vừa trò chuyện, mãi tới hơn 12 giờ đêm mới về nhà. Khi còn trẻ, cả hai người bọn họ đều rất thích du lịch, trong nhà họ có một bản đồ thế giới, mỗi chấm đỏ trên bản đồ chính là những nơi họ đã từng ghé thăm. Sau này, họ cảm thấy văn hoá phương Đông rất đặc biệt và bắt đầu học tiếng Trung Quốc. Hôm nay là sinh nhật của Tiểu Minh, tôi đã mời họ đến nhà chơi, để họ trải nghiệm cuộc sống một gia đình Trung Quốc, cũng để thưởng thức món ăn Trung Hoa."}],"dialogQuestions":[],"grammar":{"g1":{"han":"假设复句“……的话，就……”","py":"Jiǎshè fùjù “...dehuà, jiù...”","title":"Câu ghép giả định “……的话，就……”","explain":"假设复句“……的话，就……”中，前一分句表示假设的情况，后一分句表示产生的结果或得出的结论，多用于口语。\nCâu ghép giả định “……的话，就……” thường dùng trong văn nói, trong đó mệnh đề thứ nhất đưa ra giả thiết, mệnh đề thứ hai biểu thị kết quả hoặc kết luận có được.","examples":[{"zh":"你们有时间的话，就来我家做客。","py":"Nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè.","vi":"Nếu các bạn có thời gian thì tới nhà mình làm khách nhé.","hl":"的话，就"},{"zh":"你觉得满意的话，咱们就买。","py":"Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.","vi":"Nếu bạn thấy hài lòng thì chúng ta mua nhé.","hl":"的话，就"},{"zh":"明天天气好的话，我就去爬山。","py":"Míngtiān tiānqì hǎo dehuà, wǒ jiù qù páshān.","vi":"Nếu ngày mai thời tiết đẹp thì mình sẽ đi leo núi.","hl":"的话，就"}],"struct":"Giả thiết + 的话，+ (Chủ ngữ 2 +) 就 + Kết quả","note":"Có thể kết hợp với “如果/要是” ở đầu vế giả thiết (Nếu... thì...), nhưng trong khẩu ngữ thường lược bỏ 如果 và chỉ dùng “…的话” ở cuối vế 1."},"g2":{"han":"“把”字句（4）","py":"“Bǎ” zìjù (4)","title":"Câu chữ “把” (4)","explain":"“把”字句的动词后使用趋向补语或状态补语，表示动作对确定的人或事物产生位置或者状态变化的影响。基本结构：主语+把+宾语+动词+趋向补语/状态补语。\nTrong câu chữ “把”, sau động từ có thể dùng bổ ngữ xu hướng hoặc bổ ngữ trạng thái để biểu thị sự thay đổi vị trí hoặc trạng thái của sự vật.","examples":[{"zh":"你把声音开得太大了。","py":"Nǐ bǎ shēngyīn kāi de tài dà le.","vi":"Em bật âm thanh to quá rồi.","hl":"把声音开得太大了"},{"zh":"他把球踢进去了吗？","py":"Tā bǎ qiú tī jìnqù le ma?","vi":"Cậu ấy sút bóng vào rồi à?","hl":"把球踢进去"},{"zh":"你把字写得太小了，我看不清楚。","py":"Nǐ bǎ zì xiě de tài xiǎo le, wǒ kàn bu qīngchu.","vi":"Bạn viết chữ nhỏ quá rồi, mình nhìn không rõ.","hl":"把字写得太小了"}],"struct":"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ xu hướng / 得 + Bổ ngữ trạng thái","note":"Phân biệt: 放进冰箱里 (xu hướng) và 开得太大了 (trạng thái)."},"g3":{"han":"并列复句“一边……，一边……”","py":"Bìngliè fùjù “yìbiān..., yìbiān...”","title":"Câu ghép đẳng lập “一边……，一边……”","explain":"并列复句“一边……，一边……”表示两个动作同时进行，可以紧缩为“边……边……”。\nCâu ghép đẳng lập sử dụng cấu trúc “一边……，一边……” để biểu thị hai hành động xảy ra đồng thời, có thể rút gọn thành “边……边……”.","examples":[{"zh":"咱们一边吃蛋糕，一边聊天儿吧。","py":"Zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","vi":"Chúng ta vừa ăn bánh kem vừa trò chuyện nhé.","hl":"一边……，一边……"},{"zh":"我喜欢一边跑步，一边听音乐。","py":"Wǒ xǐhuan yìbiān pǎobù, yìbiān tīng yīnyuè.","vi":"Tôi thích vừa chạy bộ vừa nghe nhạc.","hl":"一边……，一边……"},{"zh":"你不应该边开车边打电话。","py":"Nǐ bù yīnggāi biān kāichē biān dǎ diànhuà.","vi":"Bạn không nên vừa lái xe vừa gọi điện thoại.","hl":"边……边……"}],"struct":"Chủ ngữ + 一边 + Hành động 1，一边 + Hành động 2 (hoặc 边……边……)","note":"Hai hành động phải có thể diễn ra song song cùng lúc bởi cùng một chủ thể."}},"grammarQuiz":[{"id":"hsk3_b13_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们一边吃饭一边 (____)，时间过得很快。","opts":[{"t":"聊天儿","ok":true},{"t":"加","ok":false},{"t":"放","ok":false},{"t":"请客","ok":false},{"t":"做客","ok":false}],"exp":"Đáp án E (聊天儿): ‘Chúng tôi vừa ăn cơm vừa trò chuyện, thời gian trôi qua rất nhanh.’"},{"id":"hsk3_b13_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"咱们只点了一个鸡肉，再 (____) 几个肉菜吧。","opts":[{"t":"加","ok":true},{"t":"放","ok":false},{"t":"请客","ok":false},{"t":"做客","ok":false},{"t":"聊天儿","ok":false}],"exp":"Đáp án A (加): ‘Chúng ta mới gọi một món thịt gà, gọi thêm vài món thịt nữa đi.’"},{"id":"hsk3_b13_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"谢谢小王今天 (____)，下周你们都去我家，我给大家做饭吃。","opts":[{"t":"请客","ok":true},{"t":"加","ok":false},{"t":"放","ok":false},{"t":"做客","ok":false},{"t":"聊天儿","ok":false}],"exp":"Đáp án C (请客): ‘Cảm ơn Tiểu Vương hôm nay đã mời khách, tuần sau mọi người tới nhà mình nhé.’"},{"id":"hsk3_b13_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"在南方的一些城市，你去别人家 (____) 的时候会先喝茶。","opts":[{"t":"做客","ok":true},{"t":"加","ok":false},{"t":"放","ok":false},{"t":"请客","ok":false},{"t":"聊天儿","ok":false}],"exp":"Đáp án D (做客): ‘Ở một số thành phố miền Nam, khi đến nhà người khác làm khách bạn sẽ uống trà trước.’"},{"id":"hsk3_b13_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"桌子上 (____) 着一些饮料，你们想喝什么就拿，跟在自己家一样。","opts":[{"t":"放","ok":true},{"t":"加","ok":false},{"t":"请客","ok":false},{"t":"做客","ok":false},{"t":"聊天儿","ok":false}],"exp":"Đáp án B (放): ‘Trên bàn có để một ít đồ uống, mọi người muốn uống gì cứ lấy tự nhiên như ở nhà mình vậy.’"},{"id":"hsk3_b13_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 昨天的生日晚会玩得怎么样？\nB: 玩得太开心了，(____) 十一点我才回家。","opts":[{"t":"直到","ok":true},{"t":"不同","ok":false},{"t":"来自","ok":false},{"t":"感到","ok":false},{"t":"放心","ok":false}],"exp":"Đáp án B (直到): ‘Chơi vui quá mức, mãi đến 11 giờ mình mới về nhà.’"},{"id":"hsk3_b13_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你去外国人家做客，会不会 (____) 不太习惯？\nB: 第一次是有一点儿，但是慢慢就习惯了。","opts":[{"t":"感到","ok":true},{"t":"不同","ok":false},{"t":"直到","ok":false},{"t":"来自","ok":false},{"t":"放心","ok":false}],"exp":"Đáp án D (感到): ‘Bạn đến nhà người nước ngoài làm khách có cảm thấy hơi không quen không?’"},{"id":"hsk3_b13_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你的同学们是哪国人？\nB: 他们都 (____) 不同的地方，大家的文化也不一样。","opts":[{"t":"来自","ok":true},{"t":"不同","ok":false},{"t":"直到","ok":false},{"t":"感到","ok":false},{"t":"放心","ok":false}],"exp":"Đáp án C (来自): ‘Họ đều đến từ những nơi khác nhau, văn hoá của mọi người cũng không giống nhau.’"},{"id":"hsk3_b13_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 现在你可以 (____) 了，吃的喝的都准备好了。\nB: 我怕他们吃不习惯我做的菜。","opts":[{"t":"放心","ok":true},{"t":"不同","ok":false},{"t":"直到","ok":false},{"t":"来自","ok":false},{"t":"感到","ok":false}],"exp":"Đáp án E (放心): ‘Bây giờ em yên tâm được rồi đấy, đồ ăn thức uống đều chuẩn bị xong hết rồi.’"},{"id":"hsk3_b13_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你们国家过生日和这里过生日有什么 (____)？\nB: 差不多。我们也是先吃饭，再一起吃蛋糕。","opts":[{"t":"不同","ok":true},{"t":"直到","ok":false},{"t":"来自","ok":false},{"t":"感到","ok":false},{"t":"放心","ok":false}],"exp":"Đáp án A (不同): ‘Đón sinh nhật ở nước bạn và ở đây có gì khác nhau không?’"},{"id":"hsk3_b13_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"关于这家饭馆，可以知道什么？","opts":[{"t":"C 是南方菜饭馆","ok":true},{"t":"A 是一家面馆","ok":false},{"t":"B 鱼做得不好吃","ok":false}],"exp":"Dương Đồng Lạc xác nhận: “对，南方菜跟你们北方菜的做法不同。”"},{"id":"hsk3_b13_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"南方菜和北方菜有什么不一样？","opts":[{"t":"A 做法不同","ok":true},{"t":"B 用的肉不同","ok":false},{"t":"C 吃的鱼不同","ok":false}],"exp":"Dương Đồng Lạc nói: “南方菜跟你们北方菜的做法不同。”"},{"id":"hsk3_b13_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪和刘明在做什么？","opts":[{"t":"C 准备请客","ok":true},{"t":"A 找东西","ok":false},{"t":"B 打扫房子","ok":false}],"exp":"Hai vợ chồng chuẩn bị đồ uống, rượu và nhạc để đón hàng xóm mới sang làm khách."},{"id":"hsk3_b13_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪为什么很担心？","opts":[{"t":"C 第一次请新邻居来做客","ok":true},{"t":"A 东西都没准备好","ok":false},{"t":"B 饮料和酒找不到了","ok":false}],"exp":"Vương Nhất Tuyết nói: “第一次请新邻居来做客，总是担心有什么没准备好。”"},{"id":"hsk3_b13_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"朋友们为什么来王一雪家？","opts":[{"t":"C 她儿子过生日","ok":true},{"t":"A 她过生日","ok":false},{"t":"B 她喜欢请客","ok":false}],"exp":"Vương Nhất Tuyết cảm ơn mọi người đến dự tiệc sinh nhật của con trai chị."},{"id":"hsk3_b13_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪和朋友现在准备做什么？","opts":[{"t":"A 吃蛋糕","ok":true},{"t":"B 一起画画","ok":false},{"t":"C 吃北京菜","ok":false}],"exp":"Vương Nhất Tuyết nói: “我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。”"},{"id":"hsk3_b13_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪家的新邻居是什么人？","opts":[{"t":"B 英国夫妻","ok":true},{"t":"A 中国人","ok":false},{"t":"C 不会说中文的人","ok":false}],"exp":"Bài khóa 4: “我的新邻居是来自英国的夫妻。”"},{"id":"hsk3_b13_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪请邻居来家里做什么？","opts":[{"t":"B 请他们吃中国菜","ok":true},{"t":"A 教他们说中文","ok":false},{"t":"C 给他们讲旅游的事","ok":false}],"exp":"Bài khóa 4: “我请他们到我家玩，来看看中国人的家，也尝尝中国菜。”"}],"chars":["请","客","南","方","北","做","法","不","同","加","的","话","邻","居","放","心","酒","人","晚","会","礼","物","画","家","盘","子","一","边","聊","天","儿","来","自","夫","妻","直","到","地","图","点","感","东","文","化","英","国","我","新"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 120): 前缀、后缀 Tiền tố và hậu tố: 前缀“老”（老张、老师）；后缀“员”（球员、服务员、运动员）；后缀“家”（画家、音乐家）。","Câu hỏi thảo luận Bài khóa 1: (1) 这家饭馆什么菜做得很特别？ (2) 王一雪为什么要请同事去她家？ (3) 王一雪打算给大家做什么菜？","Câu hỏi thảo luận Bài khóa 2: (1) 王一雪刚才把什么拿出来了？ (2) 刘明把饮料和酒放在哪儿了？ (3) 刘明觉得音乐的声音合适吗？","Câu hỏi thảo luận Bài khóa 3: (1) 杨同乐送给刘小明什么礼物？ (2) 刘小明收到礼物后说了什么？ (3) 刘小明以后想做什么？","Câu hỏi thảo luận Bài khóa 4: (1) 上周王一雪去邻居家做什么了？ (2) 邻居家的世界地图有什么特别的？ (3) 她的邻居为什么学习中文？"],"workbook":null},"14":{"pages":"124–132","titleZh":"这本书被别人借走了","titlePy":"Zhè běn shū bèi biérén jièzǒu le","titleVi":"Quyển sách này đã bị người khác mượn rồi","goals":["能听懂并介绍校园活动。Có thể nghe hiểu và giới thiệu được các hoạt động trong trường học.","能听懂并表达对他人的鼓励。Có thể hiểu và diễn đạt được sự khích lệ đối với người khác.","掌握被动句（1）的用法，能表达被动意义。Nắm vững cách dùng của câu bị động (1) để diễn đạt nghĩa bị động."],"words":[{"zh":"词典","py":"cídiǎn","vi":"từ điển","pos":"dt."},{"zh":"最好","py":"zuìhǎo","vi":"tốt nhất","pos":"phó."},{"zh":"节","py":"jié","vi":"tiết, giờ (học)","pos":"lượng."},{"zh":"图书馆","py":"túshūguǎn","vi":"thư viện","pos":"dt."},{"zh":"被","py":"bèi","vi":"bị, được","pos":"giới."},{"zh":"名人","py":"míngrén","vi":"người nổi tiếng, danh nhân","pos":"dt."},{"zh":"故事","py":"gùshi","vi":"câu chuyện","pos":"dt."},{"zh":"然后","py":"ránhòu","vi":"sau đó","pos":"liên."},{"zh":"报纸","py":"bàozhǐ","vi":"báo, tờ báo","pos":"dt."},{"zh":"忘记","py":"wàngjì","vi":"quên","pos":"đgt."},{"zh":"电子书","py":"diànzǐshū","vi":"sách điện tử","pos":"dt."},{"zh":"女生","py":"nǚshēng","vi":"nữ sinh","pos":"dt."},{"zh":"表演","py":"biǎoyǎn","vi":"biểu diễn, diễn","pos":"đgt."},{"zh":"节目","py":"jiémù","vi":"tiết mục","pos":"dt."},{"zh":"怎么办","py":"zěnme bàn","vi":"làm (như) thế nào","pos":""},{"zh":"校长","py":"xiàozhǎng","vi":"hiệu trưởng","pos":"dt."},{"zh":"面前","py":"miànqián","vi":"phía trước","pos":"dt."},{"zh":"有些","py":"yǒuxiē","vi":"có một vài, có một số","pos":"phó."},{"zh":"相信","py":"xiāngxìn","vi":"tin, tin tưởng, tin rằng","pos":"đgt."},{"zh":"新年","py":"xīnnián","vi":"năm mới","pos":"dt."},{"zh":"班级","py":"bānjí","vi":"lớp học, cấp học","pos":"dt."},{"zh":"跳","py":"tiào","vi":"nhảy, khiêu vũ","pos":"đgt."},{"zh":"留学生","py":"liúxuéshēng","vi":"lưu học sinh","pos":"dt."},{"zh":"最后","py":"zuìhòu","vi":"cuối cùng","pos":"dt."},{"zh":"一块儿","py":"yíkuàir","vi":"cùng, cùng nhau, cùng một chỗ","pos":"phó./dt."},{"zh":"网站","py":"wǎngzhàn","vi":"trang web","pos":"dt."},{"zh":"视频","py":"shìpín","vi":"đoạn phim, video","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在校园餐厅，李文和白家月在聊天儿。Lý Văn và Bạch Gia Nguyệt đang trò chuyện trong căng tin trường.","audio":"14-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我借的这本词典最好今天还，但是我没时间去。","py":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.","vi":"Quyển từ điển mà anh mượn hôm nay đến hạn trả rồi, nhưng anh không có thời gian để đi trả."},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"下午我只有两节课，可以帮你去图书馆还书。","py":"Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.","vi":"Chiều nay em chỉ học hai tiết thôi, có thể đến thư viện trả hộ anh."},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"李文","name":"Lý Văn","zh":"那太谢谢了。你能再帮我借本书吗？","py":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?","vi":"Cảm ơn em rất nhiều! Em có thể mượn giúp anh một quyển sách khác không?"},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"行，你告诉我书名。","py":"Xíng, nǐ gàosu wǒ shūmíng.","vi":"Được chứ, anh cứ nói tên sách đi."},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","py":"Wǒ bǎ míngzi xiě zài zhǐ shang ba. Wǒ qùle hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jièzǒu le.","vi":"Anh viết tên sách ra giấy cho em nhé. Anh đi thư viện mấy lần nhưng quyển sách này lúc nào cũng có người mượn."},{"section":"Bài khóa 1","context":"","audio":"14-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"《名人的故事》？我有这本书。明天我借给你吧。","py":"“Míngrén de Gùshi”? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","vi":"“Câu chuyện về các danh nhân” à? Em có quyển đó đấy. Ngày mai em sẽ cho anh mượn."},{"section":"Bài khóa 2","context":"在校园里，白家月和安妮在聊天儿。Bạch Gia Nguyệt và Annie đang trò chuyện trong khuôn viên trường.","audio":"14-3.mp3","speaker":"安妮","name":"Annie","zh":"今天下课早，你一会儿做什么？","py":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","vi":"Hôm nay tan học sớm, lát nữa bạn định làm gì?"},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我今天忙得很，要先去图书馆借书，然后去游泳。","py":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vi":"Hôm nay mình rất bận. Mình phải đến thư viện để mượn vài quyển sách trước, sau đó đi bơi."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"安妮","name":"Annie","zh":"咱们一起走吧，我想去图书馆看看中文报纸。","py":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.","vi":"Chúng mình đi cùng nhau đi. Mình muốn đi thư viện xem mấy tờ báo tiếng Trung Quốc."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"等等，我的校园卡不见了，没有卡进不去图书馆。","py":"Děngdeng, wǒ de xiàoyuánkǎ bújiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.","vi":"Đợi một chút, thẻ sinh viên của mình không biết đâu rồi, không có thẻ sẽ không vào được thư viện đâu."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"安妮","name":"Annie","zh":"你想想上一次用是什么时候？","py":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?","vi":"Bạn có nhớ lần cuối cùng bạn dùng nó là khi nào không?"},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我忘记了，可能被我放在家里了。","py":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiāli le.","vi":"Mình không nhớ nữa, có thể mình đã để nó ở nhà mất rồi."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"安妮","name":"Annie","zh":"进不去图书馆也没关系，上网看看有没有电子书。","py":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","vi":"Không vào được thư viện cũng không sao đâu, lên mạng xem có sách điện tử không."},{"section":"Bài khóa 2","context":"","audio":"14-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"不行，我必须去，我还得帮李文还书呢。","py":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.","vi":"Không được, mình phải đi, mình còn phải trả sách cho Lý Văn nữa."},{"section":"Bài khóa 3","context":"在校园餐厅，李文和白家月边吃边聊。Lý Văn và Bạch Gia Nguyệt vừa ăn vừa trò chuyện trong căng tin trường.","audio":"14-5.mp3","speaker":"李文","name":"Lý Văn","zh":"下周学校有晚会，你知道吗？","py":"Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","vi":"Tuần tới trường có dạ hội đấy, em có biết không?"},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"知道，我和几个女生要表演一个节目。你也参加吗？","py":"Zhīdào, wǒ hé jǐ gè nǚshēng yào biǎoyǎn yí gè jiémù. Nǐ yě cānjiā ma?","vi":"Có, em và vài bạn nữ khác sẽ biểu diễn một tiết mục, anh cũng tham gia chứ?"},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"李文","name":"Lý Văn","zh":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","py":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.","vi":"Anh muốn hát bài hát Trung Quốc, nhưng vẫn chưa tìm được ai biểu diễn cùng, không biết phải làm sao nữa."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"找不到人，你就一个人唱吧。","py":"Zhǎo bu dào rén, nǐ jiù yí gè rén chàng ba.","vi":"Không tìm được ai thì anh cứ hát một mình đi."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"李文","name":"Lý Văn","zh":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","py":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.","vi":"Chỉ nghĩ đến việc phải biểu diễn trước mặt hiệu trưởng, các thầy cô giáo và bao nhiêu bạn là anh đã thấy hơi căng thẳng rồi."},{"section":"Bài khóa 3","context":"","audio":"14-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","py":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","vi":"Có gì mà phải căng thẳng chứ, tụi em đều thích nghe anh hát mà, anh phải tin tưởng vào bản thân mình."},{"section":"Bài khóa 4","context":"在家里，白家月在写日记。Bạch Gia Nguyệt đang viết nhật ký ở trong nhà.","audio":"14-7.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。晚会是八点开始的，差不多十二点才结束。我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。过几天学校的网站上会有晚会的视频，我打算再看一遍。","py":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi gè bānjí de tóngxué dōu biǎoyǎn jiémù le. Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí\u0027èr diǎn cái jiéshù. Wǒ yí gè wǎnshang gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jíle, yě lèi huài le. Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒuyìsi. Guò jǐ tiān xuéxiào de wǎngzhàn shang huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn.","vi":"Hôm qua là buổi dạ hội năm mới của trường chúng tôi, học sinh các khối lớp đều tham gia biểu diễn tiết mục. Buổi dạ hội bắt đầu lúc 8 giờ tối, mãi đến gần 12 giờ đêm mới kết thúc. Cả buổi tối, tôi đã vừa hát, vừa nhảy cùng mọi người, vui cực kì mà cũng rất mệt. Tiết mục mà tôi thích nhất là tiết mục nhảy của lưu học sinh, cuối chương trình, hiệu trưởng và giáo viên cũng được mời lên nhảy cùng, đặc biệt thú vị. Vài ngày tới, các video sẽ được tải lên trang web của trường, tôi định sẽ xem lại chúng một lần nữa."}],"dialogQuestions":[],"grammar":{"g1":{"han":"被动句（1）","py":"Bèidòngjù (1)","title":"Câu bị động (1)","explain":"汉语中用带“被”字的句子表达被动意义，突出主语受到了某个动作的影响，语气常带有被动、无奈、负面等色彩。副词和能愿动词放在“被”字前面，“被”字后面的宾语可以省略。基本结构：主语+被+宾语+动词+其他成分。\nTrong tiếng Trung Quốc, câu sử dụng “被” dùng để diễn đạt nghĩa bị động, nhấn mạnh chủ ngữ bị ảnh hưởng bởi hành động nào đó, ngữ khí thường mang sắc thái bị động, bất lực hoặc tiêu cực... Phó từ và động từ năng nguyện đặt trước “被”, tân ngữ sau “被” có thể được lược bỏ.","examples":[{"zh":"这本书被别人借走了。","py":"Zhè běn shū bèi biérén jièzǒu le.","vi":"Quyển sách này bị người khác mượn mất rồi.","hl":"被别人借走了"},{"zh":"水果可能被弟弟吃了。","py":"Shuǐguǒ kěnéng bèi dìdi chī le.","vi":"Hoa quả có thể bị em trai ăn mất rồi.","hl":"被弟弟吃了"},{"zh":"我们俩经常被叫错名字。","py":"Wǒmen liǎ jīngcháng bèi jiào cuò míngzi.","vi":"Hai đứa chúng tôi thường xuyên bị gọi nhầm tên.","hl":"被叫错名字"}],"struct":"Chủ ngữ (đối tượng chịu tác động) + (Phó từ/Động từ năng nguyện) + 被 (+ Tác nhân) + Động từ + Thành phần khác","note":"Trong câu chữ “被”, động từ không đứng trơ trọi mà thường kèm theo bổ ngữ, “了”, “过” hoặc thành phần khác."},"g2":{"han":"承接复句“先……，再/然后……”","py":"Chéngjiē fùjù “xiān..., zài/ránhòu...”","title":"Câu ghép tiếp nối “先……，再/然后……”","explain":"承接复句“先……，再/然后……”中，两个分句表示动作的先后顺序。\nTrong câu ghép tiếp nối “先……，再/然后……”, hai mệnh đề biểu thị thứ tự trước sau của hành động.","examples":[{"zh":"我要先去图书馆借书，然后去游泳。","py":"Wǒ yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","vi":"Mình phải đến thư viện mượn sách trước, sau đó đi bơi.","hl":"先……，然后……"},{"zh":"你先去买门票，再来这里找我。","py":"Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.","vi":"Bạn đi mua vé vào cửa trước, rồi hãy tới đây tìm mình.","hl":"先……，再……"},{"zh":"你们先回房间休息一会儿，然后再出来吃晚饭。","py":"Nǐmen xiān huí fángjiān xiūxi yíhuìr, ránhòu zài chūlái chī wǎnfàn.","vi":"Các bạn về phòng nghỉ một lát trước đi, rồi hãy ra ngoài ăn cơm tối.","hl":"先……，然后再……"}],"struct":"(Chủ ngữ +) 先 + Hành động 1，(Chủ ngữ +) 再/然后 + Hành động 2","note":"“再” thường dùng cho việc chưa xảy ra; “然后” dùng được cho cả quá khứ lẫn tương lai."},"g3":{"han":"固定格式“×什么（啊）”","py":"Gùdìng géshì “× shénme (a)”","title":"Cấu trúc cố định “×什么（啊）”","explain":"固定格式“×什么（啊）”通常用于否定对方的担忧、疑问或强调事实，带有反驳或安慰的语气。\nCấu trúc cố định “×什么（啊）” dùng để phủ định sự lo lắng, hoài nghi của đối phương hoặc nhấn mạnh sự thật, mang ngữ khí phản bác hoặc an ủi.","examples":[{"zh":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","py":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","vi":"Căng thẳng gì chứ, bọn em đều thích nghe anh hát mà, anh phải tin vào bản thân mình.","hl":"紧张什么啊"},{"zh":"胖什么啊，你看起来不胖也不瘦。","py":"Pàng shénme a, nǐ kàn qǐlái bú pàng yě bú shòu.","vi":"Béo gì mà béo, trông bạn vừa vặn chẳng béo chẳng gầy.","hl":"胖什么啊"},{"zh":"急什么啊，马上就到了。","py":"Jí shénme a, mǎshàng jiù dào le.","vi":"Vội gì chứ, sắp đến nơi rồi.","hl":"急什么啊"}],"struct":"Động từ / Tính từ + 什么（啊）","note":"Là cách nói khẩu ngữ thân mật nhằm gạt bỏ sự lo ngại hay thắc mắc của người nghe."}},"grammarQuiz":[{"id":"hsk3_b14_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你今天看起来 (____) 难过，遇到什么问题了？","opts":[{"t":"有些","ok":true},{"t":"故事","ok":false},{"t":"最好","ok":false},{"t":"一块儿","ok":false},{"t":"表演","ok":false}],"exp":"Đáp án C (有些): ‘Hôm nay trông bạn hơi buồn, gặp vấn đề gì vậy?’"},{"id":"hsk3_b14_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"图书馆的这本书我已经看完了，我很喜欢这个 (____)。","opts":[{"t":"故事","ok":true},{"t":"最好","ok":false},{"t":"有些","ok":false},{"t":"一块儿","ok":false},{"t":"表演","ok":false}],"exp":"Đáp án A (故事): ‘Cuốn sách này của thư viện mình đọc xong rồi, mình rất thích câu chuyện này.’"},{"id":"hsk3_b14_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她读不懂中文报纸，你 (____) 把那个新闻给她讲一下。","opts":[{"t":"最好","ok":true},{"t":"故事","ok":false},{"t":"有些","ok":false},{"t":"一块儿","ok":false},{"t":"表演","ok":false}],"exp":"Đáp án B (最好): ‘Cô ấy đọc không hiểu báo tiếng Trung, tốt nhất là bạn giảng lại tin đó cho cô ấy.’"},{"id":"hsk3_b14_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"网站上已经可以看到晚会的视频了，咱们 (____) 看吧。","opts":[{"t":"一块儿","ok":true},{"t":"故事","ok":false},{"t":"最好","ok":false},{"t":"有些","ok":false},{"t":"表演","ok":false}],"exp":"Đáp án D (一块儿): ‘Trên trang web đã xem được video buổi dạ hội rồi, chúng ta cùng nhau xem nhé.’"},{"id":"hsk3_b14_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她学过 (____)，可以跟你们一起准备这个节目。","opts":[{"t":"表演","ok":true},{"t":"故事","ok":false},{"t":"最好","ok":false},{"t":"有些","ok":false},{"t":"一块儿","ok":false}],"exp":"Đáp án E (表演): ‘Cô ấy từng học biểu diễn, có thể cùng các bạn chuẩn bị tiết mục này.’"},{"id":"hsk3_b14_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你要 (____) 自己，这次一定能比上次更好！\nB: 谢谢你，我会努力的。","opts":[{"t":"相信","ok":true},{"t":"最后","ok":false},{"t":"面前","ok":false},{"t":"留学生","ok":false},{"t":"忘记","ok":false}],"exp":"Đáp án C (相信): ‘Bạn phải tin vào bản thân mình, lần này nhất định sẽ tốt hơn lần trước!’"},{"id":"hsk3_b14_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我刚才想说什么？突然就 (____) 了。\nB: 你再想想，我们刚才在说运动会的事情。","opts":[{"t":"忘记","ok":true},{"t":"最后","ok":false},{"t":"面前","ok":false},{"t":"相信","ok":false},{"t":"留学生","ok":false}],"exp":"Đáp án E (忘记): ‘Vừa nãy mình định nói gì nhỉ? Tự dưng lại quên mất tiêu rồi.’"},{"id":"hsk3_b14_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你们学校的 (____) 多吗？\nB: 越来越多，今年有三千多人。","opts":[{"t":"留学生","ok":true},{"t":"最后","ok":false},{"t":"面前","ok":false},{"t":"相信","ok":false},{"t":"忘记","ok":false}],"exp":"Đáp án D (留学生): ‘Lưu học sinh của trường các bạn có đông không?’"},{"id":"hsk3_b14_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你唱歌唱得那么好听，为什么没参加昨天的晚会？\nB: 我不喜欢在很多人 (____) 表演。","opts":[{"t":"面前","ok":true},{"t":"最后","ok":false},{"t":"相信","ok":false},{"t":"留学生","ok":false},{"t":"忘记","ok":false}],"exp":"Đáp án B (面前): ‘Mình không thích biểu diễn trước mặt nhiều người.’"},{"id":"hsk3_b14_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这次考试你考得怎么样？\nB: 我已经很努力了，希望 (____) 的成绩能好一些！","opts":[{"t":"最后","ok":true},{"t":"面前","ok":false},{"t":"相信","ok":false},{"t":"留学生","ok":false},{"t":"忘记","ok":false}],"exp":"Đáp án A (最后): ‘Mình đã rất cố gắng rồi, hy vọng kết quả cuối cùng sẽ khả quan hơn!’"},{"id":"hsk3_b14_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月下午要帮李文做什么？","opts":[{"t":"B 还词典","ok":true},{"t":"A 借词典","ok":false},{"t":"C 找一本书","ok":false}],"exp":"Lý Văn nhờ Bạch Gia Nguyệt đi trả quyển từ điển mượn từ thư viện giúp anh."},{"id":"hsk3_b14_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月是怎么知道《名人的故事》这本书的？","opts":[{"t":"A 她有一本","ok":true},{"t":"B 她听说过","ok":false},{"t":"C 她在图书馆借过","ok":false}],"exp":"Bạch Gia Nguyệt nói: “《名人的故事》？我有这本书。明天我借给你吧。”"},{"id":"hsk3_b14_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"下课以后白家月要做什么？","opts":[{"t":"A 去图书馆","ok":true},{"t":"B 找校园卡","ok":false},{"t":"C 跟陈天中去游泳","ok":false}],"exp":"Bạch Gia Nguyệt nói cô phải đi thư viện trước (mượn sách và trả sách giúp Lý Văn), sau đó mới đi bơi."},{"id":"hsk3_b14_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"安妮觉得进不去图书馆可以怎么做？","opts":[{"t":"B 上网借电子书","ok":true},{"t":"A 找李文借书","ok":false},{"t":"C 借朋友的校园卡","ok":false}],"exp":"Annie gợi ý: “进不去图书馆也没关系，上网看看有没有电子书。”"},{"id":"hsk3_b14_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"李文和白家月在说什么？","opts":[{"t":"A 学校的晚会","ok":true},{"t":"B 学唱中文歌","ok":false},{"t":"C 参加唱歌比赛","ok":false}],"exp":"Lý Văn mở đầu: “下周学校有晚会，你知道吗？”"},{"id":"hsk3_b14_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"李文想怎么表演节目？","opts":[{"t":"C 找人一起表演","ok":true},{"t":"A 自己跳舞","ok":false},{"t":"B 一个人唱歌","ok":false}],"exp":"Lý Văn nói: “我想唱中文歌，但是还没找到人一起表演...”"},{"id":"hsk3_b14_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"昨天的晚会谁表演节目了？","opts":[{"t":"C 每个班级的同学","ok":true},{"t":"A 校长","ok":false},{"t":"B 一些老师","ok":false}],"exp":"Bài khóa 4: “每个班级的同学都表演节目了。”"},{"id":"hsk3_b14_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"白家月为什么累坏了？","opts":[{"t":"A 又唱又跳","ok":true},{"t":"B 给同学们拍照","ok":false},{"t":"C 表演了很多节目","ok":false}],"exp":"Bài khóa 4: “我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。”"}],"chars":["词","典","最","好","节","图","书","馆","被","名","人","故","事","然","后","报","纸","忘","记","电","子","女","生","表","演","目","怎","么","办","校","长","面","前","有","些","相","信","新","年","班","级","跳","留","学","一","块","儿","网","站","视","频","这","本","别","借","走","了"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 李文请白家月帮他借什么书？ (2) 李文为什么没借到这本书？ (3) 李文把书名写在哪儿了？","Câu hỏi thảo luận Bài khóa 2: (1) 下课以后安妮要做什么？ (2) 白家月为什么不能进图书馆？ (3) 白家月觉得校园卡可能在哪儿？","Câu hỏi thảo luận Bài khóa 3: (1) 白家月要在晚会上做什么？ (2) 李文为什么紧张？ (3) 听说李文有点儿紧张，白家月是怎么说的？","Câu hỏi thảo luận Bài khóa 4: (1) 晚会是什么时候开始的？什么时候结束的？ (2) 白家月最喜欢哪个节目？为什么？ (3) 过几天白家月打算做什么？"],"workbook":null},"15":{"pages":"133–143","titleZh":"我是半个南京人","titlePy":"Wǒ shì bàn gè Nánjīngrén","titleVi":"Em cũng là một nửa người Nam Kinh","goals":["能听懂并描述某地的位置和环境信息。Có thể nghe hiểu và miêu tả được vị trí và môi trường của một địa phương.","能听懂并介绍某地的自然景观或历史文化。Có thể nghe hiểu và giới thiệu được cảnh quan thiên nhiên, lịch sử hoặc văn hoá của một địa phương.","掌握“在……看来”短语，能表达个人或某个群体的观点。Nắm vững cách dùng cấu trúc “在……看来”, có thể diễn đạt quan điểm cá nhân hoặc tập thể.","了解南京和黄河的基本情况。Hiểu về những thông tin cơ bản về Nam Kinh và sông Hoàng Hà."],"words":[{"zh":"蓝","py":"lán","vi":"màu xanh lam, xanh dương","pos":"tt."},{"zh":"段","py":"duàn","vi":"đoạn, quãng (thời gian, không gian)","pos":"lượng."},{"zh":"附近","py":"fùjìn","vi":"gần đó, lân cận","pos":"dt."},{"zh":"马路","py":"mǎlù","vi":"đường chính, đường cái","pos":"dt."},{"zh":"平时","py":"píngshí","vi":"thường ngày","pos":"dt."},{"zh":"放学","py":"fàngxué","vi":"tan học","pos":"đgt."},{"zh":"游戏","py":"yóuxì","vi":"trò chơi","pos":"dt."},{"zh":"老人","py":"lǎorén","vi":"người già","pos":"dt."},{"zh":"根据","py":"gēnjù","vi":"căn cứ vào, dựa vào","pos":"giới./đgt."},{"zh":"了解","py":"liǎojiě","vi":"hiểu, hiểu rõ, tìm hiểu","pos":"đgt."},{"zh":"可是","py":"kěshì","vi":"nhưng, tuy nhiên","pos":"liên."},{"zh":"以上","py":"yǐshàng","vi":"trở lên, trên","pos":"dt."},{"zh":"有名","py":"yǒumíng","vi":"nổi tiếng, có tiếng","pos":"tt."},{"zh":"景点","py":"jǐngdiǎn","vi":"cảnh điểm, điểm du lịch","pos":"dt."},{"zh":"游客","py":"yóukè","vi":"du khách","pos":"dt."},{"zh":"外地","py":"wàidì","vi":"nơi khác, vùng khác, địa phương khác","pos":"dt."},{"zh":"聊","py":"liáo","vi":"trò chuyện, nói chuyện","pos":"đgt."},{"zh":"南京","py":"Nánjīng","vi":"Nam Kinh (thủ phủ của tỉnh Giang Tô, Trung Quốc)","pos":"dt. riêng"},{"zh":"河","py":"hé","vi":"sông","pos":"dt."},{"zh":"关系","py":"guānxi","vi":"quan hệ","pos":"dt."},{"zh":"养","py":"yǎng","vi":"nuôi dưỡng","pos":"đgt."},{"zh":"黄河","py":"Huáng Hé","vi":"sông Hoàng Hà","pos":"dt. riêng"},{"zh":"西北","py":"xīběi","vi":"tây bắc","pos":"dt."},{"zh":"经过","py":"jīngguò","vi":"đi qua, trải qua, trải nghiệm","pos":"đgt./dt."},{"zh":"草地","py":"cǎodì","vi":"thảm cỏ, đồng cỏ","pos":"dt."},{"zh":"遇见","py":"yùjiàn","vi":"gặp, tình cờ gặp","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在办公室里，王一雪和杨同乐在聊天儿。Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong văn phòng.","audio":"15-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您搬到蓝天小区一段时间了，觉得怎么样？","py":"Nín bāndào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?","vi":"Chị đã chuyển đến khu dân cư Lam Thiên được một thời gian rồi, chị thấy ở đó thế nào?"},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","py":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiùshì chāoshì.","vi":"Môi trường xung quanh khá tốt, mua sắm cũng rất tiện lợi, qua đường là có ngay một cái siêu thị."},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"平时孩子们在哪儿玩？","py":"Píngshí háizimen zài nǎr wán?","vi":"Bọn trẻ thường chơi ở đâu vậy chị?"},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","py":"Xiǎoqū li yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?","vi":"Trong khu dân cư có rất nhiều cây xanh, nên sau giờ học, lũ trẻ thường chơi trò chơi dưới gốc cây. Em muốn mua nhà à?"},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"是。我想买一个大房子，让我爸妈过来跟我一起住。","py":"Shì. Wǒ xiǎng mǎi yí gè dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù.","vi":"Vâng, em muốn mua một căn nhà lớn chút để đón bố mẹ qua ở cùng em."},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","py":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒule hěn duō biànhuà.","vi":"Trong khu dân cư Lam Thiên có rất nhiều người lớn tuổi, mấy năm gần đây khu vực này đã thực hiện nhiều thay đổi để phù hợp với nhu cầu của họ."},{"section":"Bài khóa 1","context":"","audio":"15-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"真不错！过几天我去蓝天小区看看。","py":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan.","vi":"Thật tuyệt! Vài ngày nữa em sẽ đến khu dân cư Lam Thiên xem thử."},{"section":"Bài khóa 2","context":"在办公室里，王一雪和杨同乐在聊天儿。Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện trong văn phòng.","audio":"15-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"假期我想去南京旅游，但是我不太了解那里。","py":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàlǐ.","vi":"Kì nghỉ này chị muốn đi Nam Kinh du lịch, nhưng chị không biết nhiều về nơi đó."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","py":"Wǒ suīrán bú shì Nánjīngrén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn gè Nánjīngrén.","vi":"Mặc dù em không phải người Nam Kinh, nhưng em đã học đại học ở đó, có thể coi là một nửa người Nam Kinh."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"太好了！你快给我介绍一下南京吧。","py":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","vi":"Tốt quá! Em kể thêm cho chị nghe về Nam Kinh đi."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","py":"Nánjīng yǒu liǎng qiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měinián qù lǚyóu de yóukè tèbié duō.","vi":"Nam Kinh có lịch sử hơn 2000 năm, có thành cổ, phố cổ và rất nhiều địa danh nổi tiếng, hàng năm có rất nhiều du khách đến đây du lịch."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"除了这些以外，你再告诉我一些外地人不知道的地方。","py":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidìrén bù zhīdào de dìfang.","vi":"Ngoài những điểm du lịch trên, em nói cho chị thêm một vài nơi mà người nơi khác không biết đi."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"那太多了，我得一点儿一点儿给您讲。","py":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vi":"Vậy thì nhiều lắm, cái này em phải kể từng chút một cho chị."},{"section":"Bài khóa 2","context":"","audio":"15-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"行，下班后我请你吃晚饭，咱们边吃边聊。","py":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo.","vi":"Được nhé. Sau giờ làm chị sẽ mời em ăn tối, chúng ta có thể vừa ăn vừa trò chuyện nhé."},{"section":"Bài khóa 3","context":"在家里，王一雪和刘小明在聊天儿。Vương Nhất Tuyết và Lưu Tiểu Minh đang trò chuyện ở trong nhà.","audio":"15-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","py":"Xiǎomíng, Zhōngguó yǒu yì tiáo dà hé, tā de míngzi gēn yánsè yǒu guānxi, nǐ zhīdào shì shénme hé ma?","vi":"Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc. Con có biết đó là con sông nào không?"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"我知道，是黄河！","py":"Wǒ zhīdào, shì Huáng Hé!","vi":"Con biết ạ, là sông Hoàng Hà!"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你说对了。我再问问你，你知道它为什么叫黄河吗？","py":"Nǐ shuō duì le. Wǒ zài wènwen nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?","vi":"Con nói đúng rồi đó. Mẹ lại hỏi con một câu hỏi khác: Con có biết tại sao nó được gọi là sông Hoàng Hà không?"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","py":"Yīnwèi héshuǐ kàn qǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?","vi":"Tại vì nước sông trông có màu vàng nên được gọi cái tên này. Hoàng Hà có phải là con sông dài nhất Trung Quốc không mẹ?"},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"不是。黄河虽然不是最长的河，可是在历史上很重要。","py":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de hé, kěshì zài lìshǐ shang hěn zhòngyào.","vi":"Không, tuy sông Hoàng Hà không phải là con sông dài nhất, nhưng nó cực kỳ quan trọng về mặt lịch sử."},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"这个我知道。很久以前，很多中国人都住在黄河边上。","py":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biān shang.","vi":"Cái này con biết ạ! Từ ngày xửa ngày xưa, rất nhiều người Trung Quốc đã sống dọc theo sông Hoàng Hà."},{"section":"Bài khóa 3","context":"","audio":"15-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","py":"Duì. Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎngle wǒmen jǐ qiān nián.","vi":"Đúng rồi. Đối với người Trung Quốc chúng ta, sông Hoàng Hà giống như một người mẹ hiền, đã nuôi dưỡng chúng ta suốt hàng nghìn năm qua."},{"section":"Bài khóa 4","context":"在家里，王一雪在写日记。Vương Nhất Tuyết đang ngồi viết nhật ký ở trong nhà.","audio":"15-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我小时候住在北京的西北边，有一条非常有名的河经过那里。我家就住在河边。那里有高高的大树和绿绿的草地。春天，河边的花都开了，看起来特别漂亮。还记得小时候，一到夏天我就去河里游泳。长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。那是我最喜欢的地方。","py":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběibiān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàlǐ. Wǒ jiā jiù zhù zài hébiān. Nàlǐ yǒu gāogāo de dàshù hé lǜlǜ de cǎodì. Chūntiān, hébiān de huā dōu kāi le, kàn qǐlái tèbié piàoliang. Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé li yóuyǒng. Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuòzhe, tīngting niǎo jiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáo liaotiānr, nánguò de shìqing bù yíhuìr jiù wàng le. Nà shì wǒ zuì xǐhuan de dìfang.","vi":"Khi còn nhỏ, tôi sống ở vùng tây bắc của Bắc Kinh, nơi có một con sông rất nổi tiếng chảy qua. Nhà tôi ở ngay cạnh dòng sông. Ở đó có những hàng cây cao và thảm cỏ xanh mướt. Mùa xuân, hoa dọc theo bờ sông sẽ nở rộ, nhìn trông vô cùng đẹp. Tôi vẫn nhớ thuở còn bé, cứ khi hè tới tôi đều đi bơi ở dòng sông đó. Khi lớn lên, mỗi khi gặp phải những chuyện không vui, tôi thường tới ngồi dưới những tán cây bên bờ sông, lắng nghe tiếng chim hót, ngắm nhìn dòng nước chảy và trò chuyện với những người bạn tôi gặp ở đó, nỗi buồn của tôi sẽ tan biến trong nháy mắt. Đó là nơi mà tôi yêu thích nhất."}],"dialogQuestions":[],"grammar":{"g1":{"han":"介词“根据”","py":"Jiècí “gēnjù”","title":"Giới từ “根据”","explain":"介词“根据”在句子中引出事情的依据或理由。\nGiới từ “根据” dùng để dẫn ra căn cứ hoặc lý do của một hành động trong câu.","examples":[{"zh":"这几年小区根据他们的需要，有了很多变化。","py":"Zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒule hěn duō biànhuà.","vi":"Mấy năm nay khu dân cư đã có nhiều thay đổi căn cứ theo nhu cầu của họ.","hl":"根据"},{"zh":"根据要求，我们必须参加明天的会议。","py":"Gēnjù yāoqiú, wǒmen bìxū cānjiā míngtiān de huìyì.","vi":"Theo yêu cầu, chúng tôi bắt buộc phải tham gia cuộc họp ngày mai.","hl":"根据"},{"zh":"老师根据每个学生的兴趣，选择了不一样的书。","py":"Lǎoshī gēnjù měi gè xuésheng de xìngqù, xuǎnzéle bù yíyàng de shū.","vi":"Giáo viên dựa theo sở thích của từng học sinh để chọn những quyển sách khác nhau.","hl":"根据"}],"struct":"根据 + Danh từ / Cụm danh từ，+ Kết quả / Hành động","note":"Có thể đứng đầu câu hoặc sau chủ ngữ làm trạng ngữ chỉ căn cứ."},"g2":{"han":"数量重叠“数词+量词+数词+量词”","py":"Shùliàng chóngdié “shùcí + liàngcí + shùcí + liàngcí”","title":"Cụm từ chỉ số lượng lặp lại “số từ + lượng từ + số từ + lượng từ”","explain":"数量短语可以重叠，重叠后可作状语，一般表示动作的方式，有形象化的作用。基本结构：数词+量词+数词+量词+（地）+动词。\nCụm từ chỉ số lượng có thể lặp lại, làm trạng ngữ, thường dùng để chỉ phương thức của hành động, có tác dụng hình tượng hoá. Cấu trúc cơ bản: số từ + lượng từ + số từ + lượng từ + (地) + động từ.","examples":[{"zh":"我得一点儿一点儿给您讲。","py":"Wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","vi":"Em phải kể từng chút từng chút một cho chị nghe.","hl":"一点儿一点儿"},{"zh":"学生们的汉语水平一天一天地提高了。","py":"Xuéshengmen de Hànyǔ shuǐpíng yì tiān yì tiān de tígāo le.","vi":"Trình độ tiếng Hán của các học sinh đã nâng cao từng ngày một.","hl":"一天一天地"},{"zh":"他们两个两个地走进去了。","py":"Tāmen liǎng gè liǎng gè de zǒu jìnqù le.","vi":"Họ đi vào theo từng cặp hai người một.","hl":"两个两个地"}],"struct":"Số từ + Lượng từ + Số từ + Lượng từ (+ 地) + Động từ","note":"Diễn tả sự tuần tự, đều đặn từng đơn vị một (一天一天, 一页一页, 一件一件, 一个一个)."},"g3":{"han":"固定短语“在……看来”","py":"Gùdìng duǎnyǔ “zài... kànlái”","title":"Cấu trúc cố định “在……看来”","explain":"固定短语“在……看来”表示个人或某个群体的观点。\nCấu trúc cố định “在……看来” dùng để biểu thị quan điểm của cá nhân hoặc tập thể.","examples":[{"zh":"在我们中国人看来，黄河像妈妈一样，养了我们几千年。","py":"Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎngle wǒmen jǐ qiān nián.","vi":"Theo cách nhìn của người Trung Quốc chúng ta, sông Hoàng Hà giống như người mẹ đã nuôi dưỡng chúng ta hàng nghìn năm.","hl":"在我们中国人看来"},{"zh":"在同事们看来，她工作非常认真。","py":"Zài tóngshìmen kànlái, tā gōngzuò fēicháng rènzhēn.","vi":"Trong mắt các đồng nghiệp, cô ấy làm việc rất nghiêm túc.","hl":"在同事们看来"},{"zh":"在我看来，每天读书是一种很好的习惯。","py":"Zài wǒ kànlái, měitiān dúshū shì yì zhǒng hěn hǎo de xíguàn.","vi":"Theo quan điểm của tôi, đọc sách mỗi ngày là một thói quen rất tốt.","hl":"在我看来"}],"struct":"在 + Đại từ / Danh từ chỉ người + 看来，+ Quan điểm","note":"Ý nghĩa tương tự “theo tôi thấy / dưới góc nhìn của...”."},"g4":{"han":"固定短语“不一会儿”","py":"Gùdìng duǎnyǔ “bù yíhuìr”","title":"Cụm từ cố định “不一会儿”","explain":"固定短语“不一会儿”表示很短的时间，在句中作状语，多用于口语。\nCụm từ cố định “不一会儿” thường dùng trong văn nói, làm trạng ngữ trong câu, biểu thị thời gian rất ngắn.","examples":[{"zh":"难过的事情不一会儿就忘了。","py":"Nánguò de shìqing bù yíhuìr jiù wàng le.","vi":"Chuyện buồn không bao lâu là quên ngay thôi.","hl":"不一会儿"},{"zh":"不一会儿，张校长就来了。","py":"Bù yíhuìr, Zhāng xiàozhǎng jiù lái le.","vi":"Chẳng mấy chốc, hiệu trưởng Trương đã tới rồi.","hl":"不一会儿"},{"zh":"两个小时看起来长，但是不一会儿就过去了。","py":"Liǎng gè xiǎoshí kàn qǐlái cháng, dànshì bù yíhuìr jiù guòqù le.","vi":"Hai tiếng đồng hồ nghe thì lâu, nhưng chớp mắt là trôi qua ngay.","hl":"不一会儿"}],"struct":"不一会儿（，）+ Chủ ngữ + 就 + Động từ","note":"Có thể đứng đầu câu hoặc sau chủ ngữ, thường đi kèm phó từ “就”."}},"grammarQuiz":[{"id":"hsk3_b15_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我爷爷喜欢 (____) 花，他家有很多漂亮的花。","opts":[{"t":"养","ok":true},{"t":"段","ok":false},{"t":"外地","ok":false},{"t":"遇见","ok":false},{"t":"有名","ok":false}],"exp":"Đáp án B (养): ‘Ông nội tôi thích trồng hoa, nhà ông có rất nhiều hoa đẹp.’"},{"id":"hsk3_b15_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"昨天我在公园 (____) 了一位老朋友，聊了很久。","opts":[{"t":"遇见","ok":true},{"t":"段","ok":false},{"t":"养","ok":false},{"t":"外地","ok":false},{"t":"有名","ok":false}],"exp":"Đáp án D (遇见): ‘Hôm qua tôi tình cờ gặp một người bạn cũ ở công viên, nói chuyện rất lâu.’"},{"id":"hsk3_b15_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他是从 (____) 来的，还不太习惯这里的天气。","opts":[{"t":"外地","ok":true},{"t":"段","ok":false},{"t":"养","ok":false},{"t":"遇见","ok":false},{"t":"有名","ok":false}],"exp":"Đáp án C (外地): ‘Anh ấy từ địa phương khác tới, vẫn chưa quen lắm với thời tiết ở đây.’"},{"id":"hsk3_b15_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这家饭馆在我们城市很 (____)，很多人都来这里吃饭。","opts":[{"t":"有名","ok":true},{"t":"段","ok":false},{"t":"养","ok":false},{"t":"外地","ok":false},{"t":"遇见","ok":false}],"exp":"Đáp án E (有名): ‘Nhà hàng này rất nổi tiếng ở thành phố chúng tôi, nhiều người đều tới đây ăn.’"},{"id":"hsk3_b15_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这本书我已经看了一 (____) 时间了，越看越觉得有意思。","opts":[{"t":"段","ok":true},{"t":"养","ok":false},{"t":"外地","ok":false},{"t":"遇见","ok":false},{"t":"有名","ok":false}],"exp":"Đáp án A (段): ‘Quyển sách này tôi đã đọc được một khoảng thời gian rồi, càng đọc càng thấy hay.’"},{"id":"hsk3_b15_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这家饭馆很有名，咱们去尝尝吧！\nB: 今天是假期，人一定很多，(____) 人少的时候再去吧。","opts":[{"t":"平时","ok":true},{"t":"了解","ok":false},{"t":"经过","ok":false},{"t":"可是","ok":false},{"t":"根据","ok":false}],"exp":"Đáp án E (平时): ‘Hôm nay là ngày nghỉ chắc đông người lắm, đợi ngày thường ít người hãy đi nhé.’"},{"id":"hsk3_b15_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 公园有两个门，咱们进哪个门？\nB: 进东门吧，进去以后会 (____) 一条很漂亮的小河。","opts":[{"t":"经过","ok":true},{"t":"了解","ok":false},{"t":"可是","ok":false},{"t":"根据","ok":false},{"t":"平时","ok":false}],"exp":"Đáp án B (经过): ‘Vào cổng đông đi, vào rồi sẽ đi qua một con sông nhỏ rất đẹp.’"},{"id":"hsk3_b15_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我早就想去南京旅游了，(____) 一直没时间去。\nB: 有机会咱们一起去吧。","opts":[{"t":"可是","ok":true},{"t":"了解","ok":false},{"t":"经过","ok":false},{"t":"根据","ok":false},{"t":"平时","ok":false}],"exp":"Đáp án C (可是): ‘Mình muốn đi du lịch Nam Kinh từ lâu rồi, nhưng mãi vẫn chưa có thời gian đi.’"},{"id":"hsk3_b15_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我选什么课好呢？\nB: 你可以 (____) 自己的兴趣来选择。","opts":[{"t":"根据","ok":true},{"t":"了解","ok":false},{"t":"经过","ok":false},{"t":"可是","ok":false},{"t":"平时","ok":false}],"exp":"Đáp án D (根据): ‘Bạn có thể căn cứ vào sở thích của bản thân để lựa chọn.’"},{"id":"hsk3_b15_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你对这座城市 (____) 多少？\nB: 我只知道这里有很多好吃的，别的还不太清楚。","opts":[{"t":"了解","ok":true},{"t":"经过","ok":false},{"t":"可是","ok":false},{"t":"根据","ok":false},{"t":"平时","ok":false}],"exp":"Đáp án A (了解): ‘Bạn hiểu biết bao nhiêu về thành phố này?’"},{"id":"hsk3_b15_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"杨同乐和王一雪在说什么？","opts":[{"t":"C 蓝天小区怎么样","ok":true},{"t":"A 小区里的老人","ok":false},{"t":"B 小区里的孩子","ok":false}],"exp":"Dương Đồng Lạc hỏi thăm môi trường sống, tiện ích ở khu dân cư Lam Thiên."},{"id":"hsk3_b15_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"杨同乐为什么对蓝天小区感兴趣？","opts":[{"t":"B 他想买房子","ok":true},{"t":"A 他想搬家","ok":false},{"t":"C 他想跟王一雪做邻居","ok":false}],"exp":"Dương Đồng Lạc nói: “我想买一个大房子，让我爸妈过来跟我一起住。”"},{"id":"hsk3_b15_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪和杨同乐在聊什么？","opts":[{"t":"A 在南京旅游","ok":true},{"t":"B 下班后吃什么","ok":false},{"t":"C 杨同乐的大学","ok":false}],"exp":"Vương Nhất Tuyết mở đầu: “假期我想去南京旅游，但是我不太了解那里。”"},{"id":"hsk3_b15_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"南京是一个什么样的城市？","opts":[{"t":"A 有很多游客去旅游","ok":true},{"t":"B 有一千年以上的历史","ok":false},{"t":"C 有很多南京人不知道的景点","ok":false}],"exp":"Dương Đồng Lạc nói Nam Kinh có lịch sử hơn 2000 năm (nên B sai) và hàng năm có rất nhiều du khách đến du lịch (đáp án A)."},{"id":"hsk3_b15_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪和小明在聊什么？","opts":[{"t":"B 黄河的历史","ok":true},{"t":"A 最长的河","ok":false},{"t":"C 学校的作业","ok":false}],"exp":"Hai mẹ con trò chuyện về tên gọi và vai trò quan trọng trong lịch sử của sông Hoàng Hà."},{"id":"hsk3_b15_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘小明对黄河了解多少？","opts":[{"t":"B 了解一些","ok":true},{"t":"A 一点儿都不了解","ok":false},{"t":"C 什么都知道","ok":false}],"exp":"Tiểu Minh biết sông Hoàng Hà và lý do có tên đó, cũng biết người xưa sống ven sông, nhưng chưa biết đây có phải con sông dài nhất không."},{"id":"hsk3_b15_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪小时候住的地方是什么样的？","opts":[{"t":"A 她家住在河边","ok":true},{"t":"B 她家在北京的南边","ok":false},{"t":"C 离她家很远的地方有一条河","ok":false}],"exp":"Bài khóa 4: “我小时候住在北京的西北边... 我家就住在河边。”"},{"id":"hsk3_b15_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"遇到不开心的事情，王一雪怎么办？","opts":[{"t":"B 去河边坐着","ok":true},{"t":"A 去河里游泳","ok":false},{"t":"C 一个人在家","ok":false}],"exp":"Bài khóa 4: “遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水...”"}],"chars":["蓝","段","附","近","马","路","平","时","放","学","游","戏","老","人","根","据","了","解","可","是","以","上","有","名","景","点","客","外","地","聊","南","京","河","关","系","养","黄","西","北","经","过","草","遇","见","我","半","个"],"rhyme":null,"notes":["Món quà của Tiểu Ngữ (trang 142, video 15-1): 长江与黄河 — Sông Trường Giang và sông Hoàng Hà.","Tổng kết học tập Bài 13–15 (trang 142–143): 10 điểm ngữ pháp gồm ……的话，就……, “把”字句(4), 一边……，一边……, 被动句(1), 先……，再/然后……, ×什么（啊）, 介词“根据”, 数量重叠“数词+量词+数词+量词”, 在……看来 và 不一会儿.","Câu hỏi thảo luận Bài khóa 1: (1) 蓝天小区附近买东西方便吗？ (2) 蓝天小区的孩子们放学后都在哪里玩？ (3) 蓝天小区为老人做了什么？","Câu hỏi thảo luận Bài khóa 2: (1) 王一雪了解南京吗？ (2) 杨同乐为什么了解南京？ (3) 王一雪为什么请杨同乐吃晚饭？","Câu hỏi thảo luận Bài khóa 3: (1) 黄河的名字为什么跟“黄”这个颜色有关系？ (2) 黄河是中国最长的河吗？ (3) 在中国人看来，黄河像什么一样？为什么？","Câu hỏi thảo luận Bài khóa 4: (1) 王一雪小时候住的地方环境怎么样？ (2) 小时候，王一雪一到夏天就做什么？ (3) 长大以后，王一雪会去河边做什么？"],"workbook":null},"16":{"pages":"144–153","titleZh":"我听说有的熊猫出国了","titlePy":"Wǒ tīngshuō yǒude xióngmāo chūguó le","titleVi":"Con nghe nói có một số con gấu trúc đã ra nước ngoài","goals":["能听懂并描述动物的特征、习性和生活环境。Có thể nghe hiểu và miêu tả được đặc trưng, thói quen và môi trường sống của động vật.","能听懂并表达个人对动物的看法。Có thể nghe hiểu và trình bày được quan điểm cá nhân về một loài động vật.","掌握比较句（11）的用法，能表达事物在数量或时间上的差异。Nắm vững cách dùng của câu so sánh (11) để diễn đạt sự khác biệt về số lượng hoặc thời gian.","了解大熊猫的基本情况。Hiểu về những kiến thức cơ bản về gấu trúc."],"words":[{"zh":"脏","py":"zāng","vi":"bẩn","pos":"tt."},{"zh":"可爱","py":"kě\u0027ài","vi":"đáng yêu, dễ thương","pos":"tt."},{"zh":"一会儿","py":"yíhuìr","vi":"một lúc, một lát","pos":"phó."},{"zh":"脚","py":"jiǎo","vi":"chân, bàn chân","pos":"dt."},{"zh":"照顾","py":"zhàogù","vi":"chăm sóc","pos":"đgt."},{"zh":"好像","py":"hǎoxiàng","vi":"dường như","pos":"đgt."},{"zh":"认得","py":"rènde","vi":"nhận ra","pos":"đgt."},{"zh":"周末","py":"zhōumò","vi":"cuối tuần","pos":"dt."},{"zh":"动物园","py":"dòngwùyuán","vi":"vườn bách thú, sở thú","pos":"dt."},{"zh":"动物","py":"dòngwù","vi":"động vật","pos":"dt."},{"zh":"大熊猫","py":"dàxióngmāo","vi":"gấu trúc, gấu mèo","pos":"dt."},{"zh":"奇怪","py":"qíguài","vi":"kỳ lạ, kỳ quái","pos":"tt."},{"zh":"其实","py":"qíshí","vi":"thực ra","pos":"phó."},{"zh":"竹子","py":"zhúzi","vi":"tre","pos":"dt."},{"zh":"国宝","py":"guóbǎo","vi":"quốc bảo, bảo vật quốc gia","pos":"dt."},{"zh":"全","py":"quán","vi":"toàn bộ","pos":"tt."},{"zh":"野生","py":"yěshēng","vi":"hoang dã","pos":"tt."},{"zh":"关于","py":"guānyú","vi":"về..., có liên quan tới","pos":"giới."},{"zh":"饱","py":"bǎo","vi":"no","pos":"tt."},{"zh":"张","py":"zhāng","vi":"mở (miệng)","pos":"đgt."},{"zh":"嘴","py":"zuǐ","vi":"miệng","pos":"dt."},{"zh":"身边","py":"shēnbiān","vi":"bên cạnh","pos":"dt."},{"zh":"半天","py":"bàntiān","vi":"nửa ngày, một lúc lâu","pos":"sl."},{"zh":"脸","py":"liǎn","vi":"mặt, khuôn mặt","pos":"dt."},{"zh":"大人","py":"dàren","vi":"người lớn","pos":"dt."},{"zh":"喜爱","py":"xǐ\u0027ài","vi":"yêu thích","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在一家宠物领养店，王一雪和孩子们在看动物。Tại một trung tâm nhận nuôi thú cưng, Vương Nhất Tuyết và các em nhỏ đang xem động vật.","audio":"16-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"这只小猫你们养了多久了？","py":"Zhè zhī xiǎomāo nǐmen yǎngle duōjiǔ le?","vi":"Cô đã nuôi chú mèo con này được bao lâu rồi ạ?"},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"已经一年多了。第一天看见它的时候，它又脏又小。","py":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.","vi":"Đã hơn một năm rồi. Ngày đầu tiên khi nhìn thấy nó, nó vừa bẩn vừa nhỏ xíu."},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"现在它变得又干净又漂亮了。","py":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.","vi":"Bây giờ nó vừa sạch sẽ vừa xinh đẹp!"},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","py":"Shì a. Tā hái tèbié kě\u0027ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","vi":"Đúng vậy. Nó còn siêu đáng yêu nữa, lúc thì nó ngủ ngay dưới chân cháu, lúc thì trèo cả lên người cháu nữa."},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"你们把它照顾得真好。","py":"Nǐmen bǎ tā zhàogù de zhēn hǎo.","vi":"Các cô thực sự đã chăm sóc nó rất tốt ạ."},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"它就好像我们的孩子，我们照顾它，它也认得我们了。","py":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","vi":"Các cô coi nó như con của mình vậy, các cô chăm sóc nó, nó cũng nhận ra các cô."},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"妈妈，我们家也养一只小猫吧。","py":"Māma, wǒmen jiā yě yǎng yì zhī xiǎomāo ba.","vi":"Mẹ ơi, nhà mình cũng nuôi một chú mèo con đi."},{"section":"Bài khóa 1","context":"","audio":"16-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。","py":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.","vi":"Chúng ta không có thời gian chăm sóc nó đâu, nên thôi đừng nuôi con ạ. Cuối tuần mẹ đưa con đến vườn thú Bắc Kinh xem động vật nhé."},{"section":"Bài khóa 2","context":"在动物园，王一雪和孩子们边走边聊。Vương Nhất Tuyết và các em nhỏ vừa đi vừa trò chuyện ở vườn bách thú.","audio":"16-3.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","py":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?","vi":"Mẹ ơi, cái tên “đại gấu mèo” lạ quá, nó có liên quan gì đến loài mèo không ạ?"},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","py":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dàmāoxióng.","vi":"Con hỏi một câu rất hay, nó không liên quan gì đến mèo cả, thực ra nên gọi nó là “gấu trúc”."},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"大熊猫为什么只吃竹子不吃肉？","py":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?","vi":"Tại sao gấu trúc chỉ ăn trúc mà không ăn thịt hả mẹ?"},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","py":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.","vi":"Chúng giống như chúng ta vậy, có thể ăn thịt, nhưng chúng không hứng thú với thịt thôi."},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"大熊猫为什么是中国的国宝？","py":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?","vi":"Tại sao gấu trúc được coi là quốc bảo của Trung Quốc ạ?"},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","py":"Quán shìjiè zhǐ yǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","vi":"Trung Quốc là quê hương của gấu trúc, trên toàn thế giới, chỉ có Trung Quốc mới có gấu trúc sống trong môi trường hoang dã."},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"我听说有的熊猫出国了，他们去哪儿了？","py":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","vi":"Con nghe nói có vài con gấu trúc được gửi ra nước ngoài, chúng đã đi đâu vậy mẹ?"},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"关于这个问题，我得慢慢给你讲。","py":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vi":"Vấn đề này, mẹ sẽ từ từ kể cho con nghe."},{"section":"Bài khóa 2","context":"","audio":"16-3.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"弟弟，你真是“十万个为什么”。","py":"Dìdi, nǐ zhēn shì “shíwàn gè wèishénme”.","vi":"Em trai à, em đúng là cuốn “Mười vạn câu hỏi vì sao” biết đi."},{"section":"Bài khóa 3","context":"在熊猫馆，王一雪和孩子们在看大熊猫。Vương Nhất Tuyết và các em nhỏ đang xem gấu trúc tại nhà của chúng.","audio":"16-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","py":"Zhè zhī dàxióngmāo yíhuìr pá shàngqù, yíhuìr tiào xiàlái, kě\u0027ài jíle!","vi":"Chú gấu trúc này lúc thì trèo lên, lúc thì trèo xuống, cực kì đáng yêu."},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"它好像还没吃饱，站起来张着嘴找吃的呢。","py":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlái zhāngzhe zuǐ zhǎo chī de ne.","vi":"Có vẻ như nó vẫn chưa no, nó đang đứng dậy, há miệng tìm thứ gì đó để ăn."},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"它身边那只熊猫半天没动，是不是在睡觉呢？","py":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bu shì zài shuìjiào ne?","vi":"Con gấu trúc bên cạnh nó đã không động đậy một lúc rồi, nó đang ngủ phải không mẹ?"},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","py":"Wǒ kàn bu jiàn tā de liǎn, kěnéng shì ba. Yìbān láishuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","vi":"Mẹ không nhìn rõ mặt nó, có lẽ là vậy. Gấu trúc thường ngủ rất nhiều giấc trong ngày."},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"对，除了睡觉以外，很多时间都在吃东西。","py":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.","vi":"Đúng ạ, ngoài việc ngủ ra thì nó dành rất nhiều thời gian cho việc ăn."},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"刘小明","name":"Lưu Tiểu Minh","zh":"大熊猫的生活真舒服啊！","py":"Dàxióngmāo de shēnghuó zhēn shūfu a!","vi":"Cuộc sống của gấu trúc thật thoải mái biết bao!"},{"section":"Bài khóa 3","context":"","audio":"16-5.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"妈妈，您帮我和这两只大熊猫照一张照片吧。","py":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.","vi":"Mẹ ơi, mẹ có thể chụp cho con một bức ảnh với hai chú gấu trúc này được không ạ?"},{"section":"Bài khóa 4","context":"在家里，王一雪在写日记。Vương Nhất Tuyết đang ngồi viết nhật ký ở trong nhà.","audio":"16-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"今天我带小雪和小明去动物园玩了。北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","py":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le. Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ\u0027ài de háishi dàxióngmāo. Měitiān yǒu hěn duō yóukè qù xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě\u0027ài de dàxióngmāo pāizhào. Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí gè xiǎoshí. Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì gè búcuò de xuǎnzé.","vi":"Hôm nay, tôi đã đưa Tiểu Tuyết và Tiểu Minh đến vườn thú chơi. Vườn thú Bắc Kinh là một trong những vườn thú rất nổi tiếng ở Trung Quốc, trong đó có rất nhiều loài động vật sinh sống. Tất nhiên, gấu trúc là loài vật được người lớn và trẻ em yêu thích nhất. Mỗi ngày, có rất nhiều du khách đến thăm “Nhà gấu trúc”, họ mang theo máy ảnh để chụp hình những con vật đáng yêu này. Vườn thú mở cửa lúc 7 giờ 30 sáng, đóng cửa lúc 7 giờ tối. Lượng khách vào mùa đông ít hơn mùa hè nên vườn thú đóng cửa sớm hơn một tiếng. Nếu lần đầu đến Bắc Kinh du lịch, cùng gia đình ghé thăm Vườn thú Bắc Kinh chắc chắn là một lựa chọn tuyệt vời."}],"dialogQuestions":[],"grammar":{"g1":{"han":"并列复句“一会儿……，一会儿……”","py":"Bìngliè fùjù “yíhuìr..., yíhuìr...”","title":"Câu ghép đẳng lập “一会儿……，一会儿……”","explain":"并列复句“一会儿……，一会儿……”表示短时间内发生的不同动作，或者一种对立的情况。\nCâu ghép đẳng lập “一会儿……，一会儿……” dùng để biểu thị nhiều hành động khác nhau xảy ra trong thời gian ngắn hoặc một tình huống đối lập.","examples":[{"zh":"它一会儿在你脚边睡觉，一会儿在你身上爬。","py":"Tā yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","vi":"Nó lúc thì ngủ bên chân cháu, lúc thì trèo lên người cháu.","hl":"一会儿……，一会儿……"},{"zh":"他一会儿进来，一会儿出去，忙得很。","py":"Tā yíhuìr jìnlái, yíhuìr chūqù, máng de hěn.","vi":"Anh ấy lúc đi vào, lúc đi ra, bận rộn lắm.","hl":"一会儿……，一会儿……"},{"zh":"最近天气变化很快，一会儿冷，一会儿热。","py":"Zuìjìn tiānqì biànhuà hěn kuài, yíhuìr lěng, yíhuìr rè.","vi":"Gần đây thời tiết thay đổi rất nhanh, lúc lạnh lúc nóng.","hl":"一会儿……，一会儿……"}],"struct":"Chủ ngữ + 一会儿 + V1/Adj1，一会儿 + V2/Adj2","note":"Diễn tả sự thay đổi luân phiên nhanh chóng giữa hai hành động hoặc trạng thái."},"g2":{"han":"介词“关于”","py":"Jiècí “guānyú”","title":"Giới từ “关于”","explain":"介词“关于”后面加名词，引出涉及的对象。\nSau giới từ “关于” có thể thêm danh từ, dùng để dẫn nhập nội dung được đề cập đến.","examples":[{"zh":"关于这个问题，我得慢慢给你讲。","py":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","vi":"Về vấn đề này, mẹ phải từ từ kể cho con nghe.","hl":"关于这个问题"},{"zh":"关于他的要求，我们还要开会以后再决定。","py":"Guānyú tā de yāoqiú, wǒmen hái yào kāihuì yǐhòu zài juédìng.","vi":"Về yêu cầu của anh ấy, chúng ta còn phải đợi sau cuộc họp mới quyết định.","hl":"关于他的要求"},{"zh":"关于比赛的时间，我明天一定告诉大家。","py":"Guānyú bǐsài de shíjiān, wǒ míngtiān yídìng gàosu dàjiā.","vi":"Về thời gian thi đấu, ngày mai tôi nhất định sẽ báo cho mọi người.","hl":"关于比赛的时间"}],"struct":"关于 + Danh từ / Cụm danh từ，+ Mệnh đề (hoặc 关于 + Danh từ + 的 + Danh từ)","note":"Có thể đứng đầu câu làm trạng ngữ chỉ chủ đề hoặc đứng trước “的” làm định ngữ (一本关于动物的书)."},"g3":{"han":"固定短语“一般来说”","py":"Gùdìng duǎnyǔ “yìbān láishuō”","title":"Cụm từ cố định “一般来说”","explain":"“一般来说”是一个固定短语，意思是大多数情况下是这样，常用于句子的开头。\n“一般来说” là một cụm từ cố định thường dùng đầu câu, có nghĩa trong hầu hết các tình huống thì đều như vậy.","examples":[{"zh":"一般来说，熊猫每天要睡很多次觉。","py":"Yìbān láishuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","vi":"Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều giấc.","hl":"一般来说"},{"zh":"一般来说，这种树每年开一次花。","py":"Yìbān láishuō, zhè zhǒng shù měinián kāi yí cì huā.","vi":"Thông thường, loại cây này mỗi năm nở hoa một lần.","hl":"一般来说"},{"zh":"一般来说，学习外语需要多练习。","py":"Yìbān láishuō, xuéxí wàiyǔ xūyào duō liànxí.","vi":"Nói chung, học ngoại ngữ cần luyện tập nhiều.","hl":"一般来说"}],"struct":"一般来说，+ Nhận định phổ biến","note":"Thường đặt ở đầu câu để đưa ra nhận xét mang tính quy luật hoặc thông lệ."},"g4":{"han":"比较句（11）","py":"Bǐjiàojù (11)","title":"Câu so sánh (11)","explain":"用“比”表示的比较句中，谓语为一般动词时，前面可以用“多、少、早、晚”，表示两者在数量或时间上的差异。基本结构：A比B+多/少/早/晚+动词+数量短语。\nTrong câu so sánh khi sử dụng “比”, khi vị ngữ là động từ thì phía trước nó có thể thêm “多”, “少”, “早”, “晚”, biểu thị sự khác biệt về số lượng và thời gian của hai đối tượng.","examples":[{"zh":"冬天比夏天早关门一个小时。","py":"Dōngtiān bǐ xiàtiān zǎo guānmén yí gè xiǎoshí.","vi":"Mùa đông đóng cửa sớm hơn mùa hè một tiếng đồng hồ.","hl":"比……早……一个小时"},{"zh":"哥哥比弟弟多吃了三个饺子。","py":"Gēge bǐ dìdi duō chīle sān gè jiǎozi.","vi":"Anh trai ăn nhiều hơn em trai ba cái sủi cảo.","hl":"比……多吃了三个饺子"},{"zh":"我比他晚到了十分钟。","py":"Wǒ bǐ tā wǎn dàole shí fēnzhōng.","vi":"Tôi đến muộn hơn cậu ấy mười phút.","hl":"比……晚到了十分钟"}],"struct":"A + 比 + B + 多/少/早/晚 + Động từ (+ 了) + Số lượng cụ thể","note":"Lưu ý trật tự: 多/少/早/晚 đứng TRƯỚC động từ, còn số lượng chênh lệch đứng SAU động từ."}},"grammarQuiz":[{"id":"hsk3_b16_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"小猫看到妈妈后马上 (____) 开嘴要吃的。","opts":[{"t":"张","ok":true},{"t":"照顾","ok":false},{"t":"饱","ok":false},{"t":"奇怪","ok":false},{"t":"脏","ok":false}],"exp":"Đáp án B (张): ‘Chú mèo con nhìn thấy mẹ liền há miệng đòi ăn ngay.’"},{"id":"hsk3_b16_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这个电影介绍了怎么 (____) 离开爸爸妈妈的小动物。","opts":[{"t":"照顾","ok":true},{"t":"张","ok":false},{"t":"饱","ok":false},{"t":"奇怪","ok":false},{"t":"脏","ok":false}],"exp":"Đáp án A (照顾): ‘Bộ phim này giới thiệu cách chăm sóc những con vật nhỏ rời xa bố mẹ.’"},{"id":"hsk3_b16_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这只大熊猫没吃 (____)，你看它还在找吃的东西呢。","opts":[{"t":"饱","ok":true},{"t":"照顾","ok":false},{"t":"张","ok":false},{"t":"奇怪","ok":false},{"t":"脏","ok":false}],"exp":"Đáp án C (饱): ‘Chú gấu trúc lớn này ăn chưa no, bạn xem nó vẫn đang tìm đồ ăn kìa.’"},{"id":"hsk3_b16_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这个饭馆的桌子这么 (____)，碗也不干净，咱们换一家吧。","opts":[{"t":"脏","ok":true},{"t":"照顾","ok":false},{"t":"张","ok":false},{"t":"饱","ok":false},{"t":"奇怪","ok":false}],"exp":"Đáp án E (脏): ‘Bàn ở nhà hàng này bẩn thế, bát cũng không sạch, chúng ta đổi quán khác đi.’"},{"id":"hsk3_b16_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这只鸟好像飞不起来，而且吃东西的时候看起来也很 (____)。","opts":[{"t":"奇怪","ok":true},{"t":"照顾","ok":false},{"t":"张","ok":false},{"t":"饱","ok":false},{"t":"脏","ok":false}],"exp":"Đáp án D (奇怪): ‘Con chim này hình như không bay lên được, mà lúc ăn cũng trông rất kỳ lạ.’"},{"id":"hsk3_b16_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 小王，你在找什么？\nB: 我的手机不见了，我找了 (____) 也没找到。","opts":[{"t":"半天","ok":true},{"t":"认得","ok":false},{"t":"关于","ok":false},{"t":"其实","ok":false},{"t":"一般","ok":false}],"exp":"Đáp án E (半天): ‘Điện thoại của tôi mất rồi, tôi tìm cả buổi rồi mà vẫn chưa thấy.’"},{"id":"hsk3_b16_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你想借哪本书？\nB: 我忘了名字，是一本 (____) 动物的书。","opts":[{"t":"关于","ok":true},{"t":"认得","ok":false},{"t":"其实","ok":false},{"t":"一般","ok":false},{"t":"半天","ok":false}],"exp":"Đáp án B (关于): ‘Mình quên tên rồi, là một quyển sách về động vật.’"},{"id":"hsk3_b16_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这只小猫在小区里好几天了，是不是找不到家了？\nB: 我 (____) 它，这是我邻居家的小猫。","opts":[{"t":"认得","ok":true},{"t":"关于","ok":false},{"t":"其实","ok":false},{"t":"一般","ok":false},{"t":"半天","ok":false}],"exp":"Đáp án A (认得): ‘Mình nhận ra nó đấy, đây là mèo con nhà hàng xóm của mình.’"},{"id":"hsk3_b16_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你周末带孩子做什么？\nB: 如果天气好，我 (____) 带孩子去公园里玩。","opts":[{"t":"一般","ok":true},{"t":"认得","ok":false},{"t":"关于","ok":false},{"t":"其实","ok":false},{"t":"半天","ok":false}],"exp":"Đáp án D (一般): ‘Nếu thời tiết đẹp, mình thường đưa con ra công viên chơi.’"},{"id":"hsk3_b16_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你怎么又去动物园了？\nB: (____) 我也不想去，但是妈妈希望我和弟弟一起去。","opts":[{"t":"其实","ok":true},{"t":"认得","ok":false},{"t":"关于","ok":false},{"t":"一般","ok":false},{"t":"半天","ok":false}],"exp":"Đáp án C (其实): ‘Thực ra mình cũng không muốn đi, nhưng mẹ mong mình đi cùng em trai.’"},{"id":"hsk3_b16_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"这只小猫养了多久了？","opts":[{"t":"B 养了一年多了","ok":true},{"t":"A 第一天养","ok":false},{"t":"C 养了很多年了","ok":false}],"exp":"Nhân viên phục vụ nói: “已经一年多了。”"},{"id":"hsk3_b16_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"现在这只小猫是什么样的？","opts":[{"t":"B 特别可爱","ok":true},{"t":"A 特别小","ok":false},{"t":"C 不太干净","ok":false}],"exp":"Nhân viên phục vụ nói: “是啊。它还特别可爱...” (ngày xưa mới vừa bẩn vừa nhỏ, giờ đã sạch đẹp và rất đáng yêu)."},{"id":"hsk3_b16_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪和孩子们在聊什么？","opts":[{"t":"A 大熊猫","ok":true},{"t":"B 北京动物园","ok":false},{"t":"C 动物和人的不同","ok":false}],"exp":"Lưu Tiểu Minh liên tục hỏi mẹ về tên gọi, thức ăn và xuất xứ của gấu trúc lớn (大熊猫)."},{"id":"hsk3_b16_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"刘小雪为什么说弟弟是“十万个为什么”？","opts":[{"t":"C 弟弟喜欢问问题","ok":true},{"t":"A 弟弟喜欢看书","ok":false},{"t":"B 弟弟喜欢听故事","ok":false}],"exp":"Em trai hỏi liền 4 câu hỏi “tại sao” liên tiếp về gấu trúc."},{"id":"hsk3_b16_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"一般来说，大熊猫每天做什么？","opts":[{"t":"C 吃东西和睡觉","ok":true},{"t":"A 爬来爬去","ok":false},{"t":"B 跟人拍照","ok":false}],"exp":"Vương Nhất Tuyết và Lưu Tiểu Tuyết nói: “一般来说，熊猫每天要睡很多次觉... 除了睡觉以外，很多时间都在吃东西。”"},{"id":"hsk3_b16_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘小雪让妈妈帮她做什么？","opts":[{"t":"A 照一张照片","ok":true},{"t":"B 买一些吃的","ok":false},{"t":"C 找一只熊猫","ok":false}],"exp":"Lưu Tiểu Tuyết nói: “妈妈，您帮我和这两只大熊猫照一张照片吧。”"},{"id":"hsk3_b16_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"游客最喜欢去北京动物园看什么动物？","opts":[{"t":"C 大熊猫","ok":true},{"t":"A 牛","ok":false},{"t":"B 羊","ok":false}],"exp":"Bài khóa 4: “当然，大人和孩子最喜爱的还是大熊猫。”"},{"id":"hsk3_b16_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"北京动物园早上几点开门？","opts":[{"t":"C 七点半","ok":true},{"t":"A 六点","ok":false},{"t":"B 七点","ok":false}],"exp":"Bài khóa 4: “动物园早上七点半开门，晚上七点关门...”"}],"chars":["脏","可","爱","一","会","儿","脚","照","顾","好","像","认","得","周","末","动","物","园","大","熊","猫","奇","怪","其","实","竹","子","国","宝","全","野","生","关","于","饱","张","嘴","身","边","半","天","脸","人","喜","我","听","说","有","的","出","了"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 147): “十万个为什么”源于中国很受欢迎的少儿科普读物《十万个为什么》，常用来形容孩子充满好奇心，有时以开玩笑的口吻形容对方问题多。","Tiểu Ngữ giúp sức (trang 152): “又”表示又一次，后面的动词是重复的动作。Từ “又” biểu thị lặp lại một lần nữa, động từ phía sau là động tác có thể lặp lại được.","Món quà của Tiểu Ngữ (trang 153, video 16-1): 大熊猫的“明星”生活 — Đời sống “minh tinh” của gấu trúc.","Câu hỏi thảo luận Bài khóa 1: (1) 服务员第一天看见这只小猫的时候，它是什么样的？ (2) 服务员为什么觉得小猫很可爱？ (3) 服务员和小猫的关系怎么样？","Câu hỏi thảo luận Bài khóa 2: (1) 大熊猫跟猫有关系吗？ (2) 大熊猫为什么只吃竹子不吃肉？ (3) 大熊猫为什么是中国的国宝？","Câu hỏi thảo luận Bài khóa 3: (1) 刘小雪为什么觉得这只大熊猫可爱极了？ (2) 王一雪为什么觉得它没吃饱？ (3) 刘小明觉得大熊猫的生活怎么样？","Câu hỏi thảo luận Bài khóa 4: (1) 今天王一雪带孩子们去哪儿了？ (2) 很多游客去动物园做什么？ (3) 北京动物园夏天和冬天的关门时间有什么不同？"],"workbook":null},"17":{"pages":"154–162","titleZh":"我要多向认真的人学习","titlePy":"Wǒ yào duō xiàng rènzhēn de rén xuéxí","titleVi":"Mình sẽ học hỏi từ những người cẩn thận","goals":["能听懂并表达内心难过、困惑、不满等情绪。Có thể nghe hiểu và biểu đạt được cảm xúc như buồn bã, bối rối và không hài lòng.","能听懂并使用反问句“不是……吗？”表达情感和语气。Có thể nghe hiểu và sử dụng được câu phản vấn sử dụng cấu trúc “不是……吗？” để diễn đạt cảm xúc hoặc ngữ khí.","掌握“只有”的用法，能表达唯一条件和结果。Nắm vững cách dùng của “只有” để diễn đạt điều kiện và kết quả duy nhất."],"words":[{"zh":"向","py":"xiàng","vi":"hướng về","pos":"giới."},{"zh":"楼梯","py":"lóutī","vi":"cầu thang bộ","pos":"dt."},{"zh":"害怕","py":"hàipà","vi":"sợ, sợ hãi","pos":"đgt."},{"zh":"生气","py":"shēngqì","vi":"giận, tức giận","pos":"đgt."},{"zh":"常见","py":"cháng jiàn","vi":"thường thấy","pos":""},{"zh":"聪明","py":"cōngmíng","vi":"thông minh","pos":"tt."},{"zh":"错","py":"cuò","vi":"sai, lỗi, lỗi sai","pos":"dt."},{"zh":"认为","py":"rènwéi","vi":"cho rằng, nhận thấy","pos":"đgt."},{"zh":"到处","py":"dàochù","vi":"mọi nơi, khắp nơi","pos":"phó."},{"zh":"继续","py":"jìxù","vi":"tiếp tục","pos":"đgt."},{"zh":"同意","py":"tóngyì","vi":"đồng ý","pos":"đgt."},{"zh":"可","py":"kě","vi":"nhưng, nhưng mà","pos":"liên."},{"zh":"屋子","py":"wūzi","vi":"phòng, căn phòng, ngôi nhà","pos":"dt."},{"zh":"有关","py":"yǒuguān","vi":"liên quan, có liên quan","pos":"đgt./giới."},{"zh":"关机","py":"guānjī","vi":"tắt máy","pos":"đgt."},{"zh":"前天","py":"qiántiān","vi":"hôm kia","pos":"dt."},{"zh":"留学","py":"liúxué","vi":"du học","pos":"đgt."},{"zh":"国家","py":"guójiā","vi":"quốc gia, đất nước","pos":"dt."},{"zh":"比如","py":"bǐrú","vi":"ví dụ","pos":"đgt."},{"zh":"查","py":"chá","vi":"tra, tìm","pos":"đgt."},{"zh":"有用","py":"yǒuyòng","vi":"hữu ích","pos":"tt."},{"zh":"容易","py":"róngyì","vi":"dễ, dễ dàng","pos":"tt."},{"zh":"回答","py":"huídá","vi":"trả lời","pos":"đgt."},{"zh":"方向","py":"fāngxiàng","vi":"phương hướng","pos":"dt."},{"zh":"只有","py":"zhǐyǒu","vi":"chỉ có","pos":"liên."},{"zh":"真正","py":"zhēnzhèng","vi":"thực sự","pos":"phó."},{"zh":"难题","py":"nántí","vi":"vấn đề khó, vấn đề nan giải","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在教学楼里，刘小雪和同学边走边聊。Trong giảng đường, Lưu Tiểu Tuyết và bạn học đang vừa đi vừa trò chuyện.","audio":"17-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"别再向前走了，李老师的办公室已经到了。","py":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le.","vi":"Đừng đi về phía trước nữa, chúng ta đã tới văn phòng cô Lý rồi."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","py":"Nǐ jìnqù ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","vi":"Bạn vào đi, mình sẽ đợi bạn ở chỗ cầu thang. Mình sợ gặp cô Lý lắm."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"怎么回事？","py":"Zěnme huí shì?","vi":"Có chuyện gì vậy?"},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"最近我做错了好几件事，我怕李老师生气。","py":"Zuìjìn wǒ zuòcuòle hǎo jǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì.","vi":"Gần đây mình làm sai một số việc, mình sợ cô Lý sẽ bực mình."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"你想多了，做错事情是很常见的。","py":"Nǐ xiǎng duō le, zuòcuò shìqing shì hěn cháng jiàn de.","vi":"Bạn nghĩ nhiều quá rồi, làm sai cũng là chuyện thường tình thôi mà."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"我把简单的事情做错了，李老师一定觉得我不认真。","py":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn.","vi":"Nhưng ngay cả những cái rất đơn giản, mình cũng đã làm sai. Cô Lý chắc hẳn nghĩ mình không cẩn thận."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"刘小雪","name":"Lưu Tiểu Tuyết","zh":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","py":"Yǒude rén suīrán hěn cōngmíng, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le.","vi":"Có những người mặc dù họ rất thông minh, nhưng vẫn làm sai những việc đơn giản nhất, vì họ nghĩ những việc đó quá dễ nên không làm một cách cẩn thận."},{"section":"Bài khóa 1","context":"","audio":"17-1.mp3","speaker":"同学","name":"Bạn cùng lớp","zh":"你说的就是我，以后我要多向认真的人学习。","py":"Nǐ shuō de jiùshì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vi":"Người mà bạn nói đó chính là mình đấy. Từ giờ trở đi, mình sẽ học hỏi từ những người cẩn thận."},{"section":"Bài khóa 2","context":"在阅览室门口，白家月碰到了陈天中。Bạch Gia Nguyệt gặp Trần Thiên Trung ở cửa phòng đọc sách.","audio":"17-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","py":"Tàiyáng cóng xībiān chūlái le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?","vi":"Mặt trời mọc ở hướng tây sao? Dạo này ngày nào mình cũng thấy bạn ở thư viện."},{"section":"Bài khóa 2","context":"","audio":"17-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"这有什么奇怪的？我是来学习的。","py":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de.","vi":"Có gì lạ đâu cơ chứ? Mình đến đây để học mà."},{"section":"Bài khóa 2","context":"","audio":"17-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"你怎么还来图书馆学习？同学们都在到处找工作呢。","py":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","vi":"Tại sao bạn vẫn đến thư viện học thế? Các bạn khác đều đang đi khắp nơi tìm việc làm rồi kìa."},{"section":"Bài khóa 2","context":"","audio":"17-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","py":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan.","vi":"Giờ mình chưa muốn đi làm, mình vẫn muốn tiếp tục học nữa, bố mẹ mình cũng đồng ý rồi. Nhưng mình vẫn chưa quyết định sẽ học ngành gì, nên đến đây để xem."},{"section":"Bài khóa 2","context":"","audio":"17-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","py":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vi":"Chẳng phải bạn thích mày mò máy tính sao? Bạn có thể đọc sách liên quan đến máy tính xem."},{"section":"Bài khóa 2","context":"","audio":"17-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","py":"Nǐ shuō de duì, wǒ jìde nàge wūzi li yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao.","vi":"Bạn nói đúng, mình nhớ ở trong phòng kia có một vài đầu sách liên quan đến máy tính, mình đi tìm thử xem nhé."},{"section":"Bài khóa 3","context":"在校园里，李文和陈天中在聊天儿。Lý Văn và Trần Thiên Trung đang trò chuyện trong khuôn viên trường.","audio":"17-5.mp3","speaker":"李文","name":"Lý Văn","zh":"天中，你的手机怎么关机了？","py":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","vi":"Thiên Trung, sao bạn lại tắt điện thoại thế?"},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我的手机没电了。你找我有事吗？","py":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒu shì ma?","vi":"Điện thoại mình hết pin rồi. Bạn tìm mình có chuyện gì không?"},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"李文","name":"Lý Văn","zh":"前天我看见家月了，她告诉我你打算继续留学？","py":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","vi":"Hôm kia mình đã gặp Gia Nguyệt, cô ấy nói với mình là bạn đang có kế hoạch tiếp tục học lên đúng không?"},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"是，可是我还没想好学什么，更没想好去哪个国家。","py":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Đúng vậy, nhưng mình vẫn chưa quyết định học ngành gì, cũng chưa quyết định sẽ đi học ở nước nào."},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"李文","name":"Lý Văn","zh":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","py":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàlǐ yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng.","vi":"Bạn có thể đến Trung Quốc để học tiếng Trung Quốc. Những thành phố lớn như Bắc Kinh và Thượng Hải có nhiều trường đại học tốt, cũng có rất nhiều lưu học sinh."},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"好，那我上网查一查。","py":"Hǎo, nà wǒ shàngwǎng chá yi chá.","vi":"Được, mình sẽ lên mạng tra xem sao."},{"section":"Bài khóa 3","context":"","audio":"17-5.mp3","speaker":"李文","name":"Lý Văn","zh":"我给你介绍几个有用的网站。","py":"Wǒ gěi nǐ jièshào jǐ gè yǒuyòng de wǎngzhàn.","vi":"Mình có thể gợi ý cho bạn vài trang web hữu ích."},{"section":"Bài khóa 4","context":"在家里，陈天中在写日记。Trần Thiên Trung đang ngồi viết nhật ký ở trong nhà.","audio":"17-7.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"大学生活马上就要结束了，我最近经常被问到一个问题——“你以后做什么”，这个问题真不容易回答。我也问了几个同学，大家选择的方向都不同。有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。对我来说，想清楚“真正喜欢什么”是个难题。","py":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèndào yí gè wèntí —— “nǐ yǐhòu zuò shénme”, zhège wèntí zhēn bù róngyì huídá. Wǒ yě wènle jǐ gè tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng. Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuàn chūguó liúxué, hái yǒude juédìng xiān zhǎo gōngzuò. Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé. Duì wǒ láishuō, xiǎng qīngchu “zhēnzhèng xǐhuan shénme” shì gè nántí.","vi":"Cuộc sống sinh viên của tôi sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu rằng: “Sau khi tốt nghiệp bạn sẽ làm gì?”. Đây là một câu hỏi thực sự không dễ để trả lời. Tôi cũng đã hỏi vài người bạn, mỗi người đều chọn một hướng đi khác nhau. Có người muốn tiếp tục ở lại trường học cao lên, có người định đi du học, và cũng có người quyết định đi tìm việc làm trước. Tôi cho rằng, chỉ khi nào bạn nghĩ kĩ bạn thực sự thích gì, bạn mới có thể đưa ra quyết định phù hợp nhất. Đối với tôi mà nói, nghĩ cho rõ “bản thân thực sự thích gì” lại là một vấn đề nan giải."}],"dialogQuestions":[],"grammar":{"g1":{"han":"介词“向”","py":"Jiècí “xiàng”","title":"Giới từ “向”","explain":"介词“向”后加代词、名词或名词性短语，表示动作的方向或对象。\nGiới từ “向” đứng trước đại từ, danh từ hoặc cụm danh từ để chỉ phương hướng hoặc đối tượng của hành động.","examples":[{"zh":"别再向前走了。","py":"Bié zài xiàng qián zǒu le.","vi":"Đừng đi về phía trước nữa.","hl":"向前"},{"zh":"以后我要多向认真的人学习。","py":"Yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","vi":"Sau này mình sẽ học hỏi nhiều hơn từ những người cẩn thận.","hl":"向认真的人学习"},{"zh":"孩子一看见妈妈，就向她跑过去了。","py":"Háizi yí kànjiàn māma, jiù xiàng tā pǎo guòqù le.","vi":"Đứa trẻ vừa nhìn thấy mẹ liền chạy về phía mẹ.","hl":"向她跑过去"}],"struct":"Chủ ngữ + 向 + Phương hướng / Đối tượng + Động từ","note":"Thường dùng với động từ di chuyển (向前走, 向她跑) hoặc động từ tiếp nhận/giao tiếp (向……学习, 向……请假, 向……介绍)."},"g2":{"han":"反问句“不是……吗？”","py":"Fǎnwènjù “bú shì... ma?”","title":"Câu phản vấn sử dụng cấu trúc “不是……吗？”","explain":"反问句“不是……吗？”一般用来表达说话人的不理解或者不满，有时候也表示提醒或确认等。否定形式表达肯定的意思。\nCâu phản vấn sử dụng cấu trúc “不是……吗？” thường được dùng để biểu đạt người nói không hiểu hoặc không hài lòng, có lúc biểu đạt sự nhắc nhở hoặc xác nhận. Tuy hình thức phủ định nhưng lại biểu thị ý nghĩa khẳng định.","examples":[{"zh":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","py":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxi de shū.","vi":"Chẳng phải bạn thích chơi máy tính sao? Bạn có thể xem những sách liên quan đến máy tính.","hl":"不是……吗？"},{"zh":"你不是说今天有事吗？为什么来了？","py":"Nǐ bú shì shuō jīntiān yǒu shì ma? Wèishénme lái le?","vi":"Chẳng phải bạn nói hôm nay có việc sao? Sao lại đến thế?","hl":"不是……吗？"},{"zh":"考试不是下个月吗？你怎么今天就开始复习了？","py":"Kǎoshì bú shì xià gè yuè ma? Nǐ zěnme jīntiān jiù kāishǐ fùxí le?","vi":"Kỳ thi chẳng phải tháng sau mới thi sao? Sao hôm nay bạn đã bắt đầu ôn tập rồi?","hl":"不是……吗？"}],"struct":"(Chủ ngữ +) 不是 + Sự việc được biết trước + 吗？","note":"Tương đương “chẳng phải... sao?”, dùng để nhấn mạnh điều người nói vốn cho là đúng."},"g3":{"han":"递进复句“……，更……”","py":"Dìjìn fùjù “..., gèng...”","title":"Câu ghép tăng tiến “……，更……”","explain":"递进复句“……，更……”中，第二个分句表示程度上更深一层。\nTrong câu ghép tăng tiến “……，更……”, mệnh đề thứ hai biểu thị mức độ cao hơn.","examples":[{"zh":"我还没想好学什么，更没想好去哪个国家。","py":"Wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","vi":"Mình vẫn chưa nghĩ kỹ nên học gì, càng chưa nghĩ kỹ sẽ đi nước nào.","hl":"更"},{"zh":"想提高中文水平要多听多看，更要多说多练。","py":"Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.","vi":"Muốn nâng cao trình độ tiếng Trung cần nghe nhiều xem nhiều, càng phải nói nhiều luyện nhiều.","hl":"更要"},{"zh":"来中国学习，我学会了中文，更了解了中国文化。","py":"Lái Zhōngguó xuéxí, wǒ xuéhuìle Zhōngwén, gèng liǎojiěle Zhōngguó wénhuà.","vi":"Đến Trung Quốc học tập, tôi đã học được tiếng Trung, càng hiểu rõ hơn về văn hoá Trung Quốc.","hl":"更了解了"}],"struct":"Mệnh đề 1，+ 更 + Mệnh đề 2 (mức độ sâu/cao hơn)","note":"Vế sau tiến thêm một bước so với vế trước (cả nghĩa khẳng định lẫn phủ định)."},"g4":{"han":"条件复句“只有……，才……”","py":"Tiáojiàn fùjù “zhǐyǒu..., cái...”","title":"Câu ghép điều kiện “只有……，才……”","explain":"条件复句“只有……，才……”中，“只有”后面是实现结果的唯一条件，没有这个条件就不会产生“才”后面的结果。\nTrong câu ghép điều kiện “只有……，才……”, thành phần đứng sau “只有” biểu thị điều kiện duy nhất để đạt được kết quả, nếu không có điều kiện này, kết quả đứng sau “才” sẽ không thể xảy ra.","examples":[{"zh":"只有想清楚自己真正喜欢什么，才能做出最合适的选择。","py":"Zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","vi":"Chỉ có nghĩ rõ bản thân thực sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất.","hl":"只有……，才……"},{"zh":"只有每天锻炼身体，才会越来越健康。","py":"Zhǐyǒu měitiān duànliàn shēntǐ, cái huì yuèláiyuè jiànkāng.","vi":"Chỉ có rèn luyện sức khoẻ mỗi ngày thì mới ngày càng khoẻ mạnh được.","hl":"只有……，才……"},{"zh":"只有多听、多说、多看，你的中文水平才能提高。","py":"Zhǐyǒu duō tīng, duō shuō, duō kàn, nǐ de Zhōngwén shuǐpíng cái néng tígāo.","vi":"Chỉ có nghe nhiều, nói nhiều, đọc nhiều thì trình độ tiếng Trung của bạn mới có thể nâng cao.","hl":"只有……，……才……"}],"struct":"只有 + Điều kiện duy nhất，+ (Chủ ngữ 2 +) 才 + Kết quả","note":"Khác với “只要……，就……” (điều kiện đủ); “只有……，才……” nhấn mạnh điều kiện DUY NHẤT."}},"grammarQuiz":[{"id":"hsk3_b17_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"在生活中，因为不认真做错事情是很 (____) 的。","opts":[{"t":"常见","ok":true},{"t":"方向","ok":false},{"t":"回答","ok":false},{"t":"难题","ok":false},{"t":"同意","ok":false}],"exp":"Đáp án A (常见): ‘Trong cuộc sống, làm sai việc vì không cẩn thận là chuyện rất thường thấy.’"},{"id":"hsk3_b17_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我认为大学的时候就应该选好以后工作的 (____)。","opts":[{"t":"方向","ok":true},{"t":"常见","ok":false},{"t":"回答","ok":false},{"t":"难题","ok":false},{"t":"同意","ok":false}],"exp":"Đáp án B (方向): ‘Tôi cho rằng ngay từ thời đại học đã nên chọn sẵn phương hướng công việc sau này.’"},{"id":"hsk3_b17_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他说的话我一句也不 (____)，你也不要受他的影响。","opts":[{"t":"同意","ok":true},{"t":"常见","ok":false},{"t":"方向","ok":false},{"t":"回答","ok":false},{"t":"难题","ok":false}],"exp":"Đáp án E (同意): ‘Lời anh ấy nói tôi chẳng đồng ý câu nào, bạn cũng đừng bị anh ấy ảnh hưởng.’"},{"id":"hsk3_b17_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这个问题我还没想清楚怎么 (____) 他。","opts":[{"t":"回答","ok":true},{"t":"常见","ok":false},{"t":"方向","ok":false},{"t":"难题","ok":false},{"t":"同意","ok":false}],"exp":"Đáp án C (回答): ‘Câu hỏi này mình vẫn chưa nghĩ rõ nên trả lời cậu ấy thế nào.’"},{"id":"hsk3_b17_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"对我来说，怎么让父母同意我的选择是一个 (____)。","opts":[{"t":"难题","ok":true},{"t":"常见","ok":false},{"t":"方向","ok":false},{"t":"回答","ok":false},{"t":"同意","ok":false}],"exp":"Đáp án D (难题): ‘Đối với tôi, làm sao để bố mẹ đồng ý với lựa chọn của mình là một bài toán khó.’"},{"id":"hsk3_b17_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 已经下课了，同学们都走了吗？\nB: 没有，还有几个人在 (____) 问李老师问题。","opts":[{"t":"继续","ok":true},{"t":"到处","ok":false},{"t":"比如","ok":false},{"t":"有关","ok":false},{"t":"认为","ok":false}],"exp":"Đáp án C (继续): ‘Chưa, vẫn còn mấy người đang tiếp tục hỏi bài cô Lý.’"},{"id":"hsk3_b17_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你为什么 (____) 找我？有什么急事？\nB: 我要告诉你一件很重要的事。","opts":[{"t":"到处","ok":true},{"t":"比如","ok":false},{"t":"继续","ok":false},{"t":"有关","ok":false},{"t":"认为","ok":false}],"exp":"Đáp án A (到处): ‘Tại sao bạn đi tìm mình khắp nơi thế? Có chuyện gì gấp à?’"},{"id":"hsk3_b17_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你觉得中文难学吗？\nB: 我 (____) 汉字有点儿难，但是也非常有意思。","opts":[{"t":"认为","ok":true},{"t":"到处","ok":false},{"t":"比如","ok":false},{"t":"继续","ok":false},{"t":"有关","ok":false}],"exp":"Đáp án E (认为): ‘Mình cho rằng chữ Hán hơi khó một chút, nhưng cũng rất thú vị.’"},{"id":"hsk3_b17_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 今天下午的会议跟留学生 (____) 吗？\nB: 没有，留学生都不用参加。","opts":[{"t":"有关","ok":true},{"t":"到处","ok":false},{"t":"比如","ok":false},{"t":"继续","ok":false},{"t":"认为","ok":false}],"exp":"Đáp án D (有关): ‘Cuộc họp chiều nay có liên quan đến lưu học sinh không?’"},{"id":"hsk3_b17_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 中国的很多城市历史都很长，(____) 北京、南京、西安。\nB: 谢谢，我打算夏天先去西安看一看。","opts":[{"t":"比如","ok":true},{"t":"到处","ok":false},{"t":"继续","ok":false},{"t":"有关","ok":false},{"t":"认为","ok":false}],"exp":"Đáp án B (比如): ‘Rất nhiều thành phố của Trung Quốc có lịch sử lâu đời, ví dụ như Bắc Kinh, Nam Kinh, Tây An.’"},{"id":"hsk3_b17_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"小雪的同学为什么到了李老师办公室后还向前走？","opts":[{"t":"C 害怕见李老师","ok":true},{"t":"A 走错了","ok":false},{"t":"B 想去楼梯那儿","ok":false}],"exp":"Bạn học nói: “你进去吧，我在楼梯那儿等你。我害怕见李老师。”"},{"id":"hsk3_b17_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"小雪的同学认为自己是一个什么样的人？","opts":[{"t":"B 不认真的","ok":true},{"t":"A 简单的","ok":false},{"t":"C 不聪明的","ok":false}],"exp":"Bạn học nói cô Lý chắc chắn nghĩ mình không cẩn thận và tự nhận: “你说的就是我，以后我要多向认真的人学习。”"},{"id":"hsk3_b17_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"同学们最近都在做什么？","opts":[{"t":"B 找工作","ok":true},{"t":"A 玩电脑","ok":false},{"t":"C 去图书馆学习","ok":false}],"exp":"Bạch Gia Nguyệt nói: “同学们都在到处找工作呢。”"},{"id":"hsk3_b17_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"陈天中的爸妈希望他做什么？","opts":[{"t":"B 继续学习","ok":true},{"t":"A 工作","ok":false},{"t":"C 多去图书馆","ok":false}],"exp":"Trần Thiên Trung nói: “我不想现在就工作，还想继续学习，我爸妈也同意。”"},{"id":"hsk3_b17_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"李文找陈天中有什么事？","opts":[{"t":"A 给他出一些主意","ok":true},{"t":"B 告诉他手机没电了","ok":false},{"t":"C 告诉他家月也要留学","ok":false}],"exp":"Lý Văn khuyên Trần Thiên Trung có thể sang Trung Quốc học tiếng Trung và gợi ý vài trang web hữu ích."},{"id":"hsk3_b17_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"陈天中想好学什么了吗？","opts":[{"t":"C 他还没想好","ok":true},{"t":"A 他想学中文","ok":false},{"t":"B 他想学历史","ok":false}],"exp":"Trần Thiên Trung nói: “可是我还没想好学什么，更没想好去哪个国家。”"},{"id":"hsk3_b17_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"陈天中最近在想什么？","opts":[{"t":"C 大学结束后做什么","ok":true},{"t":"A 怎么找工作","ok":false},{"t":"B 真正喜欢的同学","ok":false}],"exp":"Bài khóa 4: “大学生活马上就要结束了，我最近经常被问到一个问题——‘你以后做什么’...”"},{"id":"hsk3_b17_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"陈天中觉得怎么才能做出最合适的选择？","opts":[{"t":"C 想清楚自己真正喜欢什么","ok":true},{"t":"A 听老师的话","ok":false},{"t":"B 看别人怎么做","ok":false}],"exp":"Bài khóa 4: “我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。”"}],"chars":["向","楼","梯","害","怕","生","气","常","见","聪","明","错","认","为","到","处","继","续","同","意","可","屋","子","有","关","机","前","天","留","学","国","家","比","如","查","用","容","易","回","答","方","只","真","正","难","题","我","要","多","的","人","习"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 小雪的同学为什么害怕见李老师？ (2) 小雪认为她的同学为什么做错事？ (3) 小雪的同学打算以后怎么做？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月为什么说“太阳从西边出来了”？ (2) 陈天中为什么不去找工作？ (3) 白家月觉得陈天中可以学什么？","Câu hỏi thảo luận Bài khóa 3: (1) 陈天中打算做什么？ (2) 李文给他出了什么主意？ (3) 李文为什么给陈天中介绍几个网站？","Câu hỏi thảo luận Bài khóa 4: (1) 陈天中最近经常被问到什么问题？ (2) 同学们有哪些不同的选择？ (3) 陈天中知道自己真正喜欢什么吗？"],"workbook":null},"18":{"pages":"163–173","titleZh":"我学会了包饺子","titlePy":"Wǒ xuéhuìle bāo jiǎozi","titleVi":"Cháu đã học được cách gói sủi cảo","goals":["能听懂并描述生活中的变化和成长经历。Có thể nghe hiểu và miêu tả được những thay đổi và trải nghiệm trưởng thành trong cuộc sống.","能听懂并使用概数表达不确定的数量。Có thể nghe hiểu và sử dụng được số ước lượng để diễn đạt con số không chính xác.","掌握“只要”的用法，能表达充分条件和结果。Nắm vững cách dùng của “只要” để diễn đạt điều kiện và kết quả.","了解中国传统节日“春节”的习俗。Hiểu về tập tục tết Nguyên đán truyền thống của Trung Quốc."],"words":[{"zh":"怎样","py":"zěnyàng","vi":"thế nào","pos":"đt."},{"zh":"过节","py":"guòjié","vi":"đón lễ","pos":"đgt."},{"zh":"节","py":"jié","vi":"lễ","pos":"dt."},{"zh":"节日","py":"jiérì","vi":"ngày lễ","pos":"dt."},{"zh":"联欢","py":"liánhuān","vi":"liên hoan","pos":"đgt."},{"zh":"大概","py":"dàgài","vi":"khoảng, đại khái, chung chung","pos":"phó./tt."},{"zh":"春节","py":"Chūnjié","vi":"tết Nguyên đán","pos":"dt. riêng"},{"zh":"阿姨","py":"āyí","vi":"cô, dì","pos":"dt."},{"zh":"叔叔","py":"shūshu","vi":"chú","pos":"dt."},{"zh":"收","py":"shōu","vi":"nhận, thu","pos":"đgt."},{"zh":"总","py":"zǒng","vi":"luôn luôn","pos":"phó."},{"zh":"起","py":"qǐ","vi":"(nói) đến (dùng sau động từ, chỉ người/vật liên quan)","pos":"đgt."},{"zh":"见面","py":"jiànmiàn","vi":"gặp mặt","pos":"đgt."},{"zh":"矿泉水","py":"kuàngquánshuǐ","vi":"nước khoáng, nước suối","pos":"dt."},{"zh":"刚刚","py":"gānggāng","vi":"vừa mới","pos":"phó."},{"zh":"出发","py":"chūfā","vi":"xuất phát","pos":"đgt."},{"zh":"不久","py":"bùjiǔ","vi":"không lâu","pos":"tt."},{"zh":"发生","py":"fāshēng","vi":"xảy ra","pos":"đgt."},{"zh":"刚","py":"gāng","vi":"vừa, vừa mới","pos":"phó."},{"zh":"只要","py":"zhǐyào","vi":"chỉ cần","pos":"liên."},{"zh":"学期","py":"xuéqī","vi":"học kỳ","pos":"dt."},{"zh":"毕业","py":"bìyè","vi":"tốt nghiệp","pos":"đgt."},{"zh":"出生","py":"chūshēng","vi":"sinh, sinh ra","pos":"đgt."},{"zh":"过去","py":"guòqù","vi":"quá khứ, trước kia","pos":"dt."},{"zh":"懂得","py":"dǒngde","vi":"hiểu","pos":"đgt."},{"zh":"坚持","py":"jiānchí","vi":"kiên trì","pos":"đgt."},{"zh":"完成","py":"wánchéng","vi":"hoàn thành","pos":"đgt."},{"zh":"目标","py":"mùbiāo","vi":"mục tiêu","pos":"dt."},{"zh":"发展","py":"fāzhǎn","vi":"phát triển","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在飞机上，白家月和李文在聊天儿。Bạch Gia Nguyệt và Lý Văn đang trò chuyện trên máy bay.","audio":"18-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我要在中国过年，真开心。","py":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","vi":"Em sẽ đón tết Nguyên đán ở Trung Quốc, thật vui quá."},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"李文","name":"Lý Văn","zh":"第一次请外国朋友来家里过春节，我也很高兴。","py":"Dì-yī cì qǐng wàiguó péngyou lái jiāli guò Chūnjié, wǒ yě hěn gāoxìng.","vi":"Đây là lần đầu tiên anh mời một người bạn nước ngoài về nhà ăn Tết. Anh cũng thực sự rất vui."},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"你们怎样过节？","py":"Nǐmen zěnyàng guòjié?","vi":"Các anh thường đón Tết như thế nào?"},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"李文","name":"Lý Văn","zh":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","py":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huíjiā, gēn jiārén yìqǐ guò.","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất ở Trung Quốc, bọn anh thường về nhà ăn Tết với gia đình."},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那你跟家人会一起做什么？","py":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","vi":"Vậy anh và người thân thường làm gì vậy?"},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","py":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié liánhuān wǎnhuì, yìzhí dào shí\u0027èr diǎn yǐhòu cái shuìjiào.","vi":"Bọn anh sẽ vừa gói sủi cảo, vừa xem chương trình Gala Đêm hội mùa xuân, sau 12 giờ đêm thì mới đi ngủ."},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"听起来很有意思。春节放几天假？","py":"Tīng qǐlái hěn yǒuyìsi. Chūnjié fàng jǐ tiān jià?","vi":"Nghe có vẻ rất thú vị. Các anh được nghỉ Tết bao nhiêu ngày vậy?"},{"section":"Bài khóa 1","context":"","audio":"18-1.mp3","speaker":"李文","name":"Lý Văn","zh":"大概七八天。","py":"Dàgài qī bā tiān.","vi":"Khoảng 7, 8 ngày."},{"section":"Bài khóa 2","context":"在李文家，白家月给李文的父母拜年。Bạch Gia Nguyệt đến chúc Tết bố mẹ của Lý Văn tại nhà anh ấy.","audio":"18-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","py":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià.","vi":"Chúc mừng năm mới cô Trương và chú Lý ạ! Đây là quà cháu chuẩn bị cho cô chú, mong cô chú nhận giúp ạ."},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"李叔叔","name":"Chú Lý","zh":"谢谢家月，你太客气了！","py":"Xièxie Jiāyuè, nǐ tài kèqi le!","vi":"Cảm ơn Gia Nguyệt. Cháu thật khách sáo quá!"},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"张阿姨","name":"Cô Trương","zh":"总听小文说起你，今天终于有机会见面了。","py":"Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.","vi":"Tiểu Văn lúc nào cũng nhắc về cháu, hôm nay cuối cùng cũng có dịp gặp nhau rồi."},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"谢谢您和叔叔请我来家里做客。","py":"Xièxie nín hé shūshu qǐng wǒ lái jiāli zuòkè.","vi":"Cháu cảm ơn cô chú đã mời cháu tới nhà chơi ạ."},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"李叔叔","name":"Chú Lý","zh":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","py":"Zhuōzi shang yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","vi":"Trên bàn có nước suối và các loại đồ uống, cháu muốn uống gì thì cứ tự nhiên lấy nhé."},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"张阿姨","name":"Cô Trương","zh":"你先坐着看会儿电视，饺子很快就包好了。","py":"Nǐ xiān zuòzhe kànhuìr diànshì, jiǎozi hěn kuài jiù bāohǎo le.","vi":"Cháu ngồi xuống xem tivi một lát đi. Sủi cảo sẽ gói xong ngay bây giờ thôi."},{"section":"Bài khóa 2","context":"","audio":"18-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","py":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.","vi":"Cháu đã học cách gói sủi cảo qua video, để cháu gói cùng cô chú nhé!"},{"section":"Bài khóa 3","context":"在李文家，李文妈妈和白家月在聊天儿。Mẹ của Lý Văn đang trò chuyện cùng với Bạch Gia Nguyệt tại nhà của anh ấy.","audio":"18-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这张照片是李文出国前照的吗？","py":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","vi":"Có phải bức ảnh này được chụp trước khi Lý Văn ra nước ngoài không ạ?"},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"张阿姨","name":"Cô Trương","zh":"对，这是他从北京出发时，我们全家在机场照的。","py":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de.","vi":"Đúng vậy, đây là bức ảnh được chụp tại sân bay Bắc Kinh khi cả gia đình cô tiễn Lý Văn."},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那是三四年前吧？","py":"Nà shì sān sì nián qián ba?","vi":"Là khoảng ba hoặc bốn năm trước rồi phải không ạ?"},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"张阿姨","name":"Cô Trương","zh":"是啊，时间过得真快，好像是不久前发生的一样。","py":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","vi":"Đúng vậy, thời gian trôi nhanh thật đấy, cứ như mới ngày hôm qua vậy."},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"您一定特别想李文吧？","py":"Nín yídìng tèbié xiǎng Lǐ Wén ba?","vi":"Cô chắc nhớ Lý Văn lắm phải không ạ?"},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"张阿姨","name":"Cô Trương","zh":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","py":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vi":"Lúc nó mới đi xa nhà, cô không quen lắm, chỉ cần vài ngày không gọi video cho nó là cô rất nhớ nó."},{"section":"Bài khóa 3","context":"","audio":"18-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"还有最后一个学期就要毕业了，他很快就会回来了。","py":"Hái yǒu zuìhòu yí gè xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le.","vi":"Chỉ còn một học kỳ nữa thôi là anh ấy tốt nghiệp rồi. Anh ấy sẽ sớm trở về thôi ạ."},{"section":"Bài khóa 4","context":"在家里，白家月在写日记。Bạch Gia Nguyệt đang ngồi viết nhật ký ở trong nhà.","audio":"18-7.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这次来中国，我最高兴的是认识了李文的父母。他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。李文高中的时候想学医，从那时起就努力学习。高三的时候，因为成绩特别好，他得到了出国留学的机会。在他身上，我懂得了，只要一直坚持，就能完成自己的目标。我相信，他以后一定会发展得更好。","py":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshile Lǐ Wén de fùmǔ. Tāmen gěi wǒ kànle Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎngle hěn duō tā guòqù de gùshi. Lǐ Wén gāozhōng de shíhou xiǎng xuéyī, cóng nà shí qǐ jiù nǔlì xuéxí. Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédàole chūguó liúxué de jīhuì. Zài tā shēnshang, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo. Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo.","vi":"Lần này đến Trung Quốc, điều khiến tôi hạnh phúc nhất là được làm quen với bố mẹ của Lý Văn. Họ đã cho tôi xem những bức ảnh chụp khi Lý Văn mới chào đời, còn kể cho tôi nghe nhiều câu chuyện thuở xưa của anh ấy. Khi còn học trung học phổ thông, Lý Văn muốn học ngành y nên đã học tập rất chăm chỉ. Vào năm lớp 12, anh ấy giành được cơ hội đi du học nhờ thành tích học tập đặc biệt xuất sắc của mình. Qua câu chuyện của anh ấy, tôi học được rằng, chỉ cần luôn kiên trì, bạn có thể đạt được mục tiêu của mình. Tôi tin rằng, sau này anh ấy sẽ còn đạt được những điều tuyệt vời hơn nữa."}],"dialogQuestions":[],"grammar":{"g1":{"han":"概数表达法","py":"Gàishù biǎodáfǎ","title":"Cách diễn đạt số ước lượng","explain":"汉语中相邻的两个数字连用，表示不确定的数量。\nTrong tiếng Trung Quốc, sử dụng hai con số liền kề nhau để diễn đạt số ước lượng.","examples":[{"zh":"春节大概放七八天假。","py":"Chūnjié dàgài fàng qī bā tiān jià.","vi":"Tết Nguyên đán nghỉ khoảng bảy tám ngày.","hl":"七八"},{"zh":"教室里来了五六个学生。","py":"Jiàoshì li láile wǔ liù gè xuésheng.","vi":"Trong lớp học có năm sáu học sinh đến rồi.","hl":"五六"},{"zh":"这些照片是三四年前照的吧？","py":"Zhèxiē zhàopiàn shì sān sì nián qián zhào de ba?","vi":"Những bức ảnh này chụp cách đây ba bốn năm rồi phải không?","hl":"三四"}],"struct":"Số n + Số (n+1) + Lượng từ (+ Danh từ)","note":"Hai chữ số đứng cạnh nhau theo thứ tự tăng dần (一两, 两三, 三四, 五六, 七八, 八九), thường tránh dùng 九十."},"g2":{"han":"“刚才”和“刚刚”","py":"“Gāngcái” hé “gānggāng”","title":"“刚才” và “刚刚”","explain":"“刚才”是时间名词，表示很短的时间以前，一般来说就是几分钟以前。“刚才”可以放在句首，也可以放在主语后面，动词前面。“刚刚”是时间副词，表示对说话人来说事情发生的时间不长，可能是几分钟、几天甚至几个月。“刚刚”应该放在主语后面，动词前面。\n“刚才” là danh từ chỉ thời gian, biểu thị khoảng thời gian ngắn ngay trước thời điểm nói (thường là vài phút trước đó); có thể đứng đầu câu hoặc giữa chủ ngữ và động từ. “刚刚” là phó từ chỉ thời gian, dùng để chỉ hành động xảy ra trong thời gian ngắn theo quan điểm của người nói (vài phút, vài ngày, thậm chí vài tháng); thường đứng sau chủ ngữ và trước động từ.","examples":[{"zh":"刚才的电话是我妈妈打来的。","py":"Gāngcái de diànhuà shì wǒ māma dǎlái de.","vi":"Cuộc điện thoại vừa nãy là mẹ tôi gọi đến.","hl":"刚才"},{"zh":"我刚刚看视频学会了包饺子。","py":"Wǒ gānggāng kàn shìpín xuéhuìle bāo jiǎozi.","vi":"Cháu vừa mới xem video học được cách gói sủi cảo.","hl":"刚刚"},{"zh":"他刚刚来北京两个月。","py":"Tā gānggāng lái Běijīng liǎng gè yuè.","vi":"Cậu ấy mới đến Bắc Kinh hai tháng.","hl":"刚刚"}],"struct":"刚才 (+ Chủ ngữ) + Động từ / 刚才的 + Danh từ | Chủ ngữ + 刚刚 + Động từ","note":"“刚才” có thể làm định ngữ (刚才的电话) và đứng đầu câu; “刚刚” chỉ làm trạng ngữ đứng sau chủ ngữ."},"g3":{"han":"条件复句“只要……，就……”","py":"Tiáojiàn fùjù “zhǐyào..., jiù...”","title":"Câu ghép điều kiện “只要……，就……”","explain":"“只要……，就……”中，“只要”后面是所需要的充分条件，有这个条件就能产生“就”后面的结果。主语可以放在“只要”前，也可以放在“只要”后。如果句子有两个主语，第二个主语要放在“就”前面。\nTrong câu ghép điều kiện “只要……，就……”, thành phần đứng sau “只要” biểu thị điều kiện đủ; chỉ cần có điều kiện này là có thể đạt được kết quả đứng sau “就”. Chủ ngữ có thể đặt trước hoặc sau “只要”. Trường hợp câu có hai chủ ngữ khác nhau, chủ ngữ thứ hai sẽ được đặt trước “就”.","examples":[{"zh":"我只要几天不跟他视频，就很想他。","py":"Wǒ zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","vi":"Cô chỉ cần vài ngày không gọi video cho nó là đã rất nhớ nó.","hl":"只要……，就……"},{"zh":"只要你同意，我们就这么决定了。","py":"Zhǐyào nǐ tóngyì, wǒmen jiù zhème juédìng le.","vi":"Chỉ cần bạn đồng ý thì chúng ta quyết định như vậy nhé.","hl":"只要……，……就……"},{"zh":"只要你坚持每天早睡，身体就一定会好起来。","py":"Zhǐyào nǐ jiānchí měitiān zǎoshuì, shēntǐ jiù yídìng huì hǎo qǐlái.","vi":"Chỉ cần bạn kiên trì đi ngủ sớm mỗi ngày, sức khoẻ nhất định sẽ tốt lên.","hl":"只要……，……就……"}],"struct":"只要 + Điều kiện đủ，+ (Chủ ngữ 2 +) 就 + Kết quả","note":"Phân biệt với “只有……，才……” (điều kiện duy nhất/cần)."},"g4":{"han":"固定格式“从……起”","py":"Gùdìng géshì “cóng... qǐ”","title":"Cấu trúc cố định “从……起”","explain":"固定格式“从……起”有“从……开始”的意思，多表示时间。常用在句首，作状语。\nCấu trúc cố định “从……起” mang ý nghĩa tương tự như “从……开始”, thường được đặt ở đầu câu, làm trạng ngữ, đa phần biểu thị thời gian.","examples":[{"zh":"他从那时起就努力学习。","py":"Tā cóng nà shí qǐ jiù nǔlì xuéxí.","vi":"Anh ấy từ lúc đó đã chăm chỉ học tập.","hl":"从那时起"},{"zh":"从那天起，我们就变成了好朋友。","py":"Cóng nà tiān qǐ, wǒmen jiù biànchéngle hǎo péngyou.","vi":"Kể từ ngày hôm đó, chúng tôi đã trở thành bạn tốt.","hl":"从那天起"},{"zh":"从那次旅游起，我对中国文化更有兴趣了。","py":"Cóng nà cì lǚyóu qǐ, wǒ duì Zhōngguó wénhuà gèng yǒu xìngqù le.","vi":"Kể từ chuyến du lịch đó, tôi càng có hứng thú với văn hoá Trung Quốc.","hl":"从那次旅游起"}],"struct":"从 + Mốc thời gian / Sự kiện + 起，+ Hành động / Trạng thái","note":"Biểu thị điểm khởi đầu về thời gian."}},"grammarQuiz":[{"id":"hsk3_b18_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 来中国几个月，还没在中国过过春节。","opts":[{"t":"刚","ok":true},{"t":"总","ok":false},{"t":"起","ok":false},{"t":"收","ok":false},{"t":"见面","ok":false}],"exp":"Đáp án A (刚): ‘Tôi mới đến Trung Quốc vài tháng, vẫn chưa từng đón Tết Nguyên đán ở Trung Quốc.’"},{"id":"hsk3_b18_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这是我给您和叔叔准备的小礼物，请您 (____) 下。","opts":[{"t":"收","ok":true},{"t":"刚","ok":false},{"t":"总","ok":false},{"t":"起","ok":false},{"t":"见面","ok":false}],"exp":"Đáp án D (收): ‘Đây là món quà nhỏ cháu chuẩn bị cho cô và chú, xin cô nhận cho.’"},{"id":"hsk3_b18_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"过年的时候，小孩子 (____) 会收到大人给的红包。","opts":[{"t":"总","ok":true},{"t":"刚","ok":false},{"t":"起","ok":false},{"t":"收","ok":false},{"t":"见面","ok":false}],"exp":"Đáp án B (总): ‘Vào dịp Tết, trẻ nhỏ luôn nhận được bao lì xì của người lớn.’"},{"id":"hsk3_b18_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"从上个月 (____)，妈妈就开始为春节做准备了。","opts":[{"t":"起","ok":true},{"t":"刚","ok":false},{"t":"总","ok":false},{"t":"收","ok":false},{"t":"见面","ok":false}],"exp":"Đáp án C (起): ‘Từ tháng trước, mẹ đã bắt đầu chuẩn bị cho Tết Nguyên đán rồi.’"},{"id":"hsk3_b18_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"春节的时候只要有时间，就一定要跟小时候的朋友们 (____)。","opts":[{"t":"见面","ok":true},{"t":"刚","ok":false},{"t":"总","ok":false},{"t":"起","ok":false},{"t":"收","ok":false}],"exp":"Đáp án E (见面): ‘Dịp Tết chỉ cần có thời gian thì nhất định phải gặp mặt bạn bè hồi nhỏ.’"},{"id":"hsk3_b18_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你想 (____) 过今年的春节？\nB: 我好几年没回爸爸妈妈家了，今年打算回去过节。","opts":[{"t":"怎样","ok":true},{"t":"完成","ok":false},{"t":"坚持","ok":false},{"t":"发生","ok":false},{"t":"大概","ok":false}],"exp":"Đáp án D (怎样): ‘Bạn định đón Tết Nguyên đán năm nay thế nào?’"},{"id":"hsk3_b18_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这一年 (____) 了很多开心的事。\nB: 希望明年更好，祝我们大家都新年快乐！","opts":[{"t":"发生","ok":true},{"t":"完成","ok":false},{"t":"坚持","ok":false},{"t":"怎样","ok":false},{"t":"大概","ok":false}],"exp":"Đáp án C (发生): ‘Một năm qua đã xảy ra rất nhiều chuyện vui vẻ.’"},{"id":"hsk3_b18_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你今年怎么过春节？\nB: 我回家住 (____) 三四天，然后出去旅游。","opts":[{"t":"大概","ok":true},{"t":"完成","ok":false},{"t":"坚持","ok":false},{"t":"发生","ok":false},{"t":"怎样","ok":false}],"exp":"Đáp án E (大概): ‘Mình về nhà ở khoảng ba bốn ngày, sau đó đi du lịch.’"},{"id":"hsk3_b18_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 快12点了，你是不是想睡觉了？\nB: 我一定要 (____) 到12点，新的一年开始以后再睡觉。","opts":[{"t":"坚持","ok":true},{"t":"完成","ok":false},{"t":"发生","ok":false},{"t":"怎样","ok":false},{"t":"大概","ok":false}],"exp":"Đáp án B (坚持): ‘Mình nhất định phải kiên trì thức tới 12 giờ, đợi năm mới bắt đầu rồi mới ngủ.’"},{"id":"hsk3_b18_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 新年就要到了，可是今年的目标还没 (____) 呢。\nB: 没关系，明年我们一起努力吧。","opts":[{"t":"完成","ok":true},{"t":"坚持","ok":false},{"t":"发生","ok":false},{"t":"怎样","ok":false},{"t":"大概","ok":false}],"exp":"Đáp án A (完成): ‘Năm mới sắp tới rồi, vậy mà mục tiêu năm nay vẫn chưa hoàn thành nữa.’"},{"id":"hsk3_b18_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月为什么很开心？","opts":[{"t":"C 可以在中国过春节","ok":true},{"t":"A 可以去北京","ok":false},{"t":"B 可以去李文家","ok":false}],"exp":"Bạch Gia Nguyệt nói ngay câu đầu: “我要在中国过年，真开心。”"},{"id":"hsk3_b18_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"中国人一般怎么过春节？","opts":[{"t":"C 跟家人一起过节","ok":true},{"t":"A 去朋友家过节","ok":false},{"t":"B 出去旅游过节","ok":false}],"exp":"Lý Văn nói: “我们一般会回家，跟家人一起过。”"},{"id":"hsk3_b18_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"白家月为什么去李文家？","opts":[{"t":"C 一起过年","ok":true},{"t":"A 送礼物","ok":false},{"t":"B 学包饺子","ok":false}],"exp":"Bạch Gia Nguyệt đến nhà Lý Văn chúc Tết và cùng gia đình anh đón Tết Nguyên đán."},{"id":"hsk3_b18_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文家今天晚上吃什么？","opts":[{"t":"A 饺子","ok":true},{"t":"B 包子","ok":false},{"t":"C 面条儿","ok":false}],"exp":"Cô Trương nói: “饺子很快就包好了。”"},{"id":"hsk3_b18_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月和李文妈妈在做什么？","opts":[{"t":"C 一起看照片","ok":true},{"t":"A 一起看电视","ok":false},{"t":"B 一起看视频","ok":false}],"exp":"Hai người cùng xem tấm ảnh chụp trước khi Lý Văn xuất ngoại tại sân bay Bắc Kinh."},{"id":"hsk3_b18_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"李文什么时候毕业？","opts":[{"t":"B 一个学期以后","ok":true},{"t":"A 一个月以后","ok":false},{"t":"C 三四年以后","ok":false}],"exp":"Bạch Gia Nguyệt nói: “还有最后一个学期就要毕业了，他很快就会回来了。”"},{"id":"hsk3_b18_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"白家月这次来中国，让她最高兴的事是什么？","opts":[{"t":"C 认识李文的父母","ok":true},{"t":"A 过春节","ok":false},{"t":"B 吃饺子","ok":false}],"exp":"Bài khóa 4: “这次来中国，我最高兴的是认识了李文的父母。”"},{"id":"hsk3_b18_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"在李文身上，白家月学到什么了？","opts":[{"t":"C 只要坚持努力，就能完成目标","ok":true},{"t":"A 如果想学医，就要努力学习","ok":false},{"t":"B 只有成绩好，才能出国留学","ok":false}],"exp":"Bài khóa 4: “在他身上，我懂得了，只要一直坚持，就能完成自己的目标。”"}],"chars":["怎","样","过","节","日","联","欢","大","概","春","阿","姨","叔","收","总","起","见","面","矿","泉","水","刚","出","发","不","久","生","只","要","学","期","毕","业","去","懂","得","坚","持","完","成","目","标","展","我","会","了","包","饺","子"],"rhyme":null,"notes":["Tổng kết học tập Bài 16–18 (trang 172–173): 12 điểm ngữ pháp gồm 一会儿……，一会儿……, 介词“关于”, 一般来说, 比较句(11) A比B+多/少/早/晚+动词+数量短语, 介词“向”, 不是……吗？, ……，更……, 只有……，才……, 概数表达法, “刚才”和“刚刚”, 只要……，就…… và 从……起.","Câu hỏi thảo luận Bài khóa 1: (1) 李文为什么很高兴？ (2) 李文和家人春节的时候会做什么？ (3) 春节大概放几天假？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月送礼物的时候说了什么？ (2) 李文的家人是怎么欢迎白家月的？ (3) 白家月想跟李文的家人一起做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 李文第一次出国留学，是从哪儿出发的？ (2) 李文全家的照片是什么时候照的？ (3) 李文刚离开家的时候，张阿姨怎么样？","Câu hỏi thảo luận Bài khóa 4: (1) 李文的父母给白家月看什么了？ (2) 白家月从李文的父母那里了解到什么了？ (3) 李文为什么能得到出国留学的机会？"],"workbook":null}};
